INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac62507-ef98-47a5-a05a-17a6a9dc16a3', '余所居平泉村舍近蒙韋常侍大尹特改嘉名因寄詩以謝', '余所居平泉村舍近蒙韋常侍大尹特改嘉名因寄诗以謝', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["未謝留侯疾，常懷仲蔚園。","閑謠紫芝曲，歸夢赤松村。","忽改蓬蒿色，俄吹黍谷暄。","多慙孔北海，傳教及衡門。"]', '["未謝留侯疾，常懷仲蔚园。","闲謠紫芝曲，归梦赤松村。","忽改蓬蒿色，俄吹黍谷暄。","多慙孔北海，傳教及衡门。"]', '诗', 'shi', '', NULL, '余所居平泉村舍近蒙韋常侍大尹特改嘉名因寄詩以謝 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aa27f6a-e4f2-4cc6-ad53-a41d7d552b57', '山信至說平泉別墅草木滋長地轉幽深悵然思歸復此作', '山信至说平泉別墅草木滋长地轉幽深悵然思归复此作', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["忽聞樵客語，暫慰野人心。","幽徑芳蘭密，閑庭秀木深。","麕䴥來澗底，鳧鵠遍川潯。","誰念滄溟上，歸歟起歎音。"]', '["忽闻樵客語，暫慰野人心。","幽徑芳蘭密，闲庭秀木深。","麕䴥来澗底，鳧鵠遍川潯。","誰念滄溟上，归歟起歎音。"]', '诗', 'shi', '', NULL, '山信至說平泉別墅草木滋長地轉幽深悵然思歸復此作 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c376716e-14a2-4ef3-99eb-f6ab69daff67', '臨海太守惠予赤城石報以是詩', '臨海太守惠予赤城石報以是诗', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["聞君採奇石，剪斷赤城霞。","潭上倒虹影，波中搖日華。","仙巖接絳氣，谿路雜桃花。","若值客星去，便應隨海槎。"]', '["闻君採奇石，剪斷赤城霞。","潭上倒虹影，波中搖日华。","仙巖接絳氣，谿路杂桃花。","若值客星去，便應隨海槎。"]', '诗', 'shi', '', NULL, '臨海太守惠予赤城石報以是詩 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d23c60b-3b57-42b4-89b8-09d75abcf2d7', '上巳憶江南禊事', '上巳憶江南禊事', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["黃河西繞郡城流，上巳應無祓禊遊。","爲憶淥江春水色，更無宵夢向吳州。"]', '["黄河西繞郡城流，上巳應無祓禊游。","爲憶淥江春水色，更無宵梦向吳州。"]', '诗', 'shi', '', NULL, '上巳憶江南禊事 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('158a48fd-893a-4adb-a193-4d769711bf6b', '北固懷古', '北固懷古', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["自有此山川，於今幾太守。","近世二千石，畢公宣化厚。","丞相量納川，平陽氣衝斗。","三賢若時雨，所至躋仁壽。"]', '["自有此山川，於今幾太守。","近世二千石，畢公宣化厚。","丞相量納川，平陽氣衝斗。","三賢若时雨，所至躋仁壽。"]', '诗', 'shi', '', NULL, '北固懷古 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57c0cd57-397e-4054-86d7-24b6a6842efa', '汨羅', '汨羅', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["遠謫南荒一病身，停舟暫弔汨羅人。","都緣靳尚圖專國，豈是懷王厭直臣。","萬里碧潭秋景靜，四時愁色野花新。","不勞漁父重相問，自有招魂拭淚巾。"]', '["远謫南荒一病身，停舟暫弔汨羅人。","都緣靳尚圖專国，豈是懷王厭直臣。","万里碧潭秋景静，四时愁色野花新。","不勞漁父重相问，自有招魂拭泪巾。"]', '诗', 'shi', '', NULL, '汨羅 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a98dc8fa-b3c5-4d0b-94c7-ad13ade4ccb8', '嶺外守歲', '嶺外守歲', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["冬逐更籌盡，春隨斗柄回。","寒暄一夜隔，客鬢兩年催。"]', '["冬逐更籌尽，春隨斗柄回。","寒暄一夜隔，客鬢兩年催。"]', '诗', 'shi', '', NULL, '嶺外守歲 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e87a58e-fce7-4ef4-9d68-26b7cb3985ec', '記韋楚老不遇', '記韋楚老不遇', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["昔日徵黃綺，余慚在鳳池。","今來招隱士，恨不見瓊枝。"]', '["昔日徵黄綺，余慚在鳳池。","今来招隐士，恨不见瓊枝。"]', '诗', 'shi', '', NULL, '記韋楚老不遇 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('137687e4-9cf2-4f1b-a168-214b6a568f8a', '題柳郎中故居', '題柳郎中故居', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["下馬荒堦日欲曛，潺潺石溜靜中聞。","鳥啼花發人聲絕，寂寞山窗掩白雲。"]', '["下马荒堦日欲曛，潺潺石溜静中闻。","鸟啼花發人声絕，寂寞山窗掩白云。"]', '诗', 'shi', '', NULL, '題柳郎中故居 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41c4e91e-fdc9-4eae-b04c-f0a8a9b40c26', '盤陀嶺驛樓', '盤陀嶺驛楼', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["嵩少心期杳莫攀，好山聊復一開顏。","明朝便是南荒路，更上層樓望故關。"]', '["嵩少心期杳莫攀，好山聊复一开顏。","明朝便是南荒路，更上層楼望故关。"]', '诗', 'shi', '', NULL, '盤陀嶺驛樓 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d7069b-c2af-4350-ad52-41bc0b927b49', '句', '句', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["檢經求綠字，憑酒借紅顏。","君不見秋山寂歷風飆歇，半夜青崖吐明月。","寒光乍出松篠間，萬籟蕭蕭從此發。","忽聞歌管吟朔風，精魂想在幽巖中。","銀花懸院榜，神撼引鈴縧。","葳蕤輕風裏，若銜若垂何可擬。","自從一夢高唐後，可是無人勝楚王。","牛羊具特俎，心悟覺身勞。","雲中棄寶刀，久閑生䏶肉。","多壽長眉毫，書空蹺足睡。","路險側身行，誰家幼女敲筯歌。","何處丁妻點燈織，魚蝦集橘市。","休咎占人甲，挨持見天丁。","洛下推年少，山東許地高。","世上文章士，誰爲第一人。","老生誇隱拙，時輩毀尖新。","𭲟濴寒深百尺，奇觚率爾操。","諷諫欣然納。"]', '["檢經求綠字，憑酒借紅顏。","君不见秋山寂歷风飆歇，半夜青崖吐明月。","寒光乍出松篠间，万籟蕭蕭從此發。","忽闻歌管吟朔风，精魂想在幽巖中。","銀花懸院榜，神撼引鈴縧。","葳蕤轻风裏，若銜若垂何可擬。","自從一梦高唐後，可是無人勝楚王。","牛羊具特俎，心悟覺身勞。","云中棄寶刀，久闲生䏶肉。","多壽长眉毫，书空蹺足睡。","路險側身行，誰家幼女敲筯歌。","何处丁妻点灯织，鱼蝦集橘市。","休咎占人甲，挨持见天丁。","洛下推年少，山东許地高。","世上文章士，誰爲第一人。","老生誇隐拙，时輩毀尖新。","𭲟濴寒深百尺，奇觚率爾操。","諷諫欣然納。"]', '诗', 'shi', '', NULL, '句 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a854bf0-ae31-49a9-9dbc-caf2a34eb461', '至日荷李常侍過郊居', '至日荷李常侍過郊居', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["賤子守柴荆，誰人記姓名。","風雲千騎降，草木一陽生。","禮異江河動，歡殊里巷驚。","稱觴容侍坐，看竹許同行。","遇覺滄溟淺，恩疑太嶽輕。","盡搜天地物，無諭此時情。"]', '["賤子守柴荆，誰人記姓名。","风云千騎降，草木一陽生。","禮異江河动，歡殊里巷驚。","稱觴容侍坐，看竹許同行。","遇覺滄溟淺，恩疑太嶽轻。","尽搜天地物，無諭此时情。"]', '诗', 'shi', '', NULL, '至日荷李常侍過郊居 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e2ca2f-9094-4b19-a87a-23b411269a9f', '日暮天無雲', '日暮天無云', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["杳杳復蒼然，無雲日暮天。","象分青氣外，景盡赤霄前。","漸吐星河色，遙生水木煙。","從容難附麗，顧步欲澄鮮。","但見收三素，何能測上玄。","應非暫呈瑞，不許出山川。"]', '["杳杳复蒼然，無云日暮天。","象分青氣外，景尽赤霄前。","漸吐星河色，遙生水木煙。","從容难附丽，顧步欲澄鲜。","但见收三素，何能測上玄。","應非暫呈瑞，不許出山川。"]', '诗', 'shi', '', NULL, '日暮天無雲 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46ace8a4-b7d0-482d-99c2-3d06a2309379', '新成小亭月夜', '新成小亭月夜', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["已被月知處，斬新風到來。","無人伴幽境，多取木蘭栽。"]', '["已被月知处，斬新风到来。","無人伴幽境，多取木蘭栽。"]', '诗', 'shi', '', NULL, '新成小亭月夜 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6cbbb7-bb2b-44fc-9872-de4caa63bf40', '和竇中丞歲酒喜見小男兩歲', '和竇中丞歲酒喜见小男兩歲', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["更添十歲應爲相，歲酒從今把未休。","聞得一毛添五色，眼看相逐鳳池頭。"]', '["更添十歲應爲相，歲酒從今把未休。","闻得一毛添五色，眼看相逐鳳池头。"]', '诗', 'shi', '', NULL, '和竇中丞歲酒喜見小男兩歲 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3eb132b-a28e-4818-8365-8108de95eb53', '寒食', '寒食', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["東風潑火雨新休，舁盡春泥掃雪溝。","走馬犢車當御路，漢陽公主謝雞毬。"]', '["东风潑火雨新休，舁尽春泥掃雪溝。","走马犢车當御路，漢陽公主謝雞毬。"]', '诗', 'shi', '', NULL, '寒食 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac4bc63-1f26-43ca-ae56-a1e19183ae21', '送僧遊山', '送僧游山', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["雲身自在山山去，何處靈山不是歸？日暮寒林投古寺，雪花飛滿水田衣。"]', '["云身自在山山去，何处靈山不是归？日暮寒林投古寺，雪花飞满水田衣。"]', '诗', 'shi', '', NULL, '送僧遊山 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af75cd78-0728-47b7-bada-4d86c17246ba', '雪中荅僧書', '雪中荅僧书', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["八行銀字非常草，六出天花盡是梅。","無所與陳童子別，雪中辛苦遠山來。"]', '["八行銀字非常草，六出天花尽是梅。","無所與陳童子別，雪中辛苦远山来。"]', '诗', 'shi', '', NULL, '雪中荅僧書 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('425c8711-eba2-4dc9-b5c3-63551e442509', '題逍遙樓傷故韋大夫', '題逍遙楼傷故韋大夫', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["利及生人無更爲，落花流水舊城池。","逍遙樓上雕龍字，便是羊公墮淚碑。"]', '["利及生人無更爲，落花流水旧城池。","逍遙楼上雕龙字，便是羊公墮泪碑。"]', '诗', 'shi', '', NULL, '題逍遙樓傷故韋大夫 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d1cab24-322f-4541-83cd-3989e646218e', '戲贈費冠卿', '戲贈費冠卿', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["但恐紅塵虛白首，寧論蹇逸分先後。","莫占鶯花笑寂寥，長安春色年年有。"]', '["但恐紅塵虛白首，寧論蹇逸分先後。","莫占鶯花笑寂寥，长安春色年年有。"]', '诗', 'shi', '', NULL, '戲贈費冠卿 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3a9e265-1ee6-41cb-93ea-97c926a08426', '與左興宗湓城別', '與左兴宗湓城別', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["江逢九派人將別，猨到三聲月爲秋。","不知相見更何日，此夜少年堪白頭。"]', '["江逢九派人將別，猨到三声月爲秋。","不知相见更何日，此夜少年堪白头。"]', '诗', 'shi', '', NULL, '與左興宗湓城別 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3be54319-2e12-4990-90b4-18fe94de3517', '八月十五夜臥疾', '八月十五夜臥疾', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["一年秪有今宵月，盡上江樓獨病眠。","寂寞竹窗閑不閉，夜深斜影到牀前。"]', '["一年秪有今宵月，尽上江楼独病眠。","寂寞竹窗闲不閉，夜深斜影到牀前。"]', '诗', 'shi', '', NULL, '八月十五夜臥疾 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eeef00c-d99d-4f78-8d1b-e68dda63d885', '正月十五日', '正月十五日', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["漢家遺事今宵見，楚郭明燈幾處張。","深夜行歌聲絕後，紫姑神下月蒼蒼。"]', '["漢家遺事今宵见，楚郭明灯幾处張。","深夜行歌声絕後，紫姑神下月蒼蒼。"]', '诗', 'shi', '', NULL, '正月十五日 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea08d350-3d1f-46a0-934f-3dffd9c5df36', '曲池陪宴即事上竇中丞', '曲池陪宴即事上竇中丞', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["水自山阿繞坐來，珊瑚臺上木綿開。","欲知舉目無情罰，一片花流酒一杯。"]', '["水自山阿繞坐来，珊瑚台上木綿开。","欲知舉目無情罰，一片花流酒一杯。"]', '诗', 'shi', '', NULL, '曲池陪宴即事上竇中丞 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc4163c1-1ab3-4d39-a2ac-1edc318d82f9', '董監廟', '董監廟', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["仁傑淫祠廢欲無，枯楓老櫟兩三株。","神烏慣得商人食，飛趂征帆過蠡湖。"]', '["仁傑淫祠廢欲無，枯楓老櫟兩三株。","神烏慣得商人食，飞趂征帆過蠡湖。"]', '诗', 'shi', '', NULL, '董監廟 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('940eed81-f316-4ce4-91ec-6133b3dc0053', '贈侯山人', '贈侯山人', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["一見清容愜素聞，有人傳是紫陽君。","來時玉女裁春服，翦破湘山幾片雲。"]', '["一见清容愜素闻，有人傳是紫陽君。","来时玉女裁春服，翦破湘山幾片云。"]', '诗', 'shi', '', NULL, '贈侯山人 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ae0d493-0303-4bad-8e1e-47618616b9a0', '送馬判官赴安南', '送马判官赴安南', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["故人交趾去從軍，應笑狂生揮陣雲。","省得蔡州今日事，舊曾都護帳前聞。"]', '["故人交趾去從軍，應笑狂生揮陣云。","省得蔡州今日事，旧曾都護帳前闻。"]', '诗', 'shi', '', NULL, '送馬判官赴安南 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e1a37f4-5102-43bd-a77c-564a8c009ca4', '送準上人歸石經院', '送準上人归石經院', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["旃檀刻像今猶少，白石鐫經古未曾。","歸去更尋翻譯寺，前山應遇鴈門僧。"]', '["旃檀刻像今猶少，白石鐫經古未曾。","归去更尋翻譯寺，前山應遇鴈门僧。"]', '诗', 'shi', '', NULL, '送準上人歸石經院 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86979e4a-c861-428f-b333-b4f4a82f4f6d', '寒食野望', '寒食野望', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["拜掃無過骨肉親，一年唯此兩三辰。","冢頭莫種有花樹，春色不關泉下人。"]', '["拜掃無過骨肉親，一年唯此兩三辰。","冢头莫種有花樹，春色不关泉下人。"]', '诗', 'shi', '', NULL, '寒食野望 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e371811-fcc1-4621-b150-a16b614468b9', '祗役遇風謝湘中春色', '祗役遇风謝湘中春色', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["水生風熟布帆新，只見公程不見春。","應被百花撩亂笑，比來天地一閑人。"]', '["水生风熟布帆新，只见公程不见春。","應被百花撩亂笑，比来天地一闲人。"]', '诗', 'shi', '', NULL, '祗役遇風謝湘中春色 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dce9802-f272-4056-8b28-2726e55f5ade', '湘江夜泛', '湘江夜泛', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["江流如箭月如弓，行盡三湘數夜中。","無那子規知向蜀，一聲聲似怨春風。"]', '["江流如箭月如弓，行尽三湘數夜中。","無那子規知向蜀，一声声似怨春风。"]', '诗', 'shi', '', NULL, '湘江夜泛 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c219c5-cf2c-46c5-b680-4b2d201ce577', '蜀江水', '蜀江水', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["日夜朝宗來萬里，共憐江水引蕃心。","若論巴峽愁人處，猨比灘聲是好音。"]', '["日夜朝宗来万里，共怜江水引蕃心。","若論巴峽愁人处，猨比灘声是好音。"]', '诗', 'shi', '', NULL, '蜀江水 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('017629b3-5b29-49b9-9f83-86feb3a7ff00', '寄安南馬中丞', '寄安南马中丞', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["龍韜能致虎符分，萬里霜臺壓瘴雲。","蕃客不須愁海路，波神今伏馬將軍。"]', '["龙韜能致虎符分，万里霜台壓瘴云。","蕃客不須愁海路，波神今伏马將軍。"]', '诗', 'shi', '', NULL, '寄安南馬中丞 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec75a12e-606e-460c-8d3d-859e2a583bda', '甘子堂陪宴上韋大夫', '甘子堂陪宴上韋大夫', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["武陵樓上春長早，甘子堂前花落遲。","楚樂怪來聲競起，新歌盡是大夫詞。"]', '["武陵楼上春长早，甘子堂前花落遲。","楚乐怪来声競起，新歌尽是大夫词。"]', '诗', 'shi', '', NULL, '甘子堂陪宴上韋大夫 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c64f0074-8f80-4839-82aa-54895e242fdb', '青溪村居二首 一', '青溪村居二首 一', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["家占溪南千箇竹，地臨湖上一羣山。","漁船多在馬長放，出處自由閑不閑。"]', '["家占溪南千箇竹，地臨湖上一羣山。","漁船多在马长放，出处自由闲不闲。"]', '诗', 'shi', '', NULL, '青溪村居二首 一 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e95aa1-77e2-4d4c-8f5d-9a1c3ac65d67', '青溪村居二首 二', '青溪村居二首 二', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["深樹黃[鸝]曉一聲，林西江上月猶明。","野人早起無他事，貪繞沙泉看笋生。"]', '["深樹黄[鸝]晓一声，林西江上月猶明。","野人早起無他事，貪繞沙泉看笋生。"]', '诗', 'shi', '', NULL, '青溪村居二首 二 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('843a96bd-6aa8-43bc-b0ca-c6d2f25693ec', '奉和興元鄭相公早春送楊侍郎', '奉和兴元鄭相公早春送楊侍郎', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["征鞍欲上醉還留，南浦春生百草頭。","丞相新裁別離曲，聲聲飛出舊梁州。"]', '["征鞍欲上醉還留，南浦春生百草头。","丞相新裁別離曲，声声飞出旧梁州。"]', '诗', 'shi', '', NULL, '奉和興元鄭相公早春送楊侍郎 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9522d29d-f489-4b7f-ba58-d741b60a2f12', '送舍弟孺復往廬山', '送舍弟孺复往廬山', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["能騎竹馬辨西東，未省煙花暫不同。","第一早歸春欲盡，廬山好看過湖風。"]', '["能騎竹马辨西东，未省煙花暫不同。","第一早归春欲尽，廬山好看過湖风。"]', '诗', 'shi', '', NULL, '送舍弟孺復往廬山 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb4b2fc0-ce53-4570-8f10-6c6b71ee6cac', '野別留少微上人', '野別留少微上人', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["若爲相見還分散，翻覺浮雲亦不閑。","何處留師暫且住，家貧唯有坐中山。"]', '["若爲相见還分散，翻覺浮云亦不闲。","何处留師暫且住，家貧唯有坐中山。"]', '诗', 'shi', '', NULL, '野別留少微上人 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f680d452-eee6-47f9-91e5-58d07bff29de', '經古墓', '經古墓', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["碑折松枯山火燒，夜臺從閉不曾朝。","那將逝者比流水，流水東流逢上潮。"]', '["碑折松枯山火燒，夜台從閉不曾朝。","那將逝者比流水，流水东流逢上潮。"]', '诗', 'shi', '', NULL, '經古墓 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4f2dfe-b4cb-41f7-993c-ac415ea11f4b', '贈靈徹上人', '贈靈徹上人', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["詩句能生世界春，僧家更有姓湯人。","況聞暗憶前朝事，知是修行第幾身。"]', '["诗句能生世界春，僧家更有姓湯人。","況闻暗憶前朝事，知是修行第幾身。"]', '诗', 'shi', '', NULL, '贈靈徹上人 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8995d335-d4de-40ac-9e2a-e37db1d5cd91', '春郊醉中贈章八元', '春郊醉中贈章八元', '3864aca8-400c-4d7a-90dd-41c5b177ce0b', '唐', '["三月踏青能幾日，百回添酒莫辭頻。","看君到臥楊花裏，始覺春光爲醉人。"]', '["三月踏青能幾日，百回添酒莫辞頻。","看君到臥楊花裏，始覺春光爲醉人。"]', '诗', 'shi', '', NULL, '春郊醉中贈章八元 熊孺登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dd55a4b-9489-4fb8-a948-3e5550372f6f', '懷古', '懷古', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["尼父未適魯，屢屢倦迷津。","徒懷教化心，紆鬱不能伸。","一遇知己言，萬方始喧喧。","至今百王則，孰不挹其源。"]', '["尼父未適魯，屢屢倦迷津。","徒懷教化心，紆鬱不能伸。","一遇知己言，万方始喧喧。","至今百王則，孰不挹其源。"]', '诗', 'shi', '', NULL, '懷古 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b098ed67-25f5-43e3-ab71-d3ebec7caa1a', '詠古', '詠古', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["大智思濟物，道行心始休。","垂綸自消息，歲月任春秋。","紂虐武既賢，風雲固可求。","順天行殺機，所向協良謀。","況以丈人師，將濟安川流。","何勞問枯骨，再取陰陽籌。","霸國不務仁，兵戈恣相酬。","空令渭水迹，千古獨悠悠。"]', '["大智思濟物，道行心始休。","垂綸自消息，歲月任春秋。","紂虐武既賢，风云固可求。","順天行殺機，所向協良謀。","況以丈人師，將濟安川流。","何勞问枯骨，再取陰陽籌。","霸国不務仁，兵戈恣相酬。","空令渭水迹，千古独悠悠。"]', '诗', 'shi', '', NULL, '詠古 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4f0ec0-15a2-405b-a0c0-b29328a660a1', '題清溪鬼谷先生舊居', '題清溪鬼谷先生旧居', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["翠壁開天池，青崖列雲樹。","冰容不可狀，杳若清河霧。","常聞先生教，指示秦儀路。","二子才不同，逞詞過尺度。","偶因從吏役，遠到冥棲處。","松月想舊山，煙霞了如故。","未遑鍊金鼎，日覺容光暮。","萬慮隨境生，何由返真素。","寂寞天籟息，清逈鳥聲曙。","迴首望重重，無期挹風馭。"]', '["翠壁开天池，青崖列云樹。","冰容不可狀，杳若清河霧。","常闻先生教，指示秦儀路。","二子才不同，逞词過尺度。","偶因從吏役，远到冥棲处。","松月想旧山，煙霞了如故。","未遑鍊金鼎，日覺容光暮。","万慮隨境生，何由返真素。","寂寞天籟息，清逈鸟声曙。","迴首望重重，無期挹风馭。"]', '诗', 'shi', '', NULL, '題清溪鬼谷先生舊居 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('343c239c-b223-409d-a7c8-39adbeda60ce', '感興', '感兴', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["隋氏造宮闕，峨峨倚雲煙。","搜奇竭四海，立制謀千年。","秦兵半夜來，烈火焚高臺。","萬人聚筋血，一旦爲塵埃。","君看汴河路，尚說隋家柳。","但問哭陵人，秋草沒來久。"]', '["隋氏造宮闕，峨峨倚云煙。","搜奇竭四海，立制謀千年。","秦兵半夜来，烈火焚高台。","万人聚筋血，一旦爲塵埃。","君看汴河路，尚说隋家柳。","但问哭陵人，秋草沒来久。"]', '诗', 'shi', '', NULL, '感興 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c71c6d07-b995-45d0-8a4c-6e52d666025b', '鷓鴣詞二首 一', '鷓鴣词二首 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["湘江煙水深，沙岸隔楓林。","何處鷓鴣飛，日斜斑竹陰。","二女空垂淚，三閭枉自沉。","惟有鷓鴣啼，獨傷行客心。"]', '["湘江煙水深，沙岸隔楓林。","何处鷓鴣飞，日斜斑竹陰。","二女空垂泪，三閭枉自沉。","惟有鷓鴣啼，独傷行客心。"]', '诗', 'shi', '', NULL, '鷓鴣詞二首 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad840d0b-010c-4354-8102-23ff0d3a9a57', '鷓鴣詞二首 二', '鷓鴣词二首 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["越岡連越井，越鳥更南飛。","何處鷓鴣啼，夕煙東嶺歸。","嶺外行人少，天涯北客稀。","鷓鴣啼別處，相對淚沾衣。"]', '["越岡連越井，越鸟更南飞。","何处鷓鴣啼，夕煙东嶺归。","嶺外行人少，天涯北客稀。","鷓鴣啼別处，相对泪沾衣。"]', '诗', 'shi', '', NULL, '鷓鴣詞二首 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b5ccf33-1111-4a85-83e3-2f8c2dfee85c', '山中', '山中', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["無奈牧童何，放牛喫我竹。","隔林呼不譍，呌笑如生鹿。","欲報田舍翁，更深不歸屋。"]', '["無奈牧童何，放牛喫我竹。","隔林呼不譍，呌笑如生鹿。","欲報田舍翁，更深不归屋。"]', '诗', 'shi', '', NULL, '山中 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b11b4329-af6c-4005-9a6b-889ead1d6a62', '寄荆娘寫真', '寄荆娘寫真', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["章華臺南莎草齊，長河柳色連金堤。","青樓曈曨曙光蚤，梨花滿巷鶯新啼。","章臺玉顏年十六，小來能唱西梁曲。","教坊大使久知名，郢上詞人歌不足。","少年才子心相許，夜夜高堂夢雲雨。","五銖香帔結同心，三寸紅牋替傳語。","緣池並戲雙鴛鴦，田田翠葉紅蓮香。","百年恩愛兩相許，一夕不見生愁腸。","上清仙女徵遊伴，欲從湘靈住河漢。","只愁陵谷變人寰，空歎桑田歸海岸。","願分精魄定形影，永似銀壺挂金井。","召得丹青絕世工，寫真與身真相同。","忽然相對兩不語，疑是妝成來鏡中。","豈期人願天不違，雲軿却駐從山歸。","畫圖封裹寄箱篋，洞房豔豔生光輝。","良人翻作東飛翼，却遣江頭問消息。","經年不得一封書，翠幕雲屏遶空壁。","結客有少年，名總身姓江。","征帆三千里，前月發豫章。","知我別時言，識我馬上郎。","恨無羽翼飛，使我徒怨滄波長。","開篋取畫圖，寄我形影與客將。","如今憔悴不相似，恐君重見生悲傷。","蒼梧九疑在何處，斑斑竹淚連瀟湘。"]', '["章华台南莎草齊，长河柳色連金堤。","青楼曈曨曙光蚤，梨花满巷鶯新啼。","章台玉顏年十六，小来能唱西梁曲。","教坊大使久知名，郢上词人歌不足。","少年才子心相許，夜夜高堂梦云雨。","五銖香帔結同心，三寸紅牋替傳語。","緣池並戲雙鴛鴦，田田翠葉紅蓮香。","百年恩愛兩相許，一夕不见生愁腸。","上清仙女徵游伴，欲從湘靈住河漢。","只愁陵谷变人寰，空歎桑田归海岸。","願分精魄定形影，永似銀壺挂金井。","召得丹青絕世工，寫真與身真相同。","忽然相对兩不語，疑是妝成来镜中。","豈期人願天不違，云軿却駐從山归。","畫圖封裹寄箱篋，洞房豔豔生光輝。","良人翻作东飞翼，却遣江头问消息。","經年不得一封书，翠幕云屏遶空壁。","結客有少年，名總身姓江。","征帆三千里，前月發豫章。","知我別时言，識我马上郎。","恨無羽翼飞，使我徒怨滄波长。","开篋取畫圖，寄我形影與客將。","如今憔悴不相似，恐君重见生悲傷。","蒼梧九疑在何处，斑斑竹泪連瀟湘。"]', '诗', 'shi', '', NULL, '寄荆娘寫真 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88882037-a112-4b54-b424-93fe286f92bf', '與弟渤新羅劒歌', '與弟渤新羅劒歌', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["我有神劒異人與，暗中往往精靈語。","識者知從東海來，來時一夜因風雨。","長河臨曉北斗殘，秋水露背青螭寒。","昨夜大梁城下宿，不借𨁂跌光顏看。","刃邊颯颯塵沙缺，瘢痕半是蛟龍血。","雷煥張華久已無，沉冤知向何人說。","我有愛弟都九江，一條直氣今無雙。","青光好去莫惆悵，必斬長鯨須少壯。"]', '["我有神劒異人與，暗中往往精靈語。","識者知從东海来，来时一夜因风雨。","长河臨晓北斗殘，秋水露背青螭寒。","昨夜大梁城下宿，不借𨁂跌光顏看。","刃邊颯颯塵沙缺，瘢痕半是蛟龙血。","雷煥張华久已無，沉冤知向何人说。","我有愛弟都九江，一條直氣今無雙。","青光好去莫惆悵，必斬长鯨須少壯。"]', '诗', 'shi', '', NULL, '與弟渤新羅劒歌 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('145c6cc3-53ec-43b1-8162-290f3fe73e95', '六歎 一', '六歎 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["綺羅香風翡翠車，清明獨傍芙蓉渠。","上有雲鬟洞仙女，垂羅掩縠煙中語。","風月頻驚桃李時，滄波久別鴛鴻侶。","欲傳一札孤飛翼，山長水遠無消息。","却鎖重門一院深，半夜空庭明月色。"]', '["綺羅香风翡翠车，清明独傍芙蓉渠。","上有云鬟洞仙女，垂羅掩縠煙中語。","风月頻驚桃李时，滄波久別鴛鴻侶。","欲傳一札孤飞翼，山长水远無消息。","却鎖重门一院深，半夜空庭明月色。"]', '诗', 'shi', '', NULL, '六歎 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3724d7b6-b2a4-4325-9adb-ab513afbed22', '六歎 二', '六歎 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["深院梧桐夾金井，上有轆轤青絲索。","美人清晝汲寒泉，寒泉欲上銀缾落。","迢迢碧甃千餘尺，竟日倚闌空歎息。","惆悵不來照明鏡，却掩洞房抱寂寂。"]', '["深院梧桐夾金井，上有轆轤青絲索。","美人清晝汲寒泉，寒泉欲上銀缾落。","迢迢碧甃千餘尺，竟日倚闌空歎息。","惆悵不来照明镜，却掩洞房抱寂寂。"]', '诗', 'shi', '', NULL, '六歎 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09e35871-4478-4c35-ac32-81e401b05360', '六歎 三', '六歎 三', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["漢臣一沒丁零塞，牧羊西過陰沙外。","朝憑南鴈信難回，夜望北辰心獨在。","漢家茅土橫九州，高門長戟封王侯。","但將鐘鼓悅私愛，肯以犬羊爲國羞。","夜宿寒雲臥冰雪，嚴風觸刃垂旌節。","丁年奉使白頭歸，泣盡李陵衣上血。"]', '["漢臣一沒丁零塞，牧羊西過陰沙外。","朝憑南鴈信难回，夜望北辰心独在。","漢家茅土橫九州，高门长戟封王侯。","但將鐘鼓悅私愛，肯以犬羊爲国羞。","夜宿寒云臥冰雪，嚴风觸刃垂旌節。","丁年奉使白头归，泣尽李陵衣上血。"]', '诗', 'shi', '', NULL, '六歎 三 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2492153c-d2ed-4dae-a398-248f53e1c711', '春山三朅來 一', '春山三朅来 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["釣魚朅來春日暖，沿溪不厭舟行緩。","野竹初栽碧玉長，澄潭欲下青絲短。","昔人避世兼避讐，暮棲雲外朝悠悠。","我今無事亦如此，赤鯉忽到長竿頭。","汎汎隨波凡幾里，碧莎如煙沙似砥。","瘦壁橫空怪石危，山花鬬日禽爭水。","有時帶月歸扣舷，身閑自是漁家仙。"]', '["釣鱼朅来春日暖，沿溪不厭舟行緩。","野竹初栽碧玉长，澄潭欲下青絲短。","昔人避世兼避讐，暮棲云外朝悠悠。","我今無事亦如此，赤鯉忽到长竿头。","汎汎隨波凡幾里，碧莎如煙沙似砥。","瘦壁橫空怪石危，山花鬬日禽爭水。","有时带月归扣舷，身闲自是漁家仙。"]', '诗', 'shi', '', NULL, '春山三朅來 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c09f945-fce3-481d-abfb-8e29b13e70b6', '春山三朅來 二', '春山三朅来 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["山上朅來採新茗，新花亂發前山頂。","瓊英動搖鍾乳碧，業業高下隨崖嶺。","未必蓬萊有仙藥，能向鼎中雲漠漠。","越甌遙見裂鼻香，欲覺身輕騎白鶴。"]', '["山上朅来採新茗，新花亂發前山頂。","瓊英动搖鍾乳碧，業業高下隨崖嶺。","未必蓬萊有仙藥，能向鼎中云漠漠。","越甌遙见裂鼻香，欲覺身轻騎白鹤。"]', '诗', 'shi', '', NULL, '春山三朅來 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b68143da-8bbd-4bb7-8989-fde18ff51aa9', '春山三朅來 三', '春山三朅来 三', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["採藥朅來藥苗盛，藥生只傍行人徑。","世人重耳不重目，指似藥苗心不足。","野客住山三十載，妻兒共寄浮雲外。","小男學語便分別，已辯君臣知匹配。","都市廣長開大鋪，疾來求者多相悞。","見說韓康舊姓名，識之不識先相怒。"]', '["採藥朅来藥苗盛，藥生只傍行人徑。","世人重耳不重目，指似藥苗心不足。","野客住山三十載，妻兒共寄浮云外。","小男学語便分別，已辯君臣知匹配。","都市廣长开大鋪，疾来求者多相悞。","见说韓康旧姓名，識之不識先相怒。"]', '诗', 'shi', '', NULL, '春山三朅來 三 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ff463a1-0105-4abb-a798-d6583a427af0', '牧童詞', '牧童词', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["朝牧牛，牧牛下江曲。","夜牧牛，牧牛度村谷。","荷蓑出林春雨細，蘆管臥吹莎草綠。","亂插蓬蒿箭滿腰，不怕猛虎欺黃犢。"]', '["朝牧牛，牧牛下江曲。","夜牧牛，牧牛度村谷。","荷蓑出林春雨細，蘆管臥吹莎草綠。","亂插蓬蒿箭满腰，不怕猛虎欺黄犢。"]', '诗', 'shi', '', NULL, '牧童詞 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb2b7ed7-2003-4c2d-a0f1-ca154b7db0ce', '醉中贈崔膺', '醉中贈崔膺', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["與君兄弟匡嶺故，與君相逢揚子渡。","白浪南分吳塞雲，綠楊深入隋宮路。","隋家文物今雖改，舞館歌臺基尚在。","煬帝陵邊草木深，汴河流水空歸海。","古今悠悠人自別，此地繁華終未歇。","大道青樓夾翠煙，瓊墀繡帳開明月。","與君一言兩相許，外捨形骸中爾女。","揚州歌酒不可追，洛神映箔湘妃語。","白馬黃金爲身置，誰能獨羨他人醉。","暫到香爐一夕間，能展愁眉百世事。","君看白日光如箭，一度別來顏色變。","早謀侯印佩腰間，莫遣看花鬢如霰。"]', '["與君兄弟匡嶺故，與君相逢揚子渡。","白浪南分吳塞云，綠楊深入隋宮路。","隋家文物今雖改，舞館歌台基尚在。","煬帝陵邊草木深，汴河流水空归海。","古今悠悠人自別，此地繁华終未歇。","大道青楼夾翠煙，瓊墀繡帳开明月。","與君一言兩相許，外捨形骸中爾女。","揚州歌酒不可追，洛神映箔湘妃語。","白马黄金爲身置，誰能独羨他人醉。","暫到香爐一夕间，能展愁眉百世事。","君看白日光如箭，一度別来顏色变。","早謀侯印佩腰间，莫遣看花鬢如霰。"]', '诗', 'shi', '', NULL, '醉中贈崔膺 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fead2d67-502b-4d65-9654-91184c8bb0e6', '岳陽別張[祜]', '岳陽別張[祜]', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["十年蹭蹬爲逐臣，鬢毛白盡巴江春。","鹿鳴猨嘯雖寂寞，水蛟山魅多精神。","山瘧困中聞有赦，死灰不望光陰借。","半夜州符喚牧童，虛教衰病生驚怕。","巫峽洞庭千里餘，蠻陬水國何親疎。","由來真宰不宰我，徒勞歎者懷吹噓。","霸橋昔與張生別，萬變桑田何處說。","龍蛇縱在沒泥塗，長衢却爲駑駘設。","愛君氣堅風骨峭，文章真把江淹笑。","洛下諸生懼刺先，烏鳶不得齊鷹鷂。","岳陽西南湖上寺，水閣松房遍文字。","新釘張生一首詩，自餘吟著皆無味。","策馬前途須努力，莫學龍鍾虛歎息。"]', '["十年蹭蹬爲逐臣，鬢毛白尽巴江春。","鹿鳴猨嘯雖寂寞，水蛟山魅多精神。","山瘧困中闻有赦，死灰不望光陰借。","半夜州符喚牧童，虛教衰病生驚怕。","巫峽洞庭千里餘，蠻陬水国何親疎。","由来真宰不宰我，徒勞歎者懷吹噓。","霸橋昔與張生別，万变桑田何处说。","龙蛇縱在沒泥塗，长衢却爲駑駘設。","愛君氣堅风骨峭，文章真把江淹笑。","洛下諸生懼刺先，烏鳶不得齊鷹鷂。","岳陽西南湖上寺，水閣松房遍文字。","新釘張生一首诗，自餘吟著皆無味。","策马前途須努力，莫学龙鍾虛歎息。"]', '诗', 'shi', '', NULL, '岳陽別張[祜] 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2d56e6-f9a8-49d1-90a7-feb92bd667a0', '寄河陽從事楊潛', '寄河陽從事楊潛', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["憶昨天台尋石梁，赤城枕下看扶桑。","金烏欲上海如血，翠色一點蓬萊光。","安期先生不可見，蓬萊目極滄海長。","回舟偶得風水便，煙帆數夕歸瀟湘。","瀟湘水清巖嶂曲，夜宿朝遊常不足。","一自無名身事閑，五湖雲月偏相屬。","進者恐不榮，退者恐不深。","魚遊鳥逝兩雖異，彼此各有遂生心。","身解耕耘妾能織，歲晏飢寒免相逼。","稚子纔年七歲餘，漁樵一半分渠力。","吾友從軍在河上，腰佩吳鉤佐飛將。","偶與嵩山道士期，西尋汴水來相訪。","見君顏色猶憔悴，知君未展心中事。","落日驅車出孟津，高歌共歎傷心地。","洛邑秦城少年別，兩都陳事空聞說。","漢家天子不東遊，古木行宮閉煙月。","洛濱老翁年八十，西望殘陽臨水泣。","自言生長開元中，武皇恩化親霑及。","當時天下無甲兵，雖聞賦斂毫毛輕。","紅車翠蓋滿衢路，洛中歡笑爭逢迎。","一從戎馬來幽薊，山谷虎狼無捍制。","九重宮殿閉豺狼，萬國生人自相噬。","蹭蹬瘡痍今不平，干戈南北常縱橫。","中原膏血焦欲盡，四郊貪將猶憑陵。","秦中豪寵爭出羣，巧將言智寬明君。","南山四皓不敢語，渭上釣人何足云。","君不見昔時槐柳八百里，路傍五月清陰起。","只今零落幾株殘，枯根半死黃河水。"]', '["憶昨天台尋石梁，赤城枕下看扶桑。","金烏欲上海如血，翠色一点蓬萊光。","安期先生不可见，蓬萊目極滄海长。","回舟偶得风水便，煙帆數夕归瀟湘。","瀟湘水清巖嶂曲，夜宿朝游常不足。","一自無名身事闲，五湖云月偏相屬。","進者恐不榮，退者恐不深。","鱼游鸟逝兩雖異，彼此各有遂生心。","身解耕耘妾能织，歲晏飢寒免相逼。","稚子纔年七歲餘，漁樵一半分渠力。","吾友從軍在河上，腰佩吳鉤佐飞將。","偶與嵩山道士期，西尋汴水来相訪。","见君顏色猶憔悴，知君未展心中事。","落日驱车出孟津，高歌共歎傷心地。","洛邑秦城少年別，兩都陳事空闻说。","漢家天子不东游，古木行宮閉煙月。","洛濱老翁年八十，西望殘陽臨水泣。","自言生长开元中，武皇恩化親霑及。","當时天下無甲兵，雖闻賦斂毫毛轻。","紅车翠蓋满衢路，洛中歡笑爭逢迎。","一從戎马来幽薊，山谷虎狼無捍制。","九重宮殿閉豺狼，万国生人自相噬。","蹭蹬瘡痍今不平，干戈南北常縱橫。","中原膏血焦欲尽，四郊貪將猶憑陵。","秦中豪寵爭出羣，巧將言智寬明君。","南山四皓不敢語，渭上釣人何足云。","君不见昔时槐柳八百里，路傍五月清陰起。","只今零落幾株殘，枯根半死黄河水。"]', '诗', 'shi', '', NULL, '寄河陽從事楊潛 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d98614d7-0daa-4402-bf60-f57f5b1e42cb', '重登滕王閣', '重登滕王閣', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["滕王閣上唱伊州，二十年前向此遊。","半是半非君莫問，好山長在水長流。"]', '["滕王閣上唱伊州，二十年前向此游。","半是半非君莫问，好山长在水长流。"]', '诗', 'shi', '', NULL, '重登滕王閣 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530f8fa6-4dbf-45ee-835c-dc3ccfa5f7af', '重到襄陽哭亡友韋壽朋', '重到襄陽哭亡友韋壽朋', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["故人墳樹立秋風，伯道無兒跡便空。","重到笙歌分散地，隔江吹笛月明中。"]', '["故人墳樹立秋风，伯道無兒跡便空。","重到笙歌分散地，隔江吹笛月明中。"]', '诗', 'shi', '', NULL, '重到襄陽哭亡友韋壽朋 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d7a1c5-77a0-4649-a5d1-1108cdcaec49', '再至長安', '再至长安', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["十年謫宦鬼方人，三遇鴻恩始到秦。","今日九衢騎馬望，却疑渾是剎那身。"]', '["十年謫宦鬼方人，三遇鴻恩始到秦。","今日九衢騎马望，却疑渾是剎那身。"]', '诗', 'shi', '', NULL, '再至長安 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10882d59-cdfe-4a9e-be58-c9b13c4b1a63', '贈道器法師', '贈道器法師', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["冰作形容雪作眉，早知談論兩川知。","如今不用空求佛，但把令狐宰相詩。"]', '["冰作形容雪作眉，早知談論兩川知。","如今不用空求佛，但把令狐宰相诗。"]', '诗', 'shi', '', NULL, '贈道器法師 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbf696ea-8ec6-4def-b6d5-fa141c7324f9', '廬山得元侍御書', '廬山得元侍御书', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["慙君知我命龍鍾，一紙書來意萬重。","正著白衣尋古寺，忽然郵遞到雲峰。"]', '["慙君知我命龙鍾，一紙书来意万重。","正著白衣尋古寺，忽然郵遞到云峰。"]', '诗', 'shi', '', NULL, '廬山得元侍御書 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebcc4b96-a548-4985-ba37-bb72061b31ef', '竹枝詞 一', '竹枝词 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["荆門灘急水潺潺，兩岸猨啼煙滿山。","渡頭少年應官去，月落西陵望不還。"]', '["荆门灘急水潺潺，兩岸猨啼煙满山。","渡头少年應官去，月落西陵望不還。"]', '诗', 'shi', '', NULL, '竹枝詞 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d868411-1dfd-489e-8b26-5a0eb8eb944f', '竹枝詞 二', '竹枝词 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["巫峽雲開神女祠，綠潭紅樹影參差。","不勞戍口初相問，無義灘頭剩別離。"]', '["巫峽云开神女祠，綠潭紅樹影參差。","不勞戍口初相问，無義灘头剩別離。"]', '诗', 'shi', '', NULL, '竹枝詞 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09e4f7bd-0468-4d40-a17d-eb5074624ad0', '竹枝詞 三', '竹枝词 三', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["石壁千重樹萬重，白雲斜掩碧芙蓉。","昭君溪上年年月，偏照嬋娟色最濃。"]', '["石壁千重樹万重，白云斜掩碧芙蓉。","昭君溪上年年月，偏照嬋娟色最濃。"]', '诗', 'shi', '', NULL, '竹枝詞 三 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('293a3a22-dcdf-41b6-a952-521c844c0add', '竹枝詞 四', '竹枝词 四', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["十二峰頭月欲低，空聆灘上子規啼。","孤舟一夜東歸客，泣向東風憶建溪。"]', '["十二峰头月欲低，空聆灘上子規啼。","孤舟一夜东归客，泣向东风憶建溪。"]', '诗', 'shi', '', NULL, '竹枝詞 四 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4fd3ddc-578e-4335-b6e9-3acdd5e0e235', '京口送朱晝之淮南', '京口送朱晝之淮南', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["兩行客淚愁中落，萬樹山花雨後殘。","君到揚州見桃葉，爲傳風水渡江難。"]', '["兩行客泪愁中落，万樹山花雨後殘。","君到揚州见桃葉，爲傳风水渡江难。"]', '诗', 'shi', '', NULL, '京口送朱晝之淮南 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1efd4848-09d2-43aa-b910-d468606e6d7d', '題鶴林寺僧舍', '題鹤林寺僧舍', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["終日昏昏醉夢間，忽聞春盡強登山。","因過竹院逢僧話，又得浮生半日閑。"]', '["終日昏昏醉梦间，忽闻春尽強登山。","因過竹院逢僧話，又得浮生半日闲。"]', '诗', 'shi', '', NULL, '題鶴林寺僧舍 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3ce341d-7ef5-4d02-8c1d-8e9a9568c1fe', '重過文上人院', '重過文上人院', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["南隨越鳥北燕鴻，松月三年別遠公。","無限心中不平事，一宵清話又成空。"]', '["南隨越鸟北燕鴻，松月三年別远公。","無限心中不平事，一宵清話又成空。"]', '诗', 'shi', '', NULL, '重過文上人院 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db7f753e-846d-49cd-a5e2-b77039325e9c', '雙峰寺得舍弟書', '雙峰寺得舍弟书', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["暫入松門拜祖師，殷勤再讀塔前碑。","回頭忽向尋陽使，太守如今是惠持。"]', '["暫入松门拜祖師，殷勤再读塔前碑。","回头忽向尋陽使，太守如今是惠持。"]', '诗', 'shi', '', NULL, '雙峰寺得舍弟書 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45383a7a-52c1-40da-b41a-1d2f5f3cdba3', '木蘭花', '木蘭花', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["碧落真人著紫衣，始堪相並木蘭枝。","今朝繞郭花看遍，盡是深村田舍兒。"]', '["碧落真人著紫衣，始堪相並木蘭枝。","今朝繞郭花看遍，尽是深村田舍兒。"]', '诗', 'shi', '', NULL, '木蘭花 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff3927c1-3a5a-4dfc-82b1-c3a6b9009745', '過招隱寺', '過招隐寺', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["每憶中林訪惠持，今來正遇早春時。","自從休去無心事，唯向高僧說便知。"]', '["每憶中林訪惠持，今来正遇早春时。","自從休去無心事，唯向高僧说便知。"]', '诗', 'shi', '', NULL, '過招隱寺 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5004c92-9fba-4ea7-9882-434de508dd65', '酬舉生許遇山居', '酬舉生許遇山居', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["琉璃潭上新秋月，清淨泉中智惠珠。","不似本宗疎二教，許過雲壑訪潛夫。"]', '["琉璃潭上新秋月，清淨泉中智惠珠。","不似本宗疎二教，許過云壑訪潛夫。"]', '诗', 'shi', '', NULL, '酬舉生許遇山居 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6240f3d-d285-473b-95ed-cba57a85f201', '春晚遊鶴林寺寄使府諸公', '春晚游鹤林寺寄使府諸公', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["野寺尋花春已遲，背巖唯有兩三枝。","明朝攜酒猶堪賞，爲報春風且莫吹。"]', '["野寺尋花春已遲，背巖唯有兩三枝。","明朝携酒猶堪賞，爲報春风且莫吹。"]', '诗', 'shi', '', NULL, '春晚遊鶴林寺寄使府諸公 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d9dbc25-afa4-4316-95b6-abba6bd0f8c6', '題開聖寺', '題开聖寺', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["宿雨初收草木濃，羣鴉飛散下堂鍾。","長廊無事僧歸院，盡日門前獨看松。"]', '["宿雨初收草木濃，羣鴉飞散下堂鍾。","长廊無事僧归院，尽日门前独看松。"]', '诗', 'shi', '', NULL, '題開聖寺 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('826f1f6a-9ec6-4b55-897e-ba4962b9abde', '奉使淮南', '奉使淮南', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["漢使徵兵詔未休，兩行旌斾接揚州。","試上高樓望春色，一年風景盡堪愁。"]', '["漢使徵兵詔未休，兩行旌斾接揚州。","試上高楼望春色，一年风景尽堪愁。"]', '诗', 'shi', '', NULL, '奉使淮南 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc4b501-12f1-42ef-86be-3dc7ba768960', '登北固山亭', '登北固山亭', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["海繞重山江抱城，隋家宮苑此分明。","居人不覺三吳恨，却笑關河又戰爭。"]', '["海繞重山江抱城，隋家宮苑此分明。","居人不覺三吳恨，却笑关河又戰爭。"]', '诗', 'shi', '', NULL, '登北固山亭 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dcccebb-cacc-4c8f-a869-05ac6d48aaa9', '秋日過員太祝林園', '秋日過員太祝林园', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["望水尋山二里餘，竹林斜到地仙居。","秋光何處堪消日，玄晏先生滿架書。"]', '["望水尋山二里餘，竹林斜到地仙居。","秋光何处堪消日，玄晏先生满架书。"]', '诗', 'shi', '', NULL, '秋日過員太祝林園 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eee8425b-6325-4e66-a22b-13b7979564cc', '題武關', '題武关', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["來往悲歡萬里心，多從此路計浮沈。","皆緣不得空門要，舜葬蒼梧直至今。"]', '["来往悲歡万里心，多從此路計浮沈。","皆緣不得空门要，舜葬蒼梧直至今。"]', '诗', 'shi', '', NULL, '題武關 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef512bc-1c46-4b17-8a03-a7fe50f5ad25', '題溫泉', '題溫泉', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["能使時平四十春，開元聖主得賢臣。","當時姚宋幷燕許，盡是驪山從駕人。"]', '["能使时平四十春，开元聖主得賢臣。","當时姚宋幷燕許，尽是驪山從駕人。"]', '诗', 'shi', '', NULL, '題溫泉 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11804387-bd3a-45ad-87fc-186e892ef378', '經溳川館寄使府羣公', '經溳川館寄使府羣公', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["溳川水竹十家餘，漁艇蓬門對岸居。","大勝塵中走鞍馬，與他軍府判文書。"]', '["溳川水竹十家餘，漁艇蓬门对岸居。","大勝塵中走鞍马，與他軍府判文书。"]', '诗', 'shi', '', NULL, '經溳川館寄使府羣公 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14cb3e43-4961-4462-9f90-e82943c8712c', '葺夷陵幽居', '葺夷陵幽居', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["負郭依山一徑深，萬竿如朿翠沈沈。","從來愛物多成癖，辛苦移家爲竹林。"]', '["負郭依山一徑深，万竿如朿翠沈沈。","從来愛物多成癖，辛苦移家爲竹林。"]', '诗', 'shi', '', NULL, '葺夷陵幽居 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7a514ca-fc90-4b0d-9383-a32d4528057e', '再遊頭陀寺', '再游头陀寺', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["無因暫泊魯陽戈，白髮兼愁日日多。","只恐雪晴花便盡，數來山寺亦無他。"]', '["無因暫泊魯陽戈，白髮兼愁日日多。","只恐雪晴花便尽，數来山寺亦無他。"]', '诗', 'shi', '', NULL, '再遊頭陀寺 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6520eb3c-0770-4e71-b657-e678d90293ef', '看射柳枝', '看射柳枝', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["玉弝朱弦敕賜弓，新加二斗得秋風。","萬人齊看翻金勒，百步穿楊逐箭空。"]', '["玉弝朱弦敕賜弓，新加二斗得秋风。","万人齊看翻金勒，百步穿楊逐箭空。"]', '诗', 'shi', '', NULL, '看射柳枝 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('470df489-6f73-41f6-97b9-f5e74d9a8c7d', '寄峽州韋郎中', '寄峽州韋郎中', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["年過五十鬢如絲，不必前程更問師。","幸得休耕樂堯化，楚山深處最相宜。"]', '["年過五十鬢如絲，不必前程更问師。","幸得休耕乐堯化，楚山深处最相宜。"]', '诗', 'shi', '', NULL, '寄峽州韋郎中 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3704963f-82bb-43e7-8309-4ba5e763a66c', '贈田玉卿', '贈田玉卿', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["長安里巷舊鄰居，未解梳頭五歲餘。","今朝嫁得風流壻，歌舞閑時看讀書。"]', '["长安里巷旧鄰居，未解梳头五歲餘。","今朝嫁得风流壻，歌舞闲时看读书。"]', '诗', 'shi', '', NULL, '贈田玉卿 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76e3723a-45f4-4321-bbe8-7c11b533870b', '題招隱寺即戴顒舊宅', '題招隐寺即戴顒旧宅', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["兩崖古樹千般色，一井寒泉數丈冰。","欲問前朝戴居士，野煙秋色是丘陵。"]', '["兩崖古樹千般色，一井寒泉數丈冰。","欲问前朝戴居士，野煙秋色是丘陵。"]', '诗', 'shi', '', NULL, '題招隱寺即戴顒舊宅 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ad839a1-3447-4915-b278-1f90219729d4', '山居送僧', '山居送僧', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["失意因休便買山，白雲深處寄柴關。","若逢城邑人相問，報道花時也不閑。"]', '["失意因休便買山，白云深处寄柴关。","若逢城邑人相问，報道花时也不闲。"]', '诗', 'shi', '', NULL, '山居送僧 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('826589fd-2be5-41f9-9bfe-57c38f4e12e4', '過襄陽上于司空頔', '過襄陽上于司空頔', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["方城漢水舊城池，陵谷依然世自移。","歇馬獨來尋故事，逢人唯說峴山碑。"]', '["方城漢水旧城池，陵谷依然世自移。","歇马独来尋故事，逢人唯说峴山碑。"]', '诗', 'shi', '', NULL, '過襄陽上于司空頔 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e16ef8d4-c50c-48da-971f-cda8c41d5d10', '送魏簡能東遊二首 一', '送魏簡能东游二首 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["獻賦論兵命未通，却乘羸馬出關東。","灞陵原上重回首，十載長安似夢中。"]', '["獻賦論兵命未通，却乘羸马出关东。","灞陵原上重回首，十載长安似梦中。"]', '诗', 'shi', '', NULL, '送魏簡能東遊二首 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c74bb0b-650d-41ff-9ed7-9ab81cc54cd5', '送魏簡能東遊二首 二', '送魏簡能东游二首 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["燕市悲歌又送君，目隨征鴈過寒雲。","孤亭宿處時看劒，莫使塵埃蔽斗文。"]', '["燕市悲歌又送君，目隨征鴈過寒云。","孤亭宿处时看劒，莫使塵埃蔽斗文。"]', '诗', 'shi', '', NULL, '送魏簡能東遊二首 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf3e7cd-58bb-4359-9c92-a2ae5b29872f', '中秋夜君山臺望月', '中秋夜君山台望月', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["大堤花裏錦江前，詩酒同遊四十年。","不料中秋最明夜，洞庭湖上見當天。"]', '["大堤花裏錦江前，诗酒同游四十年。","不料中秋最明夜，洞庭湖上见當天。"]', '诗', 'shi', '', NULL, '中秋夜君山臺望月 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf80c19d-9ccb-4870-a50b-6653f4c33241', '酬彭伉', '酬彭伉', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["公孫閣裏見君初，衣錦南歸二十餘。","莫歎屈聲猶未展，同年今日在中書。"]', '["公孫閣裏见君初，衣錦南归二十餘。","莫歎屈声猶未展，同年今日在中书。"]', '诗', 'shi', '', NULL, '酬彭伉 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abae4b57-fa93-49e7-99ac-ac6d9095d595', '硤石遇赦', '硤石遇赦', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["天網初開釋楚囚，殘骸已廢自知休。","荷簑不是人間事，歸去滄江有釣舟。"]', '["天網初开釋楚囚，殘骸已廢自知休。","荷簑不是人间事，归去滄江有釣舟。"]', '诗', 'shi', '', NULL, '硤石遇赦 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7d3a8fc-7992-46f6-acb6-e4f010e4c659', '贈龍泉洞塵上人', '贈龙泉洞塵上人', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["八十山僧眼未昏，獨尋流水到窮源。","自言共得龍神語，擬作茅菴住洞門。"]', '["八十山僧眼未昏，独尋流水到窮源。","自言共得龙神語，擬作茅菴住洞门。"]', '诗', 'shi', '', NULL, '贈龍泉洞塵上人 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb2b030-facf-4f9b-8ea8-ab97c6a64a02', '題湖臺', '題湖台', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["山有松門江有亭，不勞他處問青冥。","有時帶月牀舁到，一陣風來酒盡醒。"]', '["山有松门江有亭，不勞他处问青冥。","有时带月牀舁到，一陣风来酒尽醒。"]', '诗', 'shi', '', NULL, '題湖臺 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4178b4f8-a5ac-4bcf-9057-b5a1867b6ea6', '送妻入道', '送妻入道', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["人無回意似波瀾，琴有離聲爲一彈。","縱使空門再相見，還如秋月水中看。"]', '["人無回意似波瀾，琴有離声爲一彈。","縱使空门再相见，還如秋月水中看。"]', '诗', 'shi', '', NULL, '送妻入道 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f40308b6-f294-4a5d-aefb-ad0948b721e7', '遇湖州妓宋態宜二首 一', '遇湖州妓宋態宜二首 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["曾識雲仙至小時，芙蓉頭上綰青絲。","當時驚覺高唐夢，唯有如今宋玉知。"]', '["曾識云仙至小时，芙蓉头上綰青絲。","當时驚覺高唐梦，唯有如今宋玉知。"]', '诗', 'shi', '', NULL, '遇湖州妓宋態宜二首 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b57905-7c1e-4ada-95c1-205482e6a57c', '遇湖州妓宋態宜二首 二', '遇湖州妓宋態宜二首 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["陵陽夜會使君筵，解語花枝出眼前。","一從明[月]西沉海，不見嫦娥二十年。"]', '["陵陽夜會使君筵，解語花枝出眼前。","一從明[月]西沉海，不见嫦娥二十年。"]', '诗', 'shi', '', NULL, '遇湖州妓宋態宜二首 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d868572a-423c-45d8-9567-283cfcecea5c', '逢舊二首 一', '逢旧二首 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["碧落高高雲萬重，當時孤鶴去無蹤。","不期陵谷遷朝市，今日遼東特地逢。"]', '["碧落高高云万重，當时孤鹤去無蹤。","不期陵谷遷朝市，今日遼东特地逢。"]', '诗', 'shi', '', NULL, '逢舊二首 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0ab234f-ecba-4505-bfbc-5a7cc95ad934', '逢舊二首 二', '逢旧二首 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["將作乘槎去不還，便尋雲海住三山。","不知留得支機石，却逐黃河到世間。"]', '["將作乘槎去不還，便尋云海住三山。","不知留得支機石，却逐黄河到世间。"]', '诗', 'shi', '', NULL, '逢舊二首 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd1d93ca-b688-4ec1-a1e6-c4cf880695b7', '潤州聽暮角', '潤州听暮角', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["江城吹角水茫茫，曲引邊聲怨思長。","驚起暮天沙上鴈，海門斜去兩三行。"]', '["江城吹角水茫茫，曲引邊声怨思长。","驚起暮天沙上鴈，海门斜去兩三行。"]', '诗', 'shi', '', NULL, '潤州聽暮角 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bd22d03-97d2-4f6f-8f08-11fe9302c109', '頭陀寺看竹', '头陀寺看竹', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["寺前新笋已成竿，策馬重來獨自看。","可惜班皮空滿地，無人解取作頭冠。"]', '["寺前新笋已成竿，策马重来独自看。","可惜班皮空满地，無人解取作头冠。"]', '诗', 'shi', '', NULL, '頭陀寺看竹 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('684798dd-31d7-4eaa-90c1-ebf806bc3dfd', '奉使京西', '奉使京西', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["盧龍已復兩河平，烽火樓邊處處耕。","何事書生走羸馬，原州城下又添兵。"]', '["盧龙已复兩河平，烽火楼邊处处耕。","何事书生走羸马，原州城下又添兵。"]', '诗', 'shi', '', NULL, '奉使京西 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de1401d7-e100-4070-a35d-ad3d7de7b73c', '題連雲堡', '題連云堡', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["由來天地有關扃，斷壑連山接杳冥。","一出縱知邊上事，滿朝誰信語堪聽。"]', '["由来天地有关扃，斷壑連山接杳冥。","一出縱知邊上事，满朝誰信語堪听。"]', '诗', 'shi', '', NULL, '題連雲堡 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ff3d44e-8d09-4b83-a13c-aa090b481f59', '再宿武關', '再宿武关', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["遠別秦城萬里遊，亂山高下出商州。","關門不鎖寒溪水，一夜潺湲送客愁。"]', '["远別秦城万里游，亂山高下出商州。","关门不鎖寒溪水，一夜潺湲送客愁。"]', '诗', 'shi', '', NULL, '再宿武關 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a84d43ca-8824-4e60-ac90-04dee72870bf', '長安悶作', '长安悶作', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["宵分獨坐到天明，又策羸驂信脚行。","每日除書空滿紙，不曾聞有介推名。"]', '["宵分独坐到天明，又策羸驂信脚行。","每日除书空满紙，不曾闻有介推名。"]', '诗', 'shi', '', NULL, '長安悶作 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdb3a548-2a04-474a-805f-e240048510f7', '和尚書舅見寄', '和尚书舅见寄', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["欲隨流水去幽棲，喜伴歸雲入虎溪。","深謝陳蕃憐寂寞，遠飛芳字警沉迷。"]', '["欲隨流水去幽棲，喜伴归云入虎溪。","深謝陳蕃怜寂寞，远飞芳字警沉迷。"]', '诗', 'shi', '', NULL, '和尚書舅見寄 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de495a6-9a74-4dc7-b14e-8577611ba318', '送王六覲巢縣叔父二首 一', '送王六覲巢縣叔父二首 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["巢岸南分戰鳥山，水雲程盡到東關。","弦歌自是君家事，莫怪今來一邑閑。"]', '["巢岸南分戰鸟山，水云程尽到东关。","弦歌自是君家事，莫怪今来一邑闲。"]', '诗', 'shi', '', NULL, '送王六覲巢縣叔父二首 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a07b10d-d744-4217-9ed1-39199b7ec44f', '送王六覲巢縣叔父二首 二', '送王六覲巢縣叔父二首 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["長憶山陰舊會時，王家兄弟盡相隨。","老來放逐瀟湘路，淚滴秋風引獻之。"]', '["长憶山陰旧會时，王家兄弟尽相隨。","老来放逐瀟湘路，泪滴秋风引獻之。"]', '诗', 'shi', '', NULL, '送王六覲巢縣叔父二首 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530443f2-e2ae-41a4-965b-d2169ed04759', '偶懷', '偶懷', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["轉知名宦是悠悠，分付空源始到頭。","待送妻兒下山了，便隨雲水一生休。"]', '["轉知名宦是悠悠，分付空源始到头。","待送妻兒下山了，便隨云水一生休。"]', '诗', 'shi', '', NULL, '偶懷 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6045f0ab-faa4-4f0e-aaf3-5aa5486447cc', '秋夜題夷陵水館', '秋夜題夷陵水館', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["凝碧初高海氣秋，桂輪斜落到江樓。","三更浦上巴歌歇，山影沉沉水不流。"]', '["凝碧初高海氣秋，桂輪斜落到江楼。","三更浦上巴歌歇，山影沉沉水不流。"]', '诗', 'shi', '', NULL, '秋夜題夷陵水館 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdca6404-1889-4dde-bcca-820d8c84a19b', '與梧州劉中丞', '與梧州劉中丞', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["三代盧龍將相家，五分符竹到天涯。","瘴山江上重相見，醉裏同看荳蔲花。"]', '["三代盧龙將相家，五分符竹到天涯。","瘴山江上重相见，醉裏同看荳蔲花。"]', '诗', 'shi', '', NULL, '與梧州劉中丞 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dbefd46-1e0e-413e-8b57-407004454af3', '聽多美唱歌', '听多美唱歌', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["黃鶯慢轉引秋蟬，衝斷行雲直入天。","一曲梁州聽初了，爲君別唱想夫憐。"]', '["黄鶯慢轉引秋蟬，衝斷行云直入天。","一曲梁州听初了，爲君別唱想夫怜。"]', '诗', 'shi', '', NULL, '聽多美唱歌 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33a209ae-7252-42fe-b235-01d6086e64f6', '題澗飲寺', '題澗饮寺', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["百年如夢竟何成，白髮重來此地行。","還似蕭郎許玄度，再看庭石悟前生。"]', '["百年如梦竟何成，白髮重来此地行。","還似蕭郎許玄度，再看庭石悟前生。"]', '诗', 'shi', '', NULL, '題澗飲寺 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aff6f954-43c1-41cf-840c-01540f5b4494', '題蘇仙宅枯松', '題蘇仙宅枯松', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["幾年蒼翠在仙家，一旦枝枯類海槎。","不如酸澀棠梨樹，却占高城獨放花。"]', '["幾年蒼翠在仙家，一旦枝枯類海槎。","不如酸澀棠梨樹，却占高城独放花。"]', '诗', 'shi', '', NULL, '題蘇仙宅枯松 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d02e730c-f618-46e8-9441-0f2f38b50878', '山居', '山居', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["一從身世兩相遺，往往關門到午時。","想得俗流應大笑，不知年老識便宜。"]', '["一從身世兩相遺，往往关门到午时。","想得俗流應大笑，不知年老識便宜。"]', '诗', 'shi', '', NULL, '山居 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d01d58c0-3e3c-492b-8a5f-c403d26a0d8e', '聽鄰女吟', '听鄰女吟', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["含情遙夜幾人知，閑詠風流小謝詩。","還似霓旌下煙露，月邊吹落上清詞。"]', '["含情遙夜幾人知，闲詠风流小謝诗。","還似霓旌下煙露，月邊吹落上清词。"]', '诗', 'shi', '', NULL, '聽鄰女吟 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc669dfe-f2a1-4943-8995-09a55eb09188', '題宇文秀才櫻桃', '題宇文秀才櫻桃', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["風光莫占少年家，白髮殷勤最戀花。","今日顛狂任君笑，趂愁得醉眼麻茶。"]', '["风光莫占少年家，白髮殷勤最戀花。","今日顛狂任君笑，趂愁得醉眼麻茶。"]', '诗', 'shi', '', NULL, '題宇文秀才櫻桃 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2386d800-7a20-48c4-a1ac-b8a1919efb93', '漢上偶題', '漢上偶題', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["謫仙唐世游茲郡，花下聽歌醉眼迷。","今日漢江煙樹盡，更無人唱白銅鞮。"]', '["謫仙唐世游茲郡，花下听歌醉眼迷。","今日漢江煙樹尽，更無人唱白銅鞮。"]', '诗', 'shi', '', NULL, '漢上偶題 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95f586e7-f277-4eb0-ac7f-b9304458f354', '送楊敬之倅湖南', '送楊敬之倅湖南', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["久嗟塵匣掩青萍，見說除書試一聽。","聞君却作長沙傅，便逐秋風過洞庭。"]', '["久嗟塵匣掩青萍，见说除书試一听。","闻君却作长沙傅，便逐秋风過洞庭。"]', '诗', 'shi', '', NULL, '送楊敬之倅湖南 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f241fb38-5750-41e2-b05c-f1c04a8abe00', '送孫堯夫赴舉', '送孫堯夫赴舉', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["自說軒皇息戰威，萬方無復事戎衣。","却教孫子藏兵法，空把文章向禮闈。"]', '["自说軒皇息戰威，万方無复事戎衣。","却教孫子藏兵法，空把文章向禮闈。"]', '诗', 'shi', '', NULL, '送孫堯夫赴舉 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80e98e34-908e-4480-9240-b0a874b552e0', '題水月臺', '題水月台', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["平流白日無人愛，橋上閑行若箇知。","水似晴天天似水，兩重星點碧琉璃。"]', '["平流白日無人愛，橋上闲行若箇知。","水似晴天天似水，兩重星点碧琉璃。"]', '诗', 'shi', '', NULL, '題水月臺 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3512f84-94d1-4088-87e2-c05dbb8ca17b', '早春霽後發頭陀寺寄院中', '早春霽後發头陀寺寄院中', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["紅樓金剎倚晴岡，雨雪初收望漢陽。","草檄可中能有暇，迎春一醉也無妨。"]', '["紅楼金剎倚晴岡，雨雪初收望漢陽。","草檄可中能有暇，迎春一醉也無妨。"]', '诗', 'shi', '', NULL, '早春霽後發頭陀寺寄院中 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c60e45bd-f986-4ebd-9675-f14a22fa109d', '哭田布', '哭田布', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["魏師臨陣却抽營，誰管豺狼作信兵。","縱使將軍能伏劒，何人島上哭田橫。"]', '["魏師臨陣却抽營，誰管豺狼作信兵。","縱使將軍能伏劒，何人島上哭田橫。"]', '诗', 'shi', '', NULL, '哭田布 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1cb19db-f7cd-4fa3-8cac-7b988ec69fb7', '黃葵花', '黄葵花', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["此花莫遣俗人看，新染鵝黃色未乾。","好逐秋風上天去，紫陽宮女要頭冠。"]', '["此花莫遣俗人看，新染鵝黄色未乾。","好逐秋风上天去，紫陽宮女要头冠。"]', '诗', 'shi', '', NULL, '黃葵花 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51e72bcd-15c0-421d-a1c1-179ada1ee595', '別南溪二首 一', '別南溪二首 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["如雲不厭蒼梧遠，似鴈逢春又北飛。","唯有隱山溪上月，年年相望兩依依。"]', '["如云不厭蒼梧远，似鴈逢春又北飞。","唯有隐山溪上月，年年相望兩依依。"]', '诗', 'shi', '', NULL, '別南溪二首 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff5e1838-e8b0-476d-9427-ed82ace09959', '別南溪二首 二', '別南溪二首 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["常歎春泉去不回，我今此去更難來。","欲知別後留情處，手種巖花次第開。"]', '["常歎春泉去不回，我今此去更难来。","欲知別後留情处，手種巖花次第开。"]', '诗', 'shi', '', NULL, '別南溪二首 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca749313-844a-420f-90e4-41c58dcaacee', '井欄砂宿遇夜客', '井欄砂宿遇夜客', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["暮雨蕭蕭江上村，綠林豪客夜知聞。","他時不用逃名姓，世上如今半是君。"]', '["暮雨蕭蕭江上村，綠林豪客夜知闻。","他时不用逃名姓，世上如今半是君。"]', '诗', 'shi', '', NULL, '井欄砂宿遇夜客 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff69f38-a9de-47a9-aa2b-ae8c4a47b7b8', '謝王連州送海陽圖', '謝王連州送海陽圖', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["謝家爲郡實風流，畫得青山寄楚囚。","驚起草堂寒氣晚，海陽潮水到牀頭。"]', '["謝家爲郡實风流，畫得青山寄楚囚。","驚起草堂寒氣晚，海陽潮水到牀头。"]', '诗', 'shi', '', NULL, '謝王連州送海陽圖 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5abbdcae-657e-4d2b-9f2e-856b4377fe10', '再謫夷陵題長樂寺', '再謫夷陵題长乐寺', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["當時謫宦向夷陵，願得身閑便作僧。","誰知漸漸因緣重，羞見長燃一盞燈。"]', '["當时謫宦向夷陵，願得身闲便作僧。","誰知漸漸因緣重，羞见长燃一盞灯。"]', '诗', 'shi', '', NULL, '再謫夷陵題長樂寺 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36062ad8-6800-4112-bee0-39b859d791a8', '譴謫康州先寄弟渤', '譴謫康州先寄弟渤', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["唯將直道信蒼蒼，可料無名抵憲章。","陰隲却應先有謂，已交鴻鴈早隨陽。"]', '["唯將直道信蒼蒼，可料無名抵憲章。","陰隲却應先有謂，已交鴻鴈早隨陽。"]', '诗', 'shi', '', NULL, '譴謫康州先寄弟渤 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8a77c24-880b-4d01-bfd0-4430f0f05579', '贈廖道士', '贈廖道士', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["膏已明煎信矣哉，二年人世不歸來。","庭前爲報仙桃樹，今歲花時好好開。"]', '["膏已明煎信矣哉，二年人世不归来。","庭前爲報仙桃樹，今歲花时好好开。"]', '诗', 'shi', '', NULL, '贈廖道士 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06c5b925-7d25-4399-8830-586a37ccc559', '山花', '山花', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["六出花開赤玉盤，當中紅濕耐春寒。","長安若在五侯宅，誰肯將錢買牡丹。"]', '["六出花开赤玉盤，當中紅濕耐春寒。","长安若在五侯宅，誰肯將錢買牡丹。"]', '诗', 'shi', '', NULL, '山花 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87d53b66-87e0-4656-8f57-1f4e7132f30d', '聽歌', '听歌', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["颯颯先飛梁上塵，朱脣不動翠眉顰。","願得春風吹更遠，直教愁殺滿城人。"]', '["颯颯先飞梁上塵，朱脣不动翠眉顰。","願得春风吹更远，直教愁殺满城人。"]', '诗', 'shi', '', NULL, '聽歌 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad812479-1174-48dc-b2ec-316a2572bd5b', '送顏覺赴舉', '送顏覺赴舉', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["顏子將才應四科，料量時輩更誰過。","居然一片荆山玉，可怕無人是卞和。"]', '["顏子將才應四科，料量时輩更誰過。","居然一片荆山玉，可怕無人是卞和。"]', '诗', 'shi', '', NULL, '送顏覺赴舉 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970c11f2-a334-4c76-889c-aaa531a0fddc', '題五松驛', '題五松驛', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["雲木蒼蒼數萬株，此中言命的應無。","人生不得如松樹，却遇秦封作大夫。"]', '["云木蒼蒼數万株，此中言命的應無。","人生不得如松樹，却遇秦封作大夫。"]', '诗', 'shi', '', NULL, '題五松驛 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bd9e0ad-b498-479b-a5b6-f2c43a868013', '湘妃廟', '湘妃廟', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["班竹林邊有古祠，鳥啼花發盡堪悲。","當時惆悵同今日，南北行人可得知。"]', '["班竹林邊有古祠，鸟啼花發尽堪悲。","當时惆悵同今日，南北行人可得知。"]', '诗', 'shi', '', NULL, '湘妃廟 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d15a28d4-a1c4-4cdf-a3b3-0108e89eb5c5', '贈長安小主人', '贈长安小主人', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["上清真子玉童顏，花態嬌羞月思閑。","仙路迷人應有術，桃源不必在深山。"]', '["上清真子玉童顏，花態嬌羞月思闲。","仙路迷人應有術，桃源不必在深山。"]', '诗', 'shi', '', NULL, '贈長安小主人 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ecde9d1-fa45-4970-9a54-f47b43f77906', '邠州詞獻高尚書三首 一', '邠州词獻高尚书三首 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["單于都護再分疆，西引雙旌出帝鄉。","朝日詔書添戰馬，即聞千騎取河湟。"]', '["單于都護再分疆，西引雙旌出帝乡。","朝日詔书添戰马，即闻千騎取河湟。"]', '诗', 'shi', '', NULL, '邠州詞獻高尚書三首 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec5e206f-58af-4be3-92aa-5601e7f3b6c0', '邠州詞獻高尚書三首 二', '邠州词獻高尚书三首 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["將家難立是威聲，不見多傳衛霍名。","一自元和平蜀後，馬頭行處即長城。"]', '["將家难立是威声，不见多傳衛霍名。","一自元和平蜀後，马头行处即长城。"]', '诗', 'shi', '', NULL, '邠州詞獻高尚書三首 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b5cddc7-551d-4eab-87a0-a724d0653cdc', '邠州詞獻高尚書三首 三', '邠州词獻高尚书三首 三', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["朔方忠義舊來閑，盡是邠城父子軍。","今日兵符歸上將，旄頭不用更妖氛。"]', '["朔方忠義旧来闲，尽是邠城父子軍。","今日兵符归上將，旄头不用更妖氛。"]', '诗', 'shi', '', NULL, '邠州詞獻高尚書三首 三 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9997019-b1f3-4aeb-b0ca-3d92a11af799', '游西林寺', '游西林寺', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["十地初心在此身，水能生月即離塵。","如今再結林中社，可羨當年會裏人。"]', '["十地初心在此身，水能生月即離塵。","如今再結林中社，可羨當年會裏人。"]', '诗', 'shi', '', NULL, '游西林寺 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('076fa225-c4f1-444d-a7cf-391b8e7e6fbb', '題白鹿蘭若', '題白鹿蘭若', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["只去都門十里強，竹陰流水遶回廊。","滿城車馬皆知有，每喚同游盡道忙。"]', '["只去都门十里強，竹陰流水遶回廊。","满城车马皆知有，每喚同游尽道忙。"]', '诗', 'shi', '', NULL, '題白鹿蘭若 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91c6fef3-85d2-405c-90c6-1f53f88704fa', '寄趙準乞湘川山居', '寄趙準乞湘川山居', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["閑說班超有舊居，山橫水曲占商於。","知君不用磻溪石，乞取終年獨釣魚。"]', '["闲说班超有旧居，山橫水曲占商於。","知君不用磻溪石，乞取終年独釣鱼。"]', '诗', 'shi', '', NULL, '寄趙準乞湘川山居 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb95ba48-c5e4-41b2-b9ef-681e683d6398', '曉過函谷關', '晓過函谷关', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["因韓爲趙兩游秦，十月冰霜渡孟津。","縱使雞鳴遇關吏，不知余也是何人。"]', '["因韓爲趙兩游秦，十月冰霜渡孟津。","縱使雞鳴遇关吏，不知余也是何人。"]', '诗', 'shi', '', NULL, '曉過函谷關 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('993579a0-64a0-49de-a0b0-fe1a03656f0c', '奉和九弟渤見寄絕句', '奉和九弟渤见寄絕句', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["忽啓新緘吟近詩，詩中韻出碧雲詞。","且喜陟岡愁已散，登舟只恨渡江遲。"]', '["忽啓新緘吟近诗，诗中韻出碧云词。","且喜陟岡愁已散，登舟只恨渡江遲。"]', '诗', 'shi', '', NULL, '奉和九弟渤見寄絕句 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89eff5b8-5af5-43de-91a8-877632675189', '贈友人孩子', '贈友人孩子', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["驪龍頷下亦生珠，便與人間衆寶殊。","他時若要追風日，須得君家萬里駒。"]', '["驪龙頷下亦生珠，便與人间衆寶殊。","他时若要追风日，須得君家万里駒。"]', '诗', 'shi', '', NULL, '贈友人孩子 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac1877d8-60fa-44ef-b446-21c3ece68e05', '奉宣慰使魚十四郎', '奉宣慰使鱼十四郎', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["年纔二十衆知名，孤鶴儀容徹骨清。","口傳天語來人世，却逐祥雲上玉京。"]', '["年纔二十衆知名，孤鹤儀容徹骨清。","口傳天語来人世，却逐祥云上玉京。"]', '诗', 'shi', '', NULL, '奉宣慰使魚十四郎 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6afa1cd6-6cb8-4a8c-823d-1e2330e0a0a8', '題善光寺', '題善光寺', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["雲門天竺舊姻緣，臨老移家住玉泉。","早到可中溳南寺，免得翻經住幾年。"]', '["云门天竺旧姻緣，臨老移家住玉泉。","早到可中溳南寺，免得翻經住幾年。"]', '诗', 'shi', '', NULL, '題善光寺 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('582c7f2f-dcf3-46d8-9461-b49eb45616cc', '題宣化寺道光上人居', '題宣化寺道光上人居', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["二十年前不繫身，草堂曾與雪爲鄰。","常思和尚當時語，衣鉢留將與此人。"]', '["二十年前不繫身，草堂曾與雪爲鄰。","常思和尚當时語，衣鉢留將與此人。"]', '诗', 'shi', '', NULL, '題宣化寺道光上人居 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b8f9ff5-ec06-4f60-9980-b116842374ec', '柳枝詞', '柳枝词', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["錦池江上柳垂橋，風引蟬聲送寂寥。","不必如絲千萬縷，只禁離恨兩三條。"]', '["錦池江上柳垂橋，风引蟬声送寂寥。","不必如絲千万縷，只禁離恨兩三條。"]', '诗', 'shi', '', NULL, '柳枝詞 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2f0bafa-8c94-4d34-96bb-b4225ed18be0', '竹枝詞', '竹枝词', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["十二山晴花盡開，楚宮雙闕對陽臺。","細腰爭舞君沈醉，白日秦兵天下來。"]', '["十二山晴花尽开，楚宮雙闕对陽台。","細腰爭舞君沈醉，白日秦兵天下来。"]', '诗', 'shi', '', NULL, '竹枝詞 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('860e5ed3-642d-4ec0-a5a9-f2c67c532b74', '竹裏', '竹裏', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["竹裏編茅倚石[根]，竹莖疎處見前村。","閑眠盡日無人到，自有春風爲掃門。"]', '["竹裏編茅倚石[根]，竹莖疎处见前村。","闲眠尽日無人到，自有春风爲掃门。"]', '诗', 'shi', '', NULL, '竹裏 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e7b084a-3107-4f8a-9f3c-2d2cf8939700', '失題', '失題', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["華表千年一鶴歸，丹砂爲頂雪爲衣。","泠泠仙語人聽盡，却向五雲翻翅飛。"]', '["华表千年一鹤归，丹砂爲頂雪爲衣。","泠泠仙語人听尽，却向五云翻翅飞。"]', '诗', 'shi', '', NULL, '失題 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0129f386-cc7e-44fa-aa48-e75b2d1dd050', '雲安公主下降奉詔作催粧詩', '云安公主下降奉詔作催粧诗', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["雲安公主貴，出嫁五侯家。","天母親調粉，日兄憐賜花。","催鋪百子帳，待障七香車。","借問妝成未，東方欲曉霞。"]', '["云安公主貴，出嫁五侯家。","天母親調粉，日兄怜賜花。","催鋪百子帳，待障七香车。","借问妝成未，东方欲晓霞。"]', '诗', 'shi', '', NULL, '雲安公主下降奉詔作催粧詩 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71b52a42-55e2-4a93-87ab-c86f12b2b55f', '山出雲', '山出云', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["靈山蓄雲彩，紛郁出清晨。","望樹繁花白，看峰小雪新。","映松張蓋影，依澗布魚鱗。","高似從龍處，低如觸石頻。","濃光藏半岫，淺色類飄塵。","玉葉開天際，遙憐占早春。"]', '["靈山蓄云彩，紛郁出清晨。","望樹繁花白，看峰小雪新。","映松張蓋影，依澗布鱼鱗。","高似從龙处，低如觸石頻。","濃光藏半岫，淺色類飄塵。","玉葉开天際，遙怜占早春。"]', '诗', 'shi', '', NULL, '山出雲 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('020daf94-ea22-4e97-aee6-89aa43fe562b', '驚雪', '驚雪', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["怪得北風急，前庭如月輝。","天人寧許巧，翦水作花飛。"]', '["怪得北风急，前庭如月輝。","天人寧許巧，翦水作花飞。"]', '诗', 'shi', '', NULL, '驚雪 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f8c9481-4569-4d4c-be32-fbb4d8d181ae', '聞早蟬', '闻早蟬', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["落日早蟬急，客心聞更愁。","一聲來枕上，夢裏故園秋。"]', '["落日早蟬急，客心闻更愁。","一声来枕上，梦裏故园秋。"]', '诗', 'shi', '', NULL, '聞早蟬 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f197211-3d07-45c5-9144-fbdc19d82947', '別劉端公', '別劉端公', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["連騎出都門，秋蟬噪高柳。","落日辭故人，自醉不關酒。"]', '["連騎出都门，秋蟬噪高柳。","落日辞故人，自醉不关酒。"]', '诗', 'shi', '', NULL, '別劉端公 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13816ee9-b5c3-456c-947c-6b8cab1c4f4e', '新晴愛月', '新晴愛月', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["野性平生惟愛月，新晴半夜覩嬋娟。","起來自擘紗窗破，恰漏清光落枕前。"]', '["野性平生惟愛月，新晴半夜覩嬋娟。","起来自擘紗窗破，恰漏清光落枕前。"]', '诗', 'shi', '', NULL, '新晴愛月 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('751f96ce-ae00-4c17-b636-db5b09ee5554', '雲安公主出降雜詠催粧二首 一', '云安公主出降杂詠催粧二首 一', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["天上瓊花不避秋，今宵織女嫁牽牛。","萬人惟待乘鸞出，乞巧齊登明月樓。"]', '["天上瓊花不避秋，今宵织女嫁牽牛。","万人惟待乘鸾出，乞巧齊登明月楼。"]', '诗', 'shi', '', NULL, '雲安公主出降雜詠催粧二首 一 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36e7ab00-1fec-401c-907c-b5390dd2196b', '雲安公主出降雜詠催粧二首 二', '云安公主出降杂詠催粧二首 二', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["少粧銀粉飾金鈿，端正天花貴自然。","聞道禁中時節異，九秋香滿鏡臺前。"]', '["少粧銀粉飾金鈿，端正天花貴自然。","闻道禁中时節異，九秋香满镜台前。"]', '诗', 'shi', '', NULL, '雲安公主出降雜詠催粧二首 二 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ae13d11-1588-40e9-84d9-ae22ae90e878', '坐障', '坐障', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["白玉爲竿丁字成，黃金繡帶短長輕。","強遮天上花顏色，不隔雲中語笑聲。"]', '["白玉爲竿丁字成，黄金繡带短长轻。","強遮天上花顏色，不隔云中語笑声。"]', '诗', 'shi', '', NULL, '坐障 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314b83af-633b-414a-af05-c3bd260ace2f', '簾', '簾', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["勞將素手捲蝦鬚，瓊室流光更綴珠。","玉漏報來過半夜，可憐潘岳立踟躕。"]', '["勞將素手捲蝦鬚，瓊室流光更綴珠。","玉漏報来過半夜，可怜潘岳立踟躕。"]', '诗', 'shi', '', NULL, '簾 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('625dedd4-8269-41cb-b375-a9de73c65fb1', '階', '階', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["甃玉編金次第平，花紋隱起踏無聲。","幾重便上華堂裏，得見天人吹鳳笙。"]', '["甃玉編金次第平，花紋隐起踏無声。","幾重便上华堂裏，得见天人吹鳳笙。"]', '诗', 'shi', '', NULL, '階 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcb671fa-4d77-4dd4-859a-40d8be9d1e4c', '扇', '扇', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["寶扇持來入禁宮，本教花下動香風。","姮娥須逐彩雲降，不可通宵在月中。"]', '["寶扇持来入禁宮，本教花下动香风。","姮娥須逐彩云降，不可通宵在月中。"]', '诗', 'shi', '', NULL, '扇 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef7bfbca-f432-48a7-8aef-071c366262d5', '解內人嘲', '解內人嘲', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["粉面仙郎選聖朝，偶逢秦女學吹簫。","須教翡翠聞王母，不奈烏鳶噪鵲橋。"]', '["粉面仙郎選聖朝，偶逢秦女学吹簫。","須教翡翠闻王母，不奈烏鳶噪鵲橋。"]', '诗', 'shi', '', NULL, '解內人嘲 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a387c843-567b-439a-ac50-d41b3f50c583', '成都贈別席夔', '成都贈別席夔', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["不值分流二江水，定應猶得且同行。","三千里外情人別，更被子規啼數聲。"]', '["不值分流二江水，定應猶得且同行。","三千里外情人別，更被子規啼數声。"]', '诗', 'shi', '', NULL, '成都贈別席夔 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('578523ba-355b-4d06-8712-167e08b76262', '遊城東王駙馬亭', '游城东王駙马亭', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["城外無塵水間松，秋天木落見山容。","共尋蕭史江亭去，一望終南紫閣峰。"]', '["城外無塵水间松，秋天木落见山容。","共尋蕭史江亭去，一望終南紫閣峰。"]', '诗', 'shi', '', NULL, '遊城東王駙馬亭 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502400a5-4514-4981-a304-cf170774fc25', '望毛女峰', '望毛女峰', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["我種東峰千葉蓮，此峰毛女始求仙。","今朝暗算當時事，已是人間七萬年。"]', '["我種东峰千葉蓮，此峰毛女始求仙。","今朝暗算當时事，已是人间七万年。"]', '诗', 'shi', '', NULL, '望毛女峰 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bed1ca0-5e53-4b34-9961-e0557d87b314', '送李山人歸山', '送李山人归山', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["來從千山萬山裏，歸向千山萬山去。","山中白雲千萬重，却望人間不知處。"]', '["来從千山万山裏，归向千山万山去。","山中白云千万重，却望人间不知处。"]', '诗', 'shi', '', NULL, '送李山人歸山 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580d480c-8c0f-4639-8a13-0acdf798bb44', '長安新晴', '长安新晴', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["九重深淺人不知，金殿玉樓倚朝日。","一夜城中新雨晴，御溝流得宮花出。"]', '["九重深淺人不知，金殿玉楼倚朝日。","一夜城中新雨晴，御溝流得宮花出。"]', '诗', 'shi', '', NULL, '長安新晴 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51e76f1b-82f4-452e-aaa1-d2845d291d3a', '出藍田關寄董使君', '出藍田关寄董使君', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["萬里煙蘿錦帳間，雲迎水送度藍關。","七盤九折難行處，盡是龔黃界外山。"]', '["万里煙蘿錦帳间，云迎水送度藍关。","七盤九折难行处，尽是龔黄界外山。"]', '诗', 'shi', '', NULL, '出藍田關寄董使君 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13dbda0-85d1-426a-b4e6-a15c4bdecbd1', '題悟公禪室', '題悟公禪室', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["臨壇付法十三春，家本長城若下人。","芸閣少年應不識，南山鈔主是前身。"]', '["臨壇付法十三春，家本长城若下人。","芸閣少年應不識，南山鈔主是前身。"]', '诗', 'shi', '', NULL, '題悟公禪室 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35a1a7f0-4644-4ca3-9a7d-48d5cb171cd6', '宿陝府北樓奉酬崔大夫二首 一', '宿陝府北楼奉酬崔大夫二首 一', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["樓壓黃河山滿坐，風清水涼誰忍臥。","人定軍州禁漏傳，不妨秋月城頭過。"]', '["楼壓黄河山满坐，风清水涼誰忍臥。","人定軍州禁漏傳，不妨秋月城头過。"]', '诗', 'shi', '', NULL, '宿陝府北樓奉酬崔大夫二首 一 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67f1d84b-aa3a-4104-8512-09586d600b28', '宿陝府北樓奉酬崔大夫二首 二', '宿陝府北楼奉酬崔大夫二首 二', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["一別朱門三四春，再來應笑尚風塵。","昨宵唯有樓前月，識是謝公詩酒人。"]', '["一別朱门三四春，再来應笑尚风塵。","昨宵唯有楼前月，識是謝公诗酒人。"]', '诗', 'shi', '', NULL, '宿陝府北樓奉酬崔大夫二首 二 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d70b3a28-0ff7-43f3-818d-c2ba98479eb0', '陝州逢竇鞏同宿寄江陵韋協律', '陝州逢竇鞏同宿寄江陵韋協律', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["共出丘門歲九霜，相逢悽愴對離觴。","荆南爲報韋從事，一宿同眠御史牀。"]', '["共出丘门歲九霜，相逢悽愴对離觴。","荆南爲報韋從事，一宿同眠御史牀。"]', '诗', 'shi', '', NULL, '陝州逢竇鞏同宿寄江陵韋協律 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ff0b835-4837-40d4-a264-c2ace9051b8e', '夜到泗州酬崔使君', '夜到泗州酬崔使君', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["徐城洪盡到淮頭，月裏山河見泗州。","聞道泗濱清廟磬，雅聲今在謝家樓。"]', '["徐城洪尽到淮头，月裏山河见泗州。","闻道泗濱清廟磬，雅声今在謝家楼。"]', '诗', 'shi', '', NULL, '夜到泗州酬崔使君 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc336f06-f9fc-43ca-a7b9-12b47c3b3c70', '送崔員外使回入京金鉤驛逢因贈', '送崔員外使回入京金鉤驛逢因贈', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["六星宮裏一星歸，行到金鉤近紫微。","侍史別來經歲月，今宵應夢護香衣。"]', '["六星宮裏一星归，行到金鉤近紫微。","侍史別来經歲月，今宵應梦護香衣。"]', '诗', 'shi', '', NULL, '送崔員外使回入京金鉤驛逢因贈 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9dcbfdf-c6bd-4c6c-a974-10718827d5f9', '成都送別費冠卿', '成都送別費冠卿', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["紅椒花落桂花開，萬里同遊俱未回。","莫厭客中頻送客，思鄉獨上望鄉臺。"]', '["紅椒花落桂花开，万里同游俱未回。","莫厭客中頻送客，思乡独上望乡台。"]', '诗', 'shi', '', NULL, '成都送別費冠卿 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b4abe66-a315-4d17-baa0-f4c95bbd7acc', '題商山廟', '題商山廟', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["商洛秦時四老翁，人傳羽化此山空。","若無仙眼何由見，總在廟前花洞中。"]', '["商洛秦时四老翁，人傳羽化此山空。","若無仙眼何由见，總在廟前花洞中。"]', '诗', 'shi', '', NULL, '題商山廟 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6148328-6ccd-497b-9094-f083a44efc13', '題獨孤少府園林', '題独孤少府园林', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["四面青山是四隣，煙霞成伴草成茵。","年年洞口桃花發，不記曾經迷幾人。"]', '["四面青山是四隣，煙霞成伴草成茵。","年年洞口桃花發，不記曾經迷幾人。"]', '诗', 'shi', '', NULL, '題獨孤少府園林 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8850b9b6-4019-4c0b-b5a1-a887c3078a87', '送獨孤秀才下第歸太白山', '送独孤秀才下第归太白山', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["逸翮暫時成落羽，將歸太白賞靈蹤。","須尋最近碧霄處，擬倩和雲買一峰。"]', '["逸翮暫时成落羽，將归太白賞靈蹤。","須尋最近碧霄处，擬倩和云買一峰。"]', '诗', 'shi', '', NULL, '送獨孤秀才下第歸太白山 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232e8dc7-428a-4962-a762-f26c5943eb99', '下第後病中', '下第後病中', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["獻玉頻年命未通，窮秋成病悟真空。","笑看朝市趨名者，不病那知在病中。"]', '["獻玉頻年命未通，窮秋成病悟真空。","笑看朝市趨名者，不病那知在病中。"]', '诗', 'shi', '', NULL, '下第後病中 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32d01daf-c054-427c-a3f4-097ec0aff53b', '送深上人歸江南', '送深上人归江南', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["留得蓮花偈付誰，獨攜金策欲歸時。","江南無限蕭家寺，曾與白雲何處期。"]', '["留得蓮花偈付誰，独携金策欲归时。","江南無限蕭家寺，曾與白云何处期。"]', '诗', 'shi', '', NULL, '送深上人歸江南 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c3efe0a-27ee-4199-a746-a5a5a5d5bfa9', '題自然觀', '題自然观', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["劒閣門西第一峰，道陵成道有高蹤。","行人若上升仙處，須撥白雲三四重。"]', '["劒閣门西第一峰，道陵成道有高蹤。","行人若上升仙处，須撥白云三四重。"]', '诗', 'shi', '', NULL, '題自然觀 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99d06c2f-a303-457c-ac19-a567f5d8390e', '疾愈步庭花', '疾愈步庭花', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["桃紅李白覺春歸，強步閑庭力尚微。","從困不扶靈壽杖，恐驚花裏早鶯飛。"]', '["桃紅李白覺春归，強步闲庭力尚微。","從困不扶靈壽杖，恐驚花裏早鶯飞。"]', '诗', 'shi', '', NULL, '疾愈步庭花 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df1bb17-4bab-4729-9a5b-14387ba68788', '籌筆店江亭', '籌笔店江亭', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["九折巖邊下馬行，江亭暫歇聽江聲。","白雲綠樹不關我，枉與樵人樂一生。"]', '["九折巖邊下马行，江亭暫歇听江声。","白云綠樹不关我，枉與樵人乐一生。"]', '诗', 'shi', '', NULL, '籌筆店江亭 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f69ae29d-eac1-41ec-aee9-07f67d9bb0f8', '贈賀若少府', '贈賀若少府', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["十日廣陵城裏住，聽君花下撫金徽。","新聲指上懷中紙，莫怪潛偷數曲歸。"]', '["十日廣陵城裏住，听君花下撫金徽。","新声指上懷中紙，莫怪潛偷數曲归。"]', '诗', 'shi', '', NULL, '贈賀若少府 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0255d23-1e3b-4c2d-a6bf-7deb4477ade6', '太子劉舍人邀看花', '太子劉舍人邀看花', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["年少風流七品官，朱衣白馬冶遊盤。","負心不報春光主，幾處偷看紅牡丹。"]', '["年少风流七品官，朱衣白马冶游盤。","負心不報春光主，幾处偷看紅牡丹。"]', '诗', 'shi', '', NULL, '太子劉舍人邀看花 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68791e4c-e218-4c8a-a8f7-67d7ddc604f6', '薔薇花', '薔薇花', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["錦窠花朵燈業醉，翠葉眉稠裛露垂。","莫引美人來架下，恐驚紅片落燕支。"]', '["錦窠花朵灯業醉，翠葉眉稠裛露垂。","莫引美人来架下，恐驚紅片落燕支。"]', '诗', 'shi', '', NULL, '薔薇花 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e433281-8d3a-4130-8fb1-485f608d3000', '句', '句', '218c2102-f8ca-475a-ad09-686a89192543', '唐', '["蜀道易，易於履平地。","蟬噪入雲樹，風開無主花。"]', '["蜀道易，易於履平地。","蟬噪入云樹，风开無主花。"]', '诗', 'shi', '', NULL, '句 陸暢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90926ca1-f8e1-4833-a322-9a81e43ab878', '應制賀邊軍支春衣 一', '應制賀邊軍支春衣 一', 'a6e68cf2-6750-4873-8b09-d948dcef70ae', '唐', '["去歲雖無戰，今年未得歸。","皇恩何以報，春日得春衣。"]', '["去歲雖無戰，今年未得归。","皇恩何以報，春日得春衣。"]', '诗', 'shi', '', NULL, '應制賀邊軍支春衣 一 柳公權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f284555-47aa-457a-b310-f2a15a0c1ecd', '應制賀邊軍支春衣 二', '應制賀邊軍支春衣 二', 'a6e68cf2-6750-4873-8b09-d948dcef70ae', '唐', '["挾纊非真纊，分衣是假衣。","從今貔武士，不憚戍金微。"]', '["挾纊非真纊，分衣是假衣。","從今貔武士，不憚戍金微。"]', '诗', 'shi', '', NULL, '應制賀邊軍支春衣 二 柳公權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d018d9d-2b84-4b09-82a0-ec35fb73d541', '應制爲宮嬪詠', '應制爲宮嬪詠', 'a6e68cf2-6750-4873-8b09-d948dcef70ae', '唐', '["不分前時忤主恩，已甘寂寞守長門。","今朝卻得君王顧，重入椒房拭淚痕。"]', '["不分前时忤主恩，已甘寂寞守长门。","今朝卻得君王顧，重入椒房拭泪痕。"]', '诗', 'shi', '', NULL, '應制爲宮嬪詠 柳公權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d66835fc-53db-4870-b00c-1f5a623d942d', '題朱審寺壁山水畫', '題朱審寺壁山水畫', 'a6e68cf2-6750-4873-8b09-d948dcef70ae', '唐', '["朱審偏能視夕嵐，洞邊深墨寫秋潭。","與君一顧西牆畫，從此看山不向南。"]', '["朱審偏能視夕嵐，洞邊深墨寫秋潭。","與君一顧西牆畫，從此看山不向南。"]', '诗', 'shi', '', NULL, '題朱審寺壁山水畫 柳公權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c5d375b-9381-49eb-b3f6-5c25d3e8049a', '閶門即事', '閶门即事', 'a6e68cf2-6750-4873-8b09-d948dcef70ae', '唐', '["耕夫占募逐樓船，春草青青萬頃田。","試上吳門看郡郭，清明幾處有新煙。"]', '["耕夫占募逐楼船，春草青青万頃田。","試上吳门看郡郭，清明幾处有新煙。"]', '诗', 'shi', '', NULL, '閶門即事 柳公權 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d2278b0-2912-48e0-9b8e-c9ed7a95024e', '貢院樓北新栽小松', '貢院楼北新栽小松', '22deb826-1dec-4e61-9e39-84c33144d597', '唐', '["拂檻愛貞容，移根自遠峰。","已曾經草沒，終不任苔封。","葉少初陵雪，鱗生欲化龍。","乘春濯雨露，得地近垣墉。","逐吹香微動，含煙色漸濃。","時迴日月照，爲謝小山松。"]', '["拂檻愛貞容，移根自远峰。","已曾經草沒，終不任苔封。","葉少初陵雪，鱗生欲化龙。","乘春濯雨露，得地近垣墉。","逐吹香微动，含煙色漸濃。","时迴日月照，爲謝小山松。"]', '诗', 'shi', '', NULL, '貢院樓北新栽小松 吳武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ac2908-f223-4498-87b5-97b9a3bd782f', '題路左佛堂', '題路左佛堂', '22deb826-1dec-4e61-9e39-84c33144d597', '唐', '["雀兒來逐颺風高，下視鷹鸇意氣豪。","自謂能生千里翼，黃昏依舊委蓬蒿。"]', '["雀兒来逐颺风高，下視鷹鸇意氣豪。","自謂能生千里翼，黄昏依旧委蓬蒿。"]', '诗', 'shi', '', NULL, '題路左佛堂 吳武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d212cafa-6d47-405f-8e4d-00124c278927', '盛山十二詩 隱月岫', '盛山十二诗 隐月岫', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["初映鉤如線，終銜鏡似鉤。","遠澄秋水色，高倚曉河流。"]', '["初映鉤如線，終銜镜似鉤。","远澄秋水色，高倚晓河流。"]', '诗', 'shi', '', NULL, '盛山十二詩 隱月岫 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a8f42ef-af07-4b36-b905-fada91ba6808', '盛山十二詩 流桮渠', '盛山十二诗 流桮渠', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["激曲縈飛箭，浮溝泛滿巵。","將來山太守，早向習家池。"]', '["激曲縈飞箭，浮溝泛满巵。","將来山太守，早向習家池。"]', '诗', 'shi', '', NULL, '盛山十二詩 流桮渠 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddadb644-49a7-452c-8ce3-85ebd55de76f', '盛山十二詩 竹巖', '盛山十二诗 竹巖', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["不資冬日秀，爲作暑天寒。","先植誠非鳳，來翔定是鸞。"]', '["不資冬日秀，爲作暑天寒。","先植誠非鳳，来翔定是鸾。"]', '诗', 'shi', '', NULL, '盛山十二詩 竹巖 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a5f66c-fe4e-475d-b9a3-ba41688cbdcf', '盛山十二詩 繡衣石榻', '盛山十二诗 繡衣石榻', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["巉巉雪中嶠，磊磊標方峭。","勿爲枕蒼山，還當礎清廟。"]', '["巉巉雪中嶠，磊磊標方峭。","勿爲枕蒼山，還當礎清廟。"]', '诗', 'shi', '', NULL, '盛山十二詩 繡衣石榻 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb98701e-e976-45da-8b05-acf763edbecc', '盛山十二詩 宿雲亭', '盛山十二诗 宿云亭', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["雨合飛危砌，天開卷曉窗。","齊平聯郭柳，帶繞抱城江。"]', '["雨合飞危砌，天开卷晓窗。","齊平聯郭柳，带繞抱城江。"]', '诗', 'shi', '', NULL, '盛山十二詩 宿雲亭 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dc66101-9b61-41a9-9e26-965eef8d818d', '盛山十二詩 梅谿', '盛山十二诗 梅谿', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["夾岸凝清素，交枝漾淺淪。","味調方薦實，臘近又先春。"]', '["夾岸凝清素，交枝漾淺淪。","味調方薦實，臘近又先春。"]', '诗', 'shi', '', NULL, '盛山十二詩 梅谿 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d64e4068-b378-431a-ab8b-6a3beffd0858', '盛山十二詩 桃塢', '盛山十二诗 桃塢', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["噴日舒紅景，通蹊茂綠陰。","終期王母摘，不羨武陵深。"]', '["噴日舒紅景，通蹊茂綠陰。","終期王母摘，不羨武陵深。"]', '诗', 'shi', '', NULL, '盛山十二詩 桃塢 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b205ed8e-ffd8-44bd-8cb4-b99c6b6c8419', '盛山十二詩 胡盧沼', '盛山十二诗 胡盧沼', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["疏鑿徒爲巧，圓窪自可澄。","倒花紛錯秀，鑑月靜涵冰。"]', '["疏鑿徒爲巧，圓窪自可澄。","倒花紛錯秀，鑑月静涵冰。"]', '诗', 'shi', '', NULL, '盛山十二詩 胡盧沼 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb7e594f-0839-47f2-88cf-4c44ccf12212', '盛山十二詩 茶嶺', '盛山十二诗 茶嶺', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["顧渚吳商絕，蒙山蜀信稀。","千叢因此始，含霞紫英肥。"]', '["顧渚吳商絕，蒙山蜀信稀。","千叢因此始，含霞紫英肥。"]', '诗', 'shi', '', NULL, '盛山十二詩 茶嶺 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53d63e78-9033-4496-9759-7d94501c8a2d', '盛山十二詩 盤石磴', '盛山十二诗 盤石磴', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["繚繞緣雲上，璘玢甃玉聯。","高高曾幾折，極目瞰秋鳶。"]', '["繚繞緣云上，璘玢甃玉聯。","高高曾幾折，極目瞰秋鳶。"]', '诗', 'shi', '', NULL, '盛山十二詩 盤石磴 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bec6a3c-5c7a-4997-b312-9df9d2ea151e', '盛山十二詩 琵琶臺', '盛山十二诗 琵琶台', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["褊地難層土，因厓遂削成。","淺深嵐嶂色，盡向此中呈。"]', '["褊地难層土，因厓遂削成。","淺深嵐嶂色，尽向此中呈。"]', '诗', 'shi', '', NULL, '盛山十二詩 琵琶臺 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef45051-e18b-4689-8736-146293c05cea', '盛山十二詩 上士缾泉', '盛山十二诗 上士缾泉', 'c188ac2b-4c5b-43c0-9435-95e1913aaa1b', '唐', '["綆汲豈無井，顛崖貴非浚。","願灑塵垢餘，一雨根莖潤。"]', '["綆汲豈無井，顛崖貴非浚。","願灑塵垢餘，一雨根莖潤。"]', '诗', 'shi', '', NULL, '盛山十二詩 上士缾泉 韋處厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('244167c5-829e-4074-99a8-2b3800479429', '客思吟', '客思吟', 'ab535ed1-cf46-401e-b901-5df8ebb09e5c', '唐', '["禾黍正離離，南園剪白芝。","細腰沈趙女，高髻唱蠻姬。","路愧前岡月，梳慚一頷絲。","鄉人不可語，獨念畏人知。"]', '["禾黍正離離，南园剪白芝。","細腰沈趙女，高髻唱蠻姬。","路愧前岡月，梳慚一頷絲。","乡人不可語，独念畏人知。"]', '诗', 'shi', '', NULL, '客思吟 楊敬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffcbaa5e-6b6a-45b1-ba5b-a5095b081e8b', '贈項斯', '贈項斯', 'ab535ed1-cf46-401e-b901-5df8ebb09e5c', '唐', '["幾度見詩詩總好，及觀標格過於詩。","平生不解藏人善，到處逢人說項斯。"]', '["幾度见诗诗總好，及观標格過於诗。","平生不解藏人善，到处逢人说項斯。"]', '诗', 'shi', '', NULL, '贈項斯 楊敬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2265ea77-fa3b-4444-9bea-21cdeeaee0a6', '句', '句', 'ab535ed1-cf46-401e-b901-5df8ebb09e5c', '唐', '["霜樹鳥棲夜，空街雀報明。","碧山相倚暮，歸鴈一行斜。"]', '["霜樹鸟棲夜，空街雀報明。","碧山相倚暮，归鴈一行斜。"]', '诗', 'shi', '', NULL, '句 楊敬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64487d0c-5df1-41fa-8da2-fcffa8b760a5', '初日照鳳樓', '初日照鳳楼', 'e822ebfd-b7e0-45d1-ad84-df720ab0cdeb', '唐', '["旭日煙雲殿，朝陽燭帝居。","斷霞生峻宇，通閣麗晴虛。","流彩連朱檻，騰輝照綺疏。","曈曨晨景裏，明滅曉光初。","戶牖仙山近，軒楹鳳翼舒。","還如王母過，遙度五雲車。"]', '["旭日煙云殿，朝陽燭帝居。","斷霞生峻宇，通閣丽晴虛。","流彩連朱檻，腾輝照綺疏。","曈曨晨景裏，明滅晓光初。","戶牖仙山近，軒楹鳳翼舒。","還如王母過，遙度五云车。"]', '诗', 'shi', '', NULL, '初日照鳳樓 李虞仲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d03acf16-8e65-4d88-b785-e70ba12fb63b', '郡齋三月下旬作', '郡斋三月下旬作', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["春事日已歇，池塘曠幽尋。","殘紅披獨墜，初綠間淺深。","偃仰倦芳褥，顧步愛新陰。","謀春未及竟，夏初遽見侵。"]', '["春事日已歇，池塘曠幽尋。","殘紅披独墜，初綠间淺深。","偃仰倦芳褥，顧步愛新陰。","謀春未及竟，夏初遽见侵。"]', '诗', 'shi', '', NULL, '郡齋三月下旬作 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6848174-0e38-41e8-90df-8015dc3afcef', '五月水邊柳', '五月水邊柳', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["結根挺涯涘，垂影覆清淺。","睡臉寒未開，嬾腰晴更軟。","搖空條已重，拂水帶方展。","似醉煙景凝，如愁月露泫。","絲長魚悞恐，枝弱禽驚踐。","悵別幾多情，含春任攀搴。"]', '["結根挺涯涘，垂影覆清淺。","睡臉寒未开，嬾腰晴更軟。","搖空條已重，拂水带方展。","似醉煙景凝，如愁月露泫。","絲长鱼悞恐，枝弱禽驚踐。","悵別幾多情，含春任攀搴。"]', '诗', 'shi', '', NULL, '五月水邊柳 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37a1809a-57a7-4e8a-bb1e-b8f1c16df563', '三月五日陪大夫泛長沙東湖', '三月五日陪大夫泛长沙东湖', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["上巳餘風景，芳辰集遠坰。","綵舟浮泛蕩，繡轂下娉婷。","棲樹迴蔥蒨，笙歌轉杳冥。","湖光迷翡翠，草色醉蜻蜓。","鳥弄桐花日，魚飜穀雨萍。","從今留勝會，誰看畫蘭亭。"]', '["上巳餘风景，芳辰集远坰。","綵舟浮泛蕩，繡轂下娉婷。","棲樹迴蔥蒨，笙歌轉杳冥。","湖光迷翡翠，草色醉蜻蜓。","鸟弄桐花日，鱼飜穀雨萍。","從今留勝會，誰看畫蘭亭。"]', '诗', 'shi', '', NULL, '三月五日陪大夫泛長沙東湖 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f4dc3e5-f9ea-4107-ac6e-a0c3cffea693', '贈廣陵妓', '贈廣陵妓', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["雲雨分飛二十年，當時求夢不曾眠。","今來頭白重相見，還上襄王玳瑁筵。"]', '["云雨分飞二十年，當时求梦不曾眠。","今来头白重相见，還上襄王玳瑁筵。"]', '诗', 'shi', '', NULL, '贈廣陵妓 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94dfe2eb-7282-4b99-a67a-93ca3fe70491', '牡丹', '牡丹', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["牡丹一朵值千金，將謂從來色最深。","今日滿欄開似雪，一生辜負看花心。"]', '["牡丹一朵值千金，將謂從来色最深。","今日满欄开似雪，一生辜負看花心。"]', '诗', 'shi', '', NULL, '牡丹 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c381285-f5f3-4f1e-8531-f88d4aa0203f', '游白鶴山', '游白鹤山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["白鶴山邊秋復春，張文宅畔少風塵。","欲驅五馬尋真隱，誰是當初□竹人。"]', '["白鹤山邊秋复春，張文宅畔少风塵。","欲驱五马尋真隐，誰是當初□竹人。"]', '诗', 'shi', '', NULL, '游白鶴山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8583618a-0931-4733-8945-75b761e34ff1', '行田詩', '行田诗', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["白石巖前湖水春，湖邊舊境有清塵。","欲追謝守行田意，今古同憂是長人。"]', '["白石巖前湖水春，湖邊旧境有清塵。","欲追謝守行田意，今古同憂是长人。"]', '诗', 'shi', '', NULL, '行田詩 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c32812-bf4c-4e8f-a71e-7fc60d8f0690', '羅浮山', '羅浮山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["江北重巒積翠濃，綺霞遙映碧芙蓉。","不知末後滄溟上，滅却瀛洲第幾峰。"]', '["江北重巒積翠濃，綺霞遙映碧芙蓉。","不知末後滄溟上，滅却瀛洲第幾峰。"]', '诗', 'shi', '', NULL, '羅浮山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44378e7f-03a5-4723-b836-a23f50318da3', '青障山', '青障山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["一派遠光澄碧月，萬株聳翠獵金飆。","陶仙謾學長生術，暑往寒來更寂寥。"]', '["一派远光澄碧月，万株聳翠獵金飆。","陶仙謾学长生術，暑往寒来更寂寥。"]', '诗', 'shi', '', NULL, '青障山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e69fe3d5-875f-4917-854f-c25f1deaa855', '中界山', '中界山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["瑟瑟峰頭玉水流，晉時遺跡更堪愁。","愁人到此勞長望，何處煙波是祖州。"]', '["瑟瑟峰头玉水流，晉时遺跡更堪愁。","愁人到此勞长望，何处煙波是祖州。"]', '诗', 'shi', '', NULL, '中界山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8da3bba-9c1e-4ec1-92cf-469e04ff4c5b', '帆遊山', '帆游山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["漲海嘗從此地流，千帆飛過碧山頭。","君看深谷爲陵後，翻覆人間未肯休。"]', '["漲海嘗從此地流，千帆飞過碧山头。","君看深谷爲陵後，翻覆人间未肯休。"]', '诗', 'shi', '', NULL, '帆遊山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4939f42-aaa3-4be2-81c0-be26a1c2e549', '謝池', '謝池', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["郡郭東南積穀山，謝公曾是此躋攀。","今來惟有靈池月，猶是嬋娟一水間。"]', '["郡郭东南積穀山，謝公曾是此躋攀。","今来惟有靈池月，猶是嬋娟一水间。"]', '诗', 'shi', '', NULL, '謝池 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd989fab-9d1a-47e6-8503-034c6421d8b1', '華蓋山', '华蓋山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["一岫坡陀凝綠草，千重虛翠透紅霞。","愁來始上消歸思，見盡江城數百家。"]', '["一岫坡陀凝綠草，千重虛翠透紅霞。","愁来始上消归思，见尽江城數百家。"]', '诗', 'shi', '', NULL, '華蓋山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ae0dc08-2b4e-4a4c-ad88-c37d1fe75d62', '吹臺山', '吹台山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["吹臺山上綵煙凝，日落雲收疊翠屏。","應謂焦桐堪採斵，不知誰是柳吳興。"]', '["吹台山上綵煙凝，日落云收叠翠屏。","應謂焦桐堪採斵，不知誰是柳吳兴。"]', '诗', 'shi', '', NULL, '吹臺山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('852372d6-64ff-4341-816b-63e86e8d2e25', '青㠗山', '青㠗山', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["靈海泓澄匝翠峰，昔賢心賞已成空。","今朝亭館無遺制，積水滄浪一望中。"]', '["靈海泓澄匝翠峰，昔賢心賞已成空。","今朝亭館無遺制，積水滄浪一望中。"]', '诗', 'shi', '', NULL, '青㠗山 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c23b2e8-35ba-4933-ad6c-fe0b722dc449', '孤嶼', '孤嶼', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["碧水逶迤浮翠巘，綠蘿蒙密媚晴江。","不知誰與名孤嶼，其實中川是一雙。"]', '["碧水逶迤浮翠巘，綠蘿蒙密媚晴江。","不知誰與名孤嶼，其實中川是一雙。"]', '诗', 'shi', '', NULL, '孤嶼 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b95f7661-648c-42f9-b588-d1031babdc19', '春草池', '春草池', '89d17518-fed9-467f-9853-a5c77c8c2acf', '唐', '["謝公夢草一差微，謫宦當時道不機。","且謂飛霞遊賞地，池塘煙柳亦依依。"]', '["謝公梦草一差微，謫宦當时道不機。","且謂飞霞游賞地，池塘煙柳亦依依。"]', '诗', 'shi', '', NULL, '春草池 張又新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63f8c6d2-590e-42f7-ab7f-200d0ca8dd42', '春色滿皇州', '春色满皇州', '75c03ad7-cd15-4c8a-a61a-5f512d362917', '唐', '["帝里春光正，蔥蘢喜氣浮。","錦鋪仙禁側，鏡寫曲江頭。","紅蕚開蕭閣，黃絲拂御樓。","千門歌吹動，九陌綺羅游。","日近風先滿，仁深澤共流。","應非顦顇質，辛苦在神州。"]', '["帝里春光正，蔥蘢喜氣浮。","錦鋪仙禁側，镜寫曲江头。","紅蕚开蕭閣，黄絲拂御楼。","千门歌吹动，九陌綺羅游。","日近风先满，仁深澤共流。","應非顦顇質，辛苦在神州。"]', '诗', 'shi', '', NULL, '春色滿皇州 封敖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9b5506c-bf48-422b-8f35-3c414a46faba', '題西隱寺', '題西隐寺', '75c03ad7-cd15-4c8a-a61a-5f512d362917', '唐', '["三年未到九華山，終日披圖一室間。","秋寺喜因晴後賞，靈峰看待足時還。","猨從有性留僧坐，雲靄無心伴客閑。","勝事倘能銷歲月，已𢬵名利不相關。"]', '["三年未到九华山，終日披圖一室间。","秋寺喜因晴後賞，靈峰看待足时還。","猨從有性留僧坐，云靄無心伴客闲。","勝事倘能銷歲月，已𢬵名利不相关。"]', '诗', 'shi', '', NULL, '題西隱寺 封敖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705d39df-af3a-4d59-a434-1dbca31f4da3', '奉和白敏中聖道和平致茲休運歲終功就合詠盛明呈上', '奉和白敏中聖道和平致茲休運歲終功就合詠盛明呈上', 'ef0ebf82-7658-4726-a2ff-f2c332a74caf', '唐', '["舜德堯仁化犬戎，許提河隴欵皇風。","指揮貙武皆神算，恢拓乾坤是聖功。","四帥有征無汗馬，七關雖戍已弢弓。","天留此事還英主，不在他年在大中。"]', '["舜德堯仁化犬戎，許提河隴欵皇风。","指揮貙武皆神算，恢拓乾坤是聖功。","四帥有征無汗马，七关雖戍已弢弓。","天留此事還英主，不在他年在大中。"]', '诗', 'shi', '', NULL, '奉和白敏中聖道和平致茲休運歲終功就合詠盛明呈上 馬植 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('239b21ee-29f9-46b1-8530-64b3eb5ea970', '夏日途中', '夏日途中', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["樹夾炎風路，行人正午稀。","初蟬數聲起，戲蝶一團飛。","日色欺清鏡，槐膏點白衣。","無成歸故里，自覺少光輝。"]', '["樹夾炎风路，行人正午稀。","初蟬數声起，戲蝶一團飞。","日色欺清镜，槐膏点白衣。","無成归故里，自覺少光輝。"]', '诗', 'shi', '', NULL, '夏日途中 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bccac15-d21a-4f27-88f0-73320491822a', '長安少年行 一', '长安少年行 一', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["金紫少年郎，繞街鞍馬光。","身從左中尉，官屬右春坊。","剗戴揚州帽，重薰異國香。","垂鞭踏青草，來去杏園芳。"]', '["金紫少年郎，繞街鞍马光。","身從左中尉，官屬右春坊。","剗戴揚州帽，重薰異国香。","垂鞭踏青草，来去杏园芳。"]', '诗', 'shi', '', NULL, '長安少年行 一 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9cad4e9-45f5-4a7f-8a5c-c6fc6b3bf40f', '長安少年行 二', '长安少年行 二', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["追逐輕薄伴，閑遊不著緋。","長攏出獵馬，數換打毬衣。","曉日尋花去，春風帶酒歸。","青樓無晝夜，歌舞歇時稀。"]', '["追逐轻薄伴，闲游不著緋。","长攏出獵马，數換打毬衣。","晓日尋花去，春风带酒归。","青楼無晝夜，歌舞歇时稀。"]', '诗', 'shi', '', NULL, '長安少年行 二 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7de110c-eab1-4b7c-a104-c6eac4082551', '長安少年行 三', '长安少年行 三', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["日高春睡足，帖馬賞年華。","倒插銀魚袋，行隨金犢車。","還攜新市酒，遠醉曲江花。","幾度歸侵黑，金吾送到家。"]', '["日高春睡足，帖马賞年华。","倒插銀鱼袋，行隨金犢车。","還携新市酒，远醉曲江花。","幾度归侵黑，金吾送到家。"]', '诗', 'shi', '', NULL, '長安少年行 三 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ee29981-5d91-4ab2-8741-aec7a2b312ea', '長安少年行 四', '长安少年行 四', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["好勝耽長夜，天明燭滿樓。","留人看獨脚，賭馬換偏頭。","樂奏曾無歇，盃巡不暫休。","時時遙冷笑，怪客有春愁。"]', '["好勝耽长夜，天明燭满楼。","留人看独脚，賭马換偏头。","乐奏曾無歇，盃巡不暫休。","时时遙冷笑，怪客有春愁。"]', '诗', 'shi', '', NULL, '長安少年行 四 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab9193b7-f8f2-4ea2-89b6-2e3901600741', '長安少年行 五', '长安少年行 五', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["遨遊攜豔妓，裝束似男兒。","盃酒逢花住，笙歌簇馬吹。","鶯聲催曲忽，春色送歸遲。","不以聞街鼓，華筵待月移。"]', '["遨游携豔妓，裝束似男兒。","盃酒逢花住，笙歌簇马吹。","鶯声催曲忽，春色送归遲。","不以闻街鼓，华筵待月移。"]', '诗', 'shi', '', NULL, '長安少年行 五 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cec2316-98eb-4847-b9e7-afd610e692af', '長安少年行 六', '长安少年行 六', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["賞春惟逐勝，大宅可曾歸。","不樂還逃席，多狂慣衩衣。","歌人踏日起，語燕卷簾飛。","婦好唯相妬，倡樓不醉稀。"]', '["賞春惟逐勝，大宅可曾归。","不乐還逃席，多狂慣衩衣。","歌人踏日起，語燕卷簾飞。","婦好唯相妬，倡楼不醉稀。"]', '诗', 'shi', '', NULL, '長安少年行 六 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7648538-c3fe-4e1b-9f53-a95e8d63b7a6', '長安少年行 七', '长安少年行 七', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["戟門連日閉，苦飲惜殘春。","開鎖通新客，教姬屈醉人。","倩歌牽白馬，自舞踏紅茵。","時輩皆相許，平生不負身。"]', '["戟门連日閉，苦饮惜殘春。","开鎖通新客，教姬屈醉人。","倩歌牽白马，自舞踏紅茵。","时輩皆相許，平生不負身。"]', '诗', 'shi', '', NULL, '長安少年行 七 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4684cfef-4203-40fa-b581-6983a4350dc5', '長安少年行 八', '长安少年行 八', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["新年高殿上，始見有光輝。","玉雁排方帶，金鵝立仗衣。","酒深和椀賜，馬疾打珂飛。","朝下人爭看，香街意氣歸。"]', '["新年高殿上，始见有光輝。","玉雁排方带，金鵝立仗衣。","酒深和椀賜，马疾打珂飞。","朝下人爭看，香街意氣归。"]', '诗', 'shi', '', NULL, '長安少年行 八 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99876d96-72c4-4036-b59d-93d4842c9993', '長安少年行 九', '长安少年行 九', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["遊市慵騎馬，隨姬入坐車。","樓邊聽歌吹，簾外見鶯花。","樂眼從人鬧，歸心畏日斜。","蒼頭來去報，飲伴到倡家。"]', '["游市慵騎马，隨姬入坐车。","楼邊听歌吹，簾外见鶯花。","乐眼從人鬧，归心畏日斜。","蒼头来去報，饮伴到倡家。"]', '诗', 'shi', '', NULL, '長安少年行 九 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ccbf8f-a42f-40f3-91da-68bcebcf0606', '長安少年行 十', '长安少年行 十', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["小婦教鸚鵡，頭邊喚醉醒。","犬嬌眠玉簟，鷹掣撼金鈴。","碧地攅花障，紅泥待客亭。","雖然長按曲，不飲不曾聽。"]', '["小婦教鸚鵡，头邊喚醉醒。","犬嬌眠玉簟，鷹掣撼金鈴。","碧地攅花障，紅泥待客亭。","雖然长按曲，不饮不曾听。"]', '诗', 'shi', '', NULL, '長安少年行 十 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8303277b-eaf1-4632-8c2d-88d5d32553d6', '雞鳴曲', '雞鳴曲', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["星稀月沒入五更，膠膠角角雞初鳴。","征人牽馬出門立，辭妾欲向安西行。","再鳴引頸簷頭下，樓中角聲催上馬。","纔分曙色第二鳴，旌斾紅塵已出城。","婦人上城亂招手，夫壻不聞遙哭聲。","長恨雞鳴別時苦，不遣雞栖近窗戶。"]', '["星稀月沒入五更，膠膠角角雞初鳴。","征人牽马出门立，辞妾欲向安西行。","再鳴引頸簷头下，楼中角声催上马。","纔分曙色第二鳴，旌斾紅塵已出城。","婦人上城亂招手，夫壻不闻遙哭声。","长恨雞鳴別时苦，不遣雞栖近窗戶。"]', '诗', 'shi', '', NULL, '雞鳴曲 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ce633d-ba79-4194-8c52-9c3cfd6ea283', '鏡聽詞', '镜听词', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["匣中取鏡辭竈王，羅衣掩盡明月光。","昔時長著照容色，今夜潛將聽消息。","門前地黑人來稀，無人錯道朝夕歸。","更深弱體冷如鐵，繡帶菱花懷裏熱。","銅片銅片如有靈，願照得見行人千里形。"]', '["匣中取镜辞竈王，羅衣掩尽明月光。","昔时长著照容色，今夜潛將听消息。","门前地黑人来稀，無人錯道朝夕归。","更深弱體冷如鐵，繡带菱花懷裏熱。","銅片銅片如有靈，願照得见行人千里形。"]', '诗', 'shi', '', NULL, '鏡聽詞 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8265398b-e695-416b-8449-4d3d1a862a10', '猛士行', '猛士行', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["戰鼓驚沙惡天色，猛士虬髯眼前黑。","單于衣錦日行兵，陣頭走馬生擒得。","幽幷少年不敢輕，虎狼窟裏空手行。"]', '["戰鼓驚沙惡天色，猛士虬髯眼前黑。","單于衣錦日行兵，陣头走马生擒得。","幽幷少年不敢轻，虎狼窟裏空手行。"]', '诗', 'shi', '', NULL, '猛士行 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4aa75b7-237a-4b9c-a558-8b98be074ccd', '送振武將軍', '送振武將軍', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["葉葉歸邊騎，風頭萬里乾。","金裝腰帶重，鐵縫耳衣寒。","蘆酒燒蓬煖，霜鴻撚箭看。","黃河古戍道，秋雪白漫漫。"]', '["葉葉归邊騎，风头万里乾。","金裝腰带重，鐵縫耳衣寒。","蘆酒燒蓬煖，霜鴻撚箭看。","黄河古戍道，秋雪白漫漫。"]', '诗', 'shi', '', NULL, '送振武將軍 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('003c0582-b66e-4d14-a268-c34dcba97eb9', '落第', '落第', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["牓前潛制淚，衆裏自嫌身。","氣味如中酒，情懷似別人。","煖風張樂席，晴日看花塵。","盡是添愁處，深居乞過春。"]', '["牓前潛制泪，衆裏自嫌身。","氣味如中酒，情懷似別人。","煖风張乐席，晴日看花塵。","尽是添愁处，深居乞過春。"]', '诗', 'shi', '', NULL, '落第 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f954ad69-29d1-47de-975a-5b0118730758', '贈商山東于嶺僧', '贈商山东于嶺僧', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["商嶺東西路欲分，兩間茅屋一溪雲。","師言耳重知師意，人是人非不欲聞。"]', '["商嶺东西路欲分，兩间茅屋一溪云。","師言耳重知師意，人是人非不欲闻。"]', '诗', 'shi', '', NULL, '贈商山東于嶺僧 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b991e53-204d-40fb-b24c-3768bf8a4ff2', '上令狐舍人', '上令狐舍人', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["名利生愁地，貧居歲月移。","買書添架上，斷酒過花時。","宿客嫌吟苦，乖童恨睡遲。","近來唯儉靜，持此荅深知。"]', '["名利生愁地，貧居歲月移。","買书添架上，斷酒過花时。","宿客嫌吟苦，乖童恨睡遲。","近来唯儉静，持此荅深知。"]', '诗', 'shi', '', NULL, '上令狐舍人 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6106ee78-eef7-4b61-93c5-21e2a0e329c2', '南梁行', '南梁行', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["江城鬱鬱春草長，悠悠漢水浮青光。","雜英飛盡空晝景，綠楊重陰官舍靜。","此時醉客縱橫書，公言可薦承明廬。","青天詔下寵光至，頒籍金閨徵石渠。","秭歸山路煙嵐隔，山木幽深晚花拆。","澗底紅光奪火燃，搖風扇毒愁行客。","杜鵑啼咽花亦殷，聲悲絕豔連空山。","斜陽瞥映淺深樹，雲雨翻迷崖谷間。","山雞錦質矜毛羽，透竹穿蘿命儔侶。","喬木幽谿上下同，雄雌不惑飛棲處。","望秦峰迴過商顏，浪疊雲堆萬簇山。","行盡杳冥青嶂外，九重鐘漏紫霄間。","元和列侍明光殿，諫草初焚市朝變。","北闕趨承半隙塵，南梁笑客皆飛霰。","追思感歎却昏迷，霜鬢愁吟到曉雞。","故篋歲深開斷簡，秋堂月曙掩遺題。","嗚嗚曉角霞輝粲，撫劒當應一長歎。","芻狗無由學聖賢，空持感激終昏旦。"]', '["江城鬱鬱春草长，悠悠漢水浮青光。","杂英飞尽空晝景，綠楊重陰官舍静。","此时醉客縱橫书，公言可薦承明廬。","青天詔下寵光至，頒籍金閨徵石渠。","秭归山路煙嵐隔，山木幽深晚花拆。","澗底紅光奪火燃，搖风扇毒愁行客。","杜鵑啼咽花亦殷，声悲絕豔連空山。","斜陽瞥映淺深樹，云雨翻迷崖谷间。","山雞錦質矜毛羽，透竹穿蘿命儔侶。","喬木幽谿上下同，雄雌不惑飞棲处。","望秦峰迴過商顏，浪叠云堆万簇山。","行尽杳冥青嶂外，九重鐘漏紫霄间。","元和列侍明光殿，諫草初焚市朝变。","北闕趨承半隙塵，南梁笑客皆飞霰。","追思感歎却昏迷，霜鬢愁吟到晓雞。","故篋歲深开斷簡，秋堂月曙掩遺題。","嗚嗚晓角霞輝粲，撫劒當應一长歎。","芻狗無由学聖賢，空持感激終昏旦。"]', '诗', 'shi', '', NULL, '南梁行 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd879428-876f-438d-a803-e7d4012a15d3', '趨翰苑遭誣搆四十六韻', '趨翰苑遭誣搆四十六韻', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["九五當乾德，三千應瑞符。","纂堯昌聖曆，宗禹盛丕圖。","畫象垂新令，消兵易舊謨。","選賢方去智，招諫忽升愚。","大樂調元氣，神功運化罏。","脫鱗超沆瀣，翻翼集蓬壺。","捧日恩光別，抽毫顧問殊。","鳳形憐彩筆，龍頷借驪珠。","擲地聲名寡，摩天羽翮孤。","潔身酬雨露，利口扇讒諛。","碧海同宸眷，鴻毛比賤軀。","辨疑分黑白，舉直觝朋徒。","庭獸方呈角，階蓂始効莩。","日傾烏掩魄，星落斗摧樞。","墜劒悲喬岳，號弓泣鼎湖。","亂羣逢害馬，擇肉縱狂貙。","膽爲隳肝竭，心因瀝血枯。","滿帆摧駭浪，征棹折危途。","燕客書方詐，堯門信未孚。","謗興金就鑠，毀極玉生瘉。","礪吻矜先搏，張羅騁疾驅。","地嫌稀魍魎，海恨止番禺。","瘴嶺衝蛇入，蒸池躡虺趨。","望天收雪涕，看鏡攬霜鬚。","草毒人驚剪，茅荒室未誅。","火風晴處扇，山鬼雨中呼。","窮老鄉關遠，羇愁骨肉無。","鵲靈窺牖戶，龜瑞出泥途。","煙島深千瘴，滄波淼四隅。","海標傳信使，江棹認妻孥。","到接三冬暮，來經六月徂。","暗灘朝不怒，驚瀨夜無虞。","俛首安羸業，齊眉慰病夫。","涸魚思雨潤，僵燕望雷蘇。","詔下因頒朔，恩移詎省辜。","誑天猶指鹿，依社尚憑狐。","度嶺瞻牛斗，浮江淬轆轤。","未平人睚眦，誰懼鬼揶揄。","盆浦潮通楚，匡山地接吳。","庾樓清桂滿，遠寺素蓮敷。","髣髴皆停馬，悲歡盡隙駒。","舊交封宿草，衰鬢重生芻。","萬戟分梁苑，雙旌寄魯儒。","駸駸移歲月，冉冉近桑榆。","疲馬愁千里，孤鴻念五湖。","終當賦歸去，那更學楊朱。"]', '["九五當乾德，三千應瑞符。","纂堯昌聖曆，宗禹盛丕圖。","畫象垂新令，消兵易旧謨。","選賢方去智，招諫忽升愚。","大乐調元氣，神功運化罏。","脫鱗超沆瀣，翻翼集蓬壺。","捧日恩光別，抽毫顧问殊。","鳳形怜彩笔，龙頷借驪珠。","擲地声名寡，摩天羽翮孤。","潔身酬雨露，利口扇讒諛。","碧海同宸眷，鴻毛比賤軀。","辨疑分黑白，舉直觝朋徒。","庭獸方呈角，階蓂始効莩。","日傾烏掩魄，星落斗摧樞。","墜劒悲喬岳，號弓泣鼎湖。","亂羣逢害马，擇肉縱狂貙。","膽爲隳肝竭，心因瀝血枯。","满帆摧駭浪，征棹折危途。","燕客书方詐，堯门信未孚。","謗兴金就鑠，毀極玉生瘉。","礪吻矜先搏，張羅騁疾驱。","地嫌稀魍魎，海恨止番禺。","瘴嶺衝蛇入，蒸池躡虺趨。","望天收雪涕，看镜攬霜鬚。","草毒人驚剪，茅荒室未誅。","火风晴处扇，山鬼雨中呼。","窮老乡关远，羇愁骨肉無。","鵲靈窺牖戶，龟瑞出泥途。","煙島深千瘴，滄波淼四隅。","海標傳信使，江棹認妻孥。","到接三冬暮，来經六月徂。","暗灘朝不怒，驚瀨夜無虞。","俛首安羸業，齊眉慰病夫。","涸鱼思雨潤，僵燕望雷蘇。","詔下因頒朔，恩移詎省辜。","誑天猶指鹿，依社尚憑狐。","度嶺瞻牛斗，浮江淬轆轤。","未平人睚眦，誰懼鬼揶揄。","盆浦潮通楚，匡山地接吳。","庾楼清桂满，远寺素蓮敷。","髣髴皆停马，悲歡尽隙駒。","旧交封宿草，衰鬢重生芻。","万戟分梁苑，雙旌寄魯儒。","駸駸移歲月，冉冉近桑榆。","疲马愁千里，孤鴻念五湖。","終當賦归去，那更学楊朱。"]', '诗', 'shi', '', NULL, '趨翰苑遭誣搆四十六韻 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bb3897a-7460-40d1-9ec3-b4738e3f20b4', '憶春日太液池亭候對', '憶春日太液池亭候对', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["宮鶯報曉瑞煙開，三島靈禽拂水迴。","橋轉彩虹當綺殿，艦浮花鷁近蓬萊。","草承香輦王孫長，桃豔仙顏阿母栽。","簪筆此時方侍從，却思金馬笑鄒枚。"]', '["宮鶯報晓瑞煙开，三島靈禽拂水迴。","橋轉彩虹當綺殿，艦浮花鷁近蓬萊。","草承香輦王孫长，桃豔仙顏阿母栽。","簪笔此时方侍從，却思金马笑鄒枚。"]', '诗', 'shi', '', NULL, '憶春日太液池亭候對 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25f67eb0-ddd3-41e2-8aaa-7b4311465300', '憶夜直金鑾殿承旨', '憶夜直金鑾殿承旨', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["月當銀漢玉繩低，深聽簫韶碧落齊。","門壓紫垣高綺樹，閣連青瑣近丹梯。","墨宣外渥催飛詔，草布深恩促換題。","明日獨歸花路遠，可憐人世隔雲霓。"]', '["月當銀漢玉繩低，深听簫韶碧落齊。","门壓紫垣高綺樹，閣連青瑣近丹梯。","墨宣外渥催飞詔，草布深恩促換題。","明日独归花路远，可怜人世隔云霓。"]', '诗', 'shi', '', NULL, '憶夜直金鑾殿承旨 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38153c7-0c90-4503-b578-f68aa067b156', '憶春日曲江宴後許至芙蓉園', '憶春日曲江宴後許至芙蓉园', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["春風上苑開桃李，詔許看花入御園。","香徑草中迴玉勒，鳳皇池畔泛金樽。","綠絲垂柳遮風暗，紅藥低叢拂砌繁。","歸繞曲江煙景晚，未央明月鎖千門。"]', '["春风上苑开桃李，詔許看花入御园。","香徑草中迴玉勒，鳳皇池畔泛金樽。","綠絲垂柳遮风暗，紅藥低叢拂砌繁。","归繞曲江煙景晚，未央明月鎖千门。"]', '诗', 'shi', '', NULL, '憶春日曲江宴後許至芙蓉園 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e3ee002-494b-4e6d-95d1-f1b6b3973531', '新昌宅書堂前有藥樹一株今已盈拱前長慶中於翰林院內西軒藥樹下移得纔長一寸僕夫封一泥丸以歸植今則長成名之天上樹', '新昌宅书堂前有藥樹一株今已盈拱前长慶中於翰林院內西軒藥樹下移得纔长一寸僕夫封一泥丸以归植今則长成名之天上樹', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["白榆星底開紅甲，珠樹宮中長紫霄。","丹彩結心纔辨質，碧枝抽葉乍成條。","羽衣道士偷玄圃，金簡真人護玉苗。","長帶九天餘雨露，近來蔥翠欲成喬。"]', '["白榆星底开紅甲，珠樹宮中长紫霄。","丹彩結心纔辨質，碧枝抽葉乍成條。","羽衣道士偷玄圃，金簡真人護玉苗。","长带九天餘雨露，近来蔥翠欲成喬。"]', '诗', 'shi', '', NULL, '新昌宅書堂前有藥樹一株今已盈拱前長慶中於翰林院內西軒藥樹下移得纔長一寸僕夫封一泥丸以歸植今則長成名之天上樹 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c242db18-67cc-4326-8be0-a1a8a6a65188', '過荆門', '過荆门', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["荆江水闊煙波轉，荆門路遶山蔥蒨。","帆勢侵雲滅又明，山程背日昏還見。","青青麥隴啼飛鴉，寂寞野徑棠梨花。","行行驅馬萬里遠，漸入煙嵐危棧賒。","林中有鳥飛出谷，月上千巖一聲哭。","腸斷思歸不可聞，人言恨魄來巴蜀。","我聽此鳥祝我魂，魂死莫學聲銜冤。","縱爲羽族莫棲息，直上青雲呼帝閽。","此時山月如銜鏡，嵒樹參差互輝映。","皎潔深看入澗泉，分明細見樵人徑。","陰森鬼廟當郵亭，雞豚日宰聞膻腥。","愚夫禍福自迷惑，魍魎憑何通百靈。","月低山曉問行客，已酹椒漿拜荒陌。","惆悵忠貞徒自持，誰祭山頭望夫石。"]', '["荆江水闊煙波轉，荆门路遶山蔥蒨。","帆勢侵云滅又明，山程背日昏還见。","青青麦隴啼飞鴉，寂寞野徑棠梨花。","行行驱马万里远，漸入煙嵐危棧賒。","林中有鸟飞出谷，月上千巖一声哭。","腸斷思归不可闻，人言恨魄来巴蜀。","我听此鸟祝我魂，魂死莫学声銜冤。","縱爲羽族莫棲息，直上青云呼帝閽。","此时山月如銜镜，嵒樹參差互輝映。","皎潔深看入澗泉，分明細见樵人徑。","陰森鬼廟當郵亭，雞豚日宰闻膻腥。","愚夫禍福自迷惑，魍魎憑何通百靈。","月低山晓问行客，已酹椒漿拜荒陌。","惆悵忠貞徒自持，誰祭山头望夫石。"]', '诗', 'shi', '', NULL, '過荆門 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a04b03-7a41-4faa-9e46-c8d6fb228bb0', '涉沅瀟', '涉沅瀟', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["屈原死處瀟湘陰，滄浪淼淼雲沈沈。","蛟龍長怒虎長嘯，山木翛翛波浪深。","煙橫日落驚鴻起，山映餘霞杳千里。","鴻叫離離入暮天，霞消漠漠深雲水。","水靈江暗揚波濤，黿鼉動盪風騷騷。","行人愁望待明月，星漢沈浮𩳤鬼號。","屈原爾爲懷王沒，水府通天化靈物。","何不驅雷擊電除奸邪，可憐空作沈泉骨。","舉杯瀝酒招爾魂，月影滉漾開乾坤。","波白水黑山隱見，汨羅之上遙昏昏。","風帆候曉看五兩，戍鼓鼕鼕遠山響。","潮滿江津猨鳥啼，荆夫楚語飛蠻槳。","瀟湘島浦無人居，風驚水暗惟鮫魚。","行來擊棹獨長歎，問爾精魄何所如。"]', '["屈原死处瀟湘陰，滄浪淼淼云沈沈。","蛟龙长怒虎长嘯，山木翛翛波浪深。","煙橫日落驚鴻起，山映餘霞杳千里。","鴻叫離離入暮天，霞消漠漠深云水。","水靈江暗揚波濤，黿鼉动盪风騷騷。","行人愁望待明月，星漢沈浮𩳤鬼號。","屈原爾爲懷王沒，水府通天化靈物。","何不驱雷擊電除奸邪，可怜空作沈泉骨。","舉杯瀝酒招爾魂，月影滉漾开乾坤。","波白水黑山隐见，汨羅之上遙昏昏。","风帆候晓看五兩，戍鼓鼕鼕远山响。","潮满江津猨鸟啼，荆夫楚語飞蠻槳。","瀟湘島浦無人居，风驚水暗惟鮫鱼。","行来擊棹独长歎，问爾精魄何所如。"]', '诗', 'shi', '', NULL, '涉沅瀟 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74458107-c12f-4aef-9d52-2de3205d3c12', '逾嶺嶠止荒陬抵高要', '逾嶺嶠止荒陬抵高要', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["天將南北分寒燠，北被羔裘南卉服。","寒氣凝爲戎虜驕，炎蒸結作蟲虺毒。","周王止化惟荆蠻，漢武鑿遠通孱顏。","南標銅柱限荒徼，五嶺從茲窮險艱。","衡山截斷炎方北，迴雁峰南瘴煙黑。","萬壑奔傷溢作瀧，湍飛浪激如繩直。","千崖傍聳猨嘯悲，丹蛇玄虺潛蜲蛇。","瀧夫擬檝劈高浪，瞥忽浮沈如電隨。","嶺頭刺竹蒙籠密，火拆紅蕉焰燒日。","嶺上泉分南北流，行人照水愁腸骨。","陰森石路盤縈紆，雨寒日煖常斯須。","瘴雲暫卷火山外，蒼茫海氣窮番禺。","鷓鴣猿鳥聲相續，椎髻曉呼同戚促。","百處谿灘異雨晴，四時雷電迷昏旭。","魚腸雁足望緘封，地遠三江嶺萬重。","魚躍豈通清遠峽，雁飛難渡漳江東。","雲蒸地熱無霜霰，桃李冬華匪時變。","天際長垂飲澗虹，簷前不去銜泥燕。","幸逢雷雨盪妖昏，提挈悲歡出海門。","西日眼明看少長，北風身醒辨寒溫。","賈生謫去因前席，痛哭書成竟何益。","物忌忠良表是非，朝驅絳灌爲讎敵。","明皇聖德異文皇，不使無辜困鬼方。","漢日傅臣終委棄，如今衰叟重輝光。","高明白日恩深海，齒髮雖殘壯心在。","空媿駑駘異一毛，無令朽骨慙千載。"]', '["天將南北分寒燠，北被羔裘南卉服。","寒氣凝爲戎虜驕，炎蒸結作蟲虺毒。","周王止化惟荆蠻，漢武鑿远通孱顏。","南標銅柱限荒徼，五嶺從茲窮險艱。","衡山截斷炎方北，迴雁峰南瘴煙黑。","万壑奔傷溢作瀧，湍飞浪激如繩直。","千崖傍聳猨嘯悲，丹蛇玄虺潛蜲蛇。","瀧夫擬檝劈高浪，瞥忽浮沈如電隨。","嶺头刺竹蒙籠密，火拆紅蕉焰燒日。","嶺上泉分南北流，行人照水愁腸骨。","陰森石路盤縈紆，雨寒日煖常斯須。","瘴云暫卷火山外，蒼茫海氣窮番禺。","鷓鴣猿鸟声相續，椎髻晓呼同戚促。","百处谿灘異雨晴，四时雷電迷昏旭。","鱼腸雁足望緘封，地远三江嶺万重。","鱼躍豈通清远峽，雁飞难渡漳江东。","云蒸地熱無霜霰，桃李冬华匪时变。","天際长垂饮澗虹，簷前不去銜泥燕。","幸逢雷雨盪妖昏，提挈悲歡出海门。","西日眼明看少长，北风身醒辨寒溫。","賈生謫去因前席，痛哭书成竟何益。","物忌忠良表是非，朝驱絳灌爲讎敵。","明皇聖德異文皇，不使無辜困鬼方。","漢日傅臣終委棄，如今衰叟重輝光。","高明白日恩深海，齒髮雖殘壯心在。","空媿駑駘異一毛，無令朽骨慙千載。"]', '诗', 'shi', '', NULL, '逾嶺嶠止荒陬抵高要 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f343153-68ff-4ee9-b922-02cadd765bd6', '移九江', '移九江', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["秋波入白水，帆去侵空小。","五兩劇奔星，檣烏疾飛鳥。","盆城依落日，盆浦看雲眇。","雲眇更蒼蒼，匡山低夕陽。","楚客喜風水，秦人悲異鄉。","異鄉秋思苦，江臯月華吐。","漾漾隱波亭，悠悠通月浦。","津橋歸候吏，竹巷開門戶。","容膝有匡牀，及肩纔數堵。","隙光非白駒，懸磬我無虞。","體瘦寡行立，家肥安啜哺。","天書憐譴謫，重作朱轓客。","四座眼全青，一麾頭半白。","今來思往事，往事益悽然。","風月同今昔，悲歡異目前。","四時嗟閱水，一紀換流年。","獨有西庭鶴，孤鳴白露天。"]', '["秋波入白水，帆去侵空小。","五兩劇奔星，檣烏疾飞鸟。","盆城依落日，盆浦看云眇。","云眇更蒼蒼，匡山低夕陽。","楚客喜风水，秦人悲異乡。","異乡秋思苦，江臯月华吐。","漾漾隐波亭，悠悠通月浦。","津橋归候吏，竹巷开门戶。","容膝有匡牀，及肩纔數堵。","隙光非白駒，懸磬我無虞。","體瘦寡行立，家肥安啜哺。","天书怜譴謫，重作朱轓客。","四座眼全青，一麾头半白。","今来思往事，往事益悽然。","风月同今昔，悲歡異目前。","四时嗟閱水，一紀換流年。","独有西庭鹤，孤鳴白露天。"]', '诗', 'shi', '', NULL, '移九江 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbfa6652-e5ef-48ce-a1ce-03e0487ae0bb', '泛五湖', '泛五湖', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["范子蛻冠履，扁舟逸霄漢。","嗟予抱險艱，怵惕驚瀰漫。","窮通泛濫勞，趣適殊昏旦。","浴日盪層空，浮天淼無畔。","依灘落葉聚，立浦驚鴻散。","浪疊雪峰連，山孤翠崖斷。","風帆同巨壑，雲矗成高岸。","宇宙可東西，星辰沈粲爛。","霞生[澒]洞遠，月吐青熒亂。","豈復問津迷，休爲呂梁歎。","漂沈自詎保，覆溺心長判。","吳越郡異鄉，嬰童及爲翫。","依稀占井邑，嘹唳同鵝鸛。","舉棹未宵分，維舟方日旰。","徵斯濟川力，若鼓凌風翰。","易狎當悔游，臨深罔知難。"]', '["范子蛻冠履，扁舟逸霄漢。","嗟予抱險艱，怵惕驚瀰漫。","窮通泛濫勞，趣適殊昏旦。","浴日盪層空，浮天淼無畔。","依灘落葉聚，立浦驚鴻散。","浪叠雪峰連，山孤翠崖斷。","风帆同巨壑，云矗成高岸。","宇宙可东西，星辰沈粲爛。","霞生[澒]洞远，月吐青熒亂。","豈复问津迷，休爲呂梁歎。","漂沈自詎保，覆溺心长判。","吳越郡異乡，嬰童及爲翫。","依稀占井邑，嘹唳同鵝鸛。","舉棹未宵分，維舟方日旰。","徵斯濟川力，若鼓凌风翰。","易狎當悔游，臨深罔知难。"]', '诗', 'shi', '', NULL, '泛五湖 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1963d69d-9c2f-4385-8665-5c134cbeee92', '過鍾陵', '過鍾陵', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["龍沙江尾抱鍾陵，水郭村橋晚景澄。","江對楚山千里月，郭連漁浦萬家燈。","省拋雙斾辭榮寵，遽落丹霄起愛憎。","惆悵舊遊同草露，却思恩顧一霑膺。"]', '["龙沙江尾抱鍾陵，水郭村橋晚景澄。","江对楚山千里月，郭連漁浦万家灯。","省拋雙斾辞榮寵，遽落丹霄起愛憎。","惆悵旧游同草露，却思恩顧一霑膺。"]', '诗', 'shi', '', NULL, '過鍾陵 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1929a827-9087-41b7-aaf1-4ebfd3f78b07', '泝西江', '泝西江', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["江風不定半晴陰，愁對花時盡日吟。","孤棹自遲從蹭蹬，亂帆爭疾競浮沈。","一身累困懷千載，百口無虞貴萬金。","空闊遠看波浪息，楚山安穩過雲岑。"]', '["江风不定半晴陰，愁对花时尽日吟。","孤棹自遲從蹭蹬，亂帆爭疾競浮沈。","一身累困懷千載，百口無虞貴万金。","空闊远看波浪息，楚山安穩過云岑。"]', '诗', 'shi', '', NULL, '泝西江 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c4a2b87-1e95-4cb0-a26c-cc4381994944', '早發', '早發', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["沙洲月落宿禽驚，潮起風微曉霧生。","黃鶴浪明知上信，黑龍山暗避前程。","火旗似辨吳門戍，水驛遙迷楚塞城。","蕭索更看江葉下，兩鄉俱是宦遊情。"]', '["沙洲月落宿禽驚，潮起风微晓霧生。","黄鹤浪明知上信，黑龙山暗避前程。","火旗似辨吳门戍，水驛遙迷楚塞城。","蕭索更看江葉下，兩乡俱是宦游情。"]', '诗', 'shi', '', NULL, '早發 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77c91095-de25-4b2e-b747-4645ceaee538', '守滁陽深秋憶登郡城望瑯琊', '守滁陽深秋憶登郡城望瑯琊', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["山城小閣臨青嶂，紅樹蓮宮接薜蘿。","斜日半巖開古殿，野煙浮水掩輕波。","菊迎秋節西風急，雁引砧聲北思多。","深夜獨吟還不寐，坐看凝露滿庭莎。"]', '["山城小閣臨青嶂，紅樹蓮宮接薜蘿。","斜日半巖开古殿，野煙浮水掩轻波。","菊迎秋節西风急，雁引砧声北思多。","深夜独吟還不寐，坐看凝露满庭莎。"]', '诗', 'shi', '', NULL, '守滁陽深秋憶登郡城望瑯琊 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81fa4e34-048d-4c00-9ad7-275ae0e2c963', '滁陽春日懷果園閑宴', '滁陽春日懷果园闲宴', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["西園到日栽桃李，紅白低枝拂酒杯。","繁豔只愁風處落，醉筵多就月中開。","勸人莫折憐芳早，把燭頻看畏曉催。","聞道數年深草露，幾株猶得近池臺。"]', '["西园到日栽桃李，紅白低枝拂酒杯。","繁豔只愁风处落，醉筵多就月中开。","勸人莫折怜芳早，把燭頻看畏晓催。","闻道數年深草露，幾株猶得近池台。"]', '诗', 'shi', '', NULL, '滁陽春日懷果園閑宴 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efb42b7c-c404-4b25-91b5-b1cbe6a87ceb', '悲善才', '悲善才', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["穆王夜幸蓬池曲，金鑾殿開高秉燭。","東頭弟子曹善才，琵琶請進新翻曲。","翠蛾列坐層城女，笙笛參差齊笑語。","天顏靜聽朱絲彈，衆樂寂然無敢舉。","銜花金鳳當承撥，轉腕攏弦促揮抹。","花翻鳳嘯天上來，裴回滿殿飛春雪。","抽弦度曲新聲發，金鈴玉珮相瑳切。","流鶯子母飛上林，仙鶴雌雄唳明月。","此時奉詔侍金鑾，別殿承恩許召彈。","三月曲江春草綠，九霄天樂下雲端。","紫髯供奉前屈膝，盡彈妙曲當春日。","寒泉注射隴水開，胡雁翻飛向天沒。","日曛塵暗車馬散，爲惜新聲有餘歎。","明年冠劒閉橋山，萬里孤臣投海畔。","籠禽鎩翮尚還飛，白首生從五嶺歸。","聞道善才成朽骨，空餘弟子奉音徽。","南譙寂寞三春晚，有客彈弦獨淒怨。","靜聽深奏楚月光，憶昔初聞曲江宴。","心悲不覺淚闌干，更爲調弦反覆彈。","秋吹動搖神女佩，月珠敲擊水晶盤。","自憐淮海同泥滓，恨魄凝心未能死。","惆悵追懷萬事空，雍門感慨徒爲爾。"]', '["穆王夜幸蓬池曲，金鑾殿开高秉燭。","东头弟子曹善才，琵琶請進新翻曲。","翠蛾列坐層城女，笙笛參差齊笑語。","天顏静听朱絲彈，衆乐寂然無敢舉。","銜花金鳳當承撥，轉腕攏弦促揮抹。","花翻鳳嘯天上来，裴回满殿飞春雪。","抽弦度曲新声發，金鈴玉珮相瑳切。","流鶯子母飞上林，仙鹤雌雄唳明月。","此时奉詔侍金鑾，別殿承恩許召彈。","三月曲江春草綠，九霄天乐下云端。","紫髯供奉前屈膝，尽彈妙曲當春日。","寒泉注射隴水开，胡雁翻飞向天沒。","日曛塵暗车马散，爲惜新声有餘歎。","明年冠劒閉橋山，万里孤臣投海畔。","籠禽鎩翮尚還飞，白首生從五嶺归。","闻道善才成朽骨，空餘弟子奉音徽。","南譙寂寞三春晚，有客彈弦独淒怨。","静听深奏楚月光，憶昔初闻曲江宴。","心悲不覺泪闌干，更爲調弦反覆彈。","秋吹动搖神女佩，月珠敲擊水晶盤。","自怜淮海同泥滓，恨魄凝心未能死。","惆悵追懷万事空，雍门感慨徒爲爾。"]', '诗', 'shi', '', NULL, '悲善才 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('004fc347-aa39-4d48-a5fa-dda718f4bbe5', '聞里謠效古歌', '闻里謠效古歌', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["鄉里兒，桑麻鬱鬱禾黍肥，冬有襤襦夏有絺。","兄鋤弟耨妻在機，夜犬不吠開蓬扉。","鄉里兒，醉還飽，濁醪初熟勸翁媼。","鳴鳩拂羽知年好，齊和楊花踏春草。","勸年少，樂耕桑。","使君爲我剪荆棘，使君爲我驅豺狼。","林中無虎山有鹿，水底無蛟魚有魴。","父漁子獵日歸暮，月明處處舂黃粱。","鄉里兒，東家父老爲爾言，鼓腹那知生育恩。","莫令太守馳朱轓，懸鼓一鳴盧鵲喧。","惡聲主吏噪爾門，唧唧力力烹雞豚。","鄉里兒，莫悲咤。","上有明王頒詔下，重選賢良恤孤寡。","春日遲遲驅五馬，留犢投錢以爲謝。","鄉里兒，終爾詞。","我無工巧唯無私，舉手一揮臨路岐。"]', '["乡里兒，桑麻鬱鬱禾黍肥，冬有襤襦夏有絺。","兄鋤弟耨妻在機，夜犬不吠开蓬扉。","乡里兒，醉還飽，濁醪初熟勸翁媼。","鳴鳩拂羽知年好，齊和楊花踏春草。","勸年少，乐耕桑。","使君爲我剪荆棘，使君爲我驱豺狼。","林中無虎山有鹿，水底無蛟鱼有魴。","父漁子獵日归暮，月明处处舂黄粱。","乡里兒，东家父老爲爾言，鼓腹那知生育恩。","莫令太守驰朱轓，懸鼓一鳴盧鵲喧。","惡声主吏噪爾门，唧唧力力烹雞豚。","乡里兒，莫悲咤。","上有明王頒詔下，重選賢良恤孤寡。","春日遲遲驱五马，留犢投錢以爲謝。","乡里兒，終爾词。","我無工巧唯無私，舉手一揮臨路岐。"]', '诗', 'shi', '', NULL, '聞里謠效古歌 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1135b21d-4885-4ba7-97a9-3ab6836ee9e9', '轉壽春守太和庚戌歲二月祗命壽陽時替裴五墉終歿因視壁題自墉而上或除名在邊坐殿歿凡七子無一存焉壽人多寇盜好訴訐時謂訐時謂之凶郡獷俗特著蒙此處之顧余衰年甘躡前患俾三月而寇靜朞歲而人和虎不暴物姦吏屏竄三載復遭邪佞所惡授賓客分司東都或舉其目或寄於風亦麤繼詩人之末云', '轉壽春守太和庚戌歲二月祗命壽陽时替裴五墉終歿因視壁題自墉而上或除名在邊坐殿歿凡七子無一存焉壽人多寇盜好訴訐时謂訐时謂之凶郡獷俗特著蒙此处之顧余衰年甘躡前患俾三月而寇静朞歲而人和虎不暴物姦吏屏竄三載复遭邪佞所惡授賓客分司东都或舉其目或寄於风亦麤繼诗人之末云', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["未登崖谷尋丹竈，且歷軒窗看壁題。","那遇八公生羽翼，空悲七子委塵泥。","舊壇無復翔雲鶴，廢壘曾經振鼓鼙。","點檢遺編盡朝菌，應難求望一刀圭。"]', '["未登崖谷尋丹竈，且歷軒窗看壁題。","那遇八公生羽翼，空悲七子委塵泥。","旧壇無复翔云鹤，廢壘曾經振鼓鼙。","点檢遺編尽朝菌，應难求望一刀圭。"]', '诗', 'shi', '', NULL, '轉壽春守太和庚戌歲二月祗命壽陽時替裴五墉終歿因視壁題自墉而上或除名在邊坐殿歿凡七子無一存焉壽人多寇盜好訴訐時謂訐時謂之凶郡獷俗特著蒙此處之顧余衰年甘躡前患俾三月而寇靜朞歲而人和虎不暴物姦吏屏竄三載復遭邪佞所惡授賓客分司東都或舉其目或寄於風亦麤繼詩人之末云 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b629da-76cc-4223-98b8-25fad7f63656', '憶壽春廢虎坑余以春二月至郡主吏舉所職稱霍山多虎每歲採茶爲患擇肉於人至春常修陷穽數十所勒獵者採其皮睛余悉除罷之是歲虎不復爲害至余去郡三載', '憶壽春廢虎坑余以春二月至郡主吏舉所職稱霍山多虎每歲採茶爲患擇肉於人至春常修陷穽數十所勒獵者採其皮睛余悉除罷之是歲虎不复爲害至余去郡三載', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["匪將履尾求兢惕，那效探雛所患爭。","當路絕羣嘗誡暴，爲猫驅獮亦先迎。","每推至化宣余力，豈用潛機害爾生。","休逐豺狼止貪戾，好爲仁獸答皇明。"]', '["匪將履尾求兢惕，那效探雛所患爭。","當路絕羣嘗誡暴，爲猫驱獮亦先迎。","每推至化宣余力，豈用潛機害爾生。","休逐豺狼止貪戾，好爲仁獸答皇明。"]', '诗', 'shi', '', NULL, '憶壽春廢虎坑余以春二月至郡主吏舉所職稱霍山多虎每歲採茶爲患擇肉於人至春常修陷穽數十所勒獵者採其皮睛余悉除罷之是歲虎不復爲害至余去郡三載 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ac7071c-cfc0-42da-acec-992c1c6b447b', '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 肥河維舟阻凍袛待勅命 一', '壽陽罷郡日有诗十首與追懷不殊今編於後兼紀瑞物 肥河維舟阻凍袛待勅命 一', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["罷分符竹作閑官，舟凍肥河擬棹難。","食蘗苦心甘處困，飲冰持操敢辭寒。","夜燈空應漁家火，朝食還依雁宿灘。","西奏血誠遙稽首，乞容歸病老江干。"]', '["罷分符竹作闲官，舟凍肥河擬棹难。","食蘗苦心甘处困，饮冰持操敢辞寒。","夜灯空應漁家火，朝食還依雁宿灘。","西奏血誠遙稽首，乞容归病老江干。"]', '诗', 'shi', '', NULL, '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 肥河維舟阻凍袛待勅命 一 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8daf794-d044-4e48-9e93-d3f2199fb848', '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 肥河維舟阻凍袛待勅命 二', '壽陽罷郡日有诗十首與追懷不殊今編於後兼紀瑞物 肥河維舟阻凍袛待勅命 二', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["淮陽效理空多病，疎受辭榮豈戀班。","陳力不任趨北闕，有家無處寄東山。","疲驂豈念前程稅，倦鳥安能待暮還。","珍重八公山下叟，不勞重淚更追攀。"]', '["淮陽效理空多病，疎受辞榮豈戀班。","陳力不任趨北闕，有家無处寄东山。","疲驂豈念前程稅，倦鸟安能待暮還。","珍重八公山下叟，不勞重泪更追攀。"]', '诗', 'shi', '', NULL, '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 肥河維舟阻凍袛待勅命 二 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55f2083d-f3ec-4f8d-8372-dabfc656e9cf', '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物', '壽陽罷郡日有诗十首與追懷不殊今編於後兼紀瑞物', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["垂陰敢慕甘棠葉，附幹將呈瑞木符。","十步蘭茶同秀彩，萬年枝葉表皇圖。","芟夷不及知無患，雨露曾霑自不枯。","好住孤根託桃李，莫令從此混樵蘇。"]', '["垂陰敢慕甘棠葉，附幹將呈瑞木符。","十步蘭茶同秀彩，万年枝葉表皇圖。","芟夷不及知無患，雨露曾霑自不枯。","好住孤根託桃李，莫令從此混樵蘇。"]', '诗', 'shi', '', NULL, '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0baf4974-11e6-4c7a-82d2-b58d174cf01e', '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物', '壽陽罷郡日有诗十首與追懷不殊今編於後兼紀瑞物', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["南山白額同馴擾，亦變仁心去殺機。","不競牛甘令買患，免遭狐假妄憑威。","渡河豈適他邦害，據谷終無暴物非。","爾效騶虞護生草，豈徒柔伏在淮淝。"]', '["南山白額同馴擾，亦变仁心去殺機。","不競牛甘令買患，免遭狐假妄憑威。","渡河豈適他邦害，據谷終無暴物非。","爾效騶虞護生草，豈徒柔伏在淮淝。"]', '诗', 'shi', '', NULL, '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e9d86e9-ec10-4a80-8545-eb7ed9541b99', '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 發壽陽分司勅到又遇新正感懷書事', '壽陽罷郡日有诗十首與追懷不殊今編於後兼紀瑞物 發壽陽分司勅到又遇新正感懷书事', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["休爲建隼臨淝守，轉作垂絲入洛人。","罷閱舊林三載籍，又開新曆四年春。","雲遮北雁愁行客，柳起東風慰病身。","漸喜雪霜消解盡，得隨風水到天津。"]', '["休爲建隼臨淝守，轉作垂絲入洛人。","罷閱旧林三載籍，又开新曆四年春。","云遮北雁愁行客，柳起东风慰病身。","漸喜雪霜消解尽，得隨风水到天津。"]', '诗', 'shi', '', NULL, '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 發壽陽分司勅到又遇新正感懷書事 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15f8df0c-2801-4421-87e8-90c683069dbf', '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 初出淝口入淮', '壽陽罷郡日有诗十首與追懷不殊今編於後兼紀瑞物 初出淝口入淮', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["東風百里雪初晴，淝口冰開好濯纓。","野老擁途知意重，病夫拋郡喜身輕。","人心莫厭如弦直，淮水長憐似鏡清。","回首夕嵐山翠遠，楚郊烟樹隱襄城。"]', '["东风百里雪初晴，淝口冰开好濯纓。","野老擁途知意重，病夫拋郡喜身轻。","人心莫厭如弦直，淮水长怜似镜清。","回首夕嵐山翠远，楚郊烟樹隐襄城。"]', '诗', 'shi', '', NULL, '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 初出淝口入淮 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d6fb4d7-d4b8-4697-b178-54da7fb70fbf', '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 入淮至盱眙', '壽陽罷郡日有诗十首與追懷不殊今編於後兼紀瑞物 入淮至盱眙', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["山凝翠黛孤峰迥，淮起銀花五兩高。","天外綺霞迷海鶴，日邊紅樹豔仙桃。","岸驚目眩同奔馬，浦溢心疑覩抃鼇。","寄謝雲帆疾飛鳥，莫誇迴雁卷輕毛。"]', '["山凝翠黛孤峰迥，淮起銀花五兩高。","天外綺霞迷海鹤，日邊紅樹豔仙桃。","岸驚目眩同奔马，浦溢心疑覩抃鼇。","寄謝云帆疾飞鸟，莫誇迴雁卷轻毛。"]', '诗', 'shi', '', NULL, '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 入淮至盱眙 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59730cd8-6333-485a-a0e8-79635c51ebb6', '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 憶東湖', '壽陽罷郡日有诗十首與追懷不殊今編於後兼紀瑞物 憶东湖', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["菱歌罷唱鷁舟迴，雪鷺銀鷗左右來。","霞散浦邊雲錦截，月昇湖面鏡波開。","魚驚翠羽金鱗躍，蓮脫紅衣紫菂摧。","淮口值春偏悵望，數株臨水是寒梅。"]', '["菱歌罷唱鷁舟迴，雪鷺銀鷗左右来。","霞散浦邊云錦截，月昇湖面镜波开。","鱼驚翠羽金鱗躍，蓮脫紅衣紫菂摧。","淮口值春偏悵望，數株臨水是寒梅。"]', '诗', 'shi', '', NULL, '壽陽罷郡日有詩十首與追懷不殊今編於後兼紀瑞物 憶東湖 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec39691c-53b0-4510-a998-77194c0daa61', '七年初到洛陽寓居宣教里時已春暮而四老俱在洛中分司', '七年初到洛陽寓居宣教里时已春暮而四老俱在洛中分司', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["青莎滿地無三徑，白髮緣頭忝四人。","官職謬齊商嶺客，姓名那重漢廷臣。","聖朝寡罪容衰齒，愚叟多慙未退身。","惟有門人憐鈍拙，勸教沈醉洛陽春。"]', '["青莎满地無三徑，白髮緣头忝四人。","官職謬齊商嶺客，姓名那重漢廷臣。","聖朝寡罪容衰齒，愚叟多慙未退身。","惟有门人怜鈍拙，勸教沈醉洛陽春。"]', '诗', 'shi', '', NULL, '七年初到洛陽寓居宣教里時已春暮而四老俱在洛中分司 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42dea9c8-8efb-46dd-b38c-a0345b3081c2', '初秋忽奉詔除浙東觀察使檢校右貂', '初秋忽奉詔除浙东观察使檢校右貂', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["龍樓寄引簪裾客，鳳闕陪趨朔望朝。","疎受杜門期脫屣，買臣歸邸忽乘軺。","印封龜紐知頒爵，冠飾蟬緌更珥貂。","飛詔寵榮歡里舍，豈徒斑白與垂髫。"]', '["龙楼寄引簪裾客，鳳闕陪趨朔望朝。","疎受杜门期脫屣，買臣归邸忽乘軺。","印封龟紐知頒爵，冠飾蟬緌更珥貂。","飞詔寵榮歡里舍，豈徒斑白與垂髫。"]', '诗', 'shi', '', NULL, '初秋忽奉詔除浙東觀察使檢校右貂 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89a6e1a0-ed9e-4194-a14f-9ecf988625ac', '憶至鞏縣河宿待家累追懷', '憶至鞏縣河宿待家累追懷', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["鞏樹翻紅秋日斜，水分伊洛照餘霞。","弓開後騎低初月，鶚駐前旌拂暮鴉。","閨信坐遲青玉案，弄兒閑望白羊車。","今來憶事涼風晚，烟浦空悲黃菊花。"]', '["鞏樹翻紅秋日斜，水分伊洛照餘霞。","弓开後騎低初月，鶚駐前旌拂暮鴉。","閨信坐遲青玉案，弄兒闲望白羊车。","今来憶事涼风晚，烟浦空悲黄菊花。"]', '诗', 'shi', '', NULL, '憶至鞏縣河宿待家累追懷 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcc1e06e-9f0e-4966-8a18-759b2c04a4af', '宿揚州', '宿揚州', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["江橫渡闊烟波晚，潮過金陵落葉秋。","嘹唳塞鴻經楚澤，淺深紅樹見揚州。","夜橋燈火連星漢，水郭帆檣近斗牛。","今日市朝風俗變，不須開口問迷樓。"]', '["江橫渡闊烟波晚，潮過金陵落葉秋。","嘹唳塞鴻經楚澤，淺深紅樹见揚州。","夜橋灯火連星漢，水郭帆檣近斗牛。","今日市朝风俗变，不須开口问迷楼。"]', '诗', 'shi', '', NULL, '宿揚州 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75fa0a69-c167-47c0-a8bd-f985b2c4a64b', '憶被牛相留醉州中時無他賓牛公夜出真珠輩數人', '憶被牛相留醉州中时無他賓牛公夜出真珠輩數人', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["嚴城畫角三聲閉，清宴金樽一夕同。","銀燭坐隅聽子夜，寶箏筵上起春風。","酒徵舊對慙衰質，曲換新詞感上宮。","淮海一從雲雨散，杳然俱是夢魂中。"]', '["嚴城畫角三声閉，清宴金樽一夕同。","銀燭坐隅听子夜，寶箏筵上起春风。","酒徵旧对慙衰質，曲換新词感上宮。","淮海一從云雨散，杳然俱是梦魂中。"]', '诗', 'shi', '', NULL, '憶被牛相留醉州中時無他賓牛公夜出真珠輩數人 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36bd2f7b-c94b-4c0c-a268-281b12e3b75e', '早渡揚子江', '早渡揚子江', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["日衝海浪翻銀屋，江轉秋波走雪山。","青嶂迥開蹲虎戍，碧流潛伏躍龍關。","地分吳楚星辰內，水迫滄溟宇宙間。","焚却戍船無戰伐，使知風教被烏蠻。"]', '["日衝海浪翻銀屋，江轉秋波走雪山。","青嶂迥开蹲虎戍，碧流潛伏躍龙关。","地分吳楚星辰內，水迫滄溟宇宙间。","焚却戍船無戰伐，使知风教被烏蠻。"]', '诗', 'shi', '', NULL, '早渡揚子江 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2b78bd9-0bf1-447b-afea-4b7f5ad48e71', '憶過潤州', '憶過潤州', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["昔年從宦干戈地，黃綬青春一魯儒。","弓犯控弦招武旅，劒當抽匣問狂夫。","帛書投筆封魚腹，玄髮衝冠捋虎鬚。","談笑謝金何所媿，不爲偷買用兵符。"]', '["昔年從宦干戈地，黄綬青春一魯儒。","弓犯控弦招武旅，劒當抽匣问狂夫。","帛书投笔封鱼腹，玄髮衝冠捋虎鬚。","談笑謝金何所媿，不爲偷買用兵符。"]', '诗', 'shi', '', NULL, '憶過潤州 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef51a4e1-0a22-48a1-96ad-80463b0c8f08', '憶登棲霞寺峰', '憶登棲霞寺峰', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["香印烟火息，法堂鐘磬餘。","紗燈耿晨焰，釋子安禪居。","林葉脫紅影，竹烟含綺疎。","星珠錯落耀，月宇參差虛。","顧眺匪恣適，曠襟懷卷舒。","江海淼清盪，丘陵何所如。","滔滔可問津，耕者非長沮。","茅嶺感仙客，蕭園成古墟。","移步下碧峰，涉澗更躊躇。","烏噪啄秋果，翠驚銜素魚。","迴塘彩鷁來，落景標林箊。","漾漾棹翻月，蕭蕭風襲裾。","勞歌起舊思，戚歎竟難攄。","却數共遊者，凋落非里閭。"]', '["香印烟火息，法堂鐘磬餘。","紗灯耿晨焰，釋子安禪居。","林葉脫紅影，竹烟含綺疎。","星珠錯落耀，月宇參差虛。","顧眺匪恣適，曠襟懷卷舒。","江海淼清盪，丘陵何所如。","滔滔可问津，耕者非长沮。","茅嶺感仙客，蕭园成古墟。","移步下碧峰，涉澗更躊躇。","烏噪啄秋果，翠驚銜素鱼。","迴塘彩鷁来，落景標林箊。","漾漾棹翻月，蕭蕭风襲裾。","勞歌起旧思，戚歎竟难攄。","却數共游者，凋落非里閭。"]', '诗', 'shi', '', NULL, '憶登棲霞寺峰 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f9c3e1c-9ba2-4973-8893-9a551dc6451f', '憶萬歲樓望金山', '憶万歲楼望金山', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["樓高雉堞千師壘，峰拔驚波萬壑攢。","山絕地維消虎踞，水浮天險尚龍盤。","蜃噓雲拱飛江島，鼇噴仙巖隔海瀾。","長對碧波臨古渡，幾經風月與悲歡。"]', '["楼高雉堞千師壘，峰拔驚波万壑攢。","山絕地維消虎踞，水浮天險尚龙盤。","蜃噓云拱飞江島，鼇噴仙巖隔海瀾。","长对碧波臨古渡，幾經风月與悲歡。"]', '诗', 'shi', '', NULL, '憶萬歲樓望金山 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7955404-a6e6-4a5a-8947-f4ae3f518181', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["上家山，家山依舊好。","昔去松桂長，今來容鬚老。","上家山，臨古道。","高低入雲樹，蕪沒連天草。","草色綠萋萋，寒蛩徧草啼。","噪鴉啼樹遠，行雁帖雲齊。","嵒光翻落日，僧火開經室。","竹洞磬聲長，松樓鐘韻疾。","苔階泉溜鈌，石甃青莎密。","舊徑行處迷，前交坐中失。","歎息整華冠，持杯強自歡。","笑歌憐稚孺，弦竹縱吹彈。","山明溪月上，酒滿心聊放。","丱髮此淹留，垂絲匪閑曠。","青山不可上，昔事還惆悵。","況復白頭人，追懷空望望。"]', '["上家山，家山依旧好。","昔去松桂长，今来容鬚老。","上家山，臨古道。","高低入云樹，蕪沒連天草。","草色綠萋萋，寒蛩徧草啼。","噪鴉啼樹远，行雁帖云齊。","嵒光翻落日，僧火开經室。","竹洞磬声长，松楼鐘韻疾。","苔階泉溜鈌，石甃青莎密。","旧徑行处迷，前交坐中失。","歎息整华冠，持杯強自歡。","笑歌怜稚孺，弦竹縱吹彈。","山明溪月上，酒满心聊放。","丱髮此淹留，垂絲匪闲曠。","青山不可上，昔事還惆悵。","況复白头人，追懷空望望。"]', '诗', 'shi', '', NULL, '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eff8686f-2cb8-4d15-9adb-7439085544ad', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 憶東郭居', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 憶东郭居', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["昔余過稚齒，從師昧知奧。","徒懷利物心，不獲藏身寶。","曳婁一縫掖，出處勞昏早。","醒醉迷啜哺，衣裳辨顛倒。","忠誠貫白日，直己憑蒼昊。","卷舌墮讒諛，驚波息行潦。","衰禽識舊木，疲馬知歸道。","楊柳長庭柯，蘭荃覆階草。","旌旄光里舍，騎服歡妻嫂。","綠鬢絕新知，蒼鬚稀舊老。","冠緌身忝貴，齋沐心常禱。","笙磬諒諧和，庭除還灑掃。","栖遲還竹巷，物役浸江島。","倏忽變星霜，悲傷滿衷抱。"]', '["昔余過稚齒，從師昧知奧。","徒懷利物心，不獲藏身寶。","曳婁一縫掖，出处勞昏早。","醒醉迷啜哺，衣裳辨顛倒。","忠誠貫白日，直己憑蒼昊。","卷舌墮讒諛，驚波息行潦。","衰禽識旧木，疲马知归道。","楊柳长庭柯，蘭荃覆階草。","旌旄光里舍，騎服歡妻嫂。","綠鬢絕新知，蒼鬚稀旧老。","冠緌身忝貴，斋沐心常禱。","笙磬諒諧和，庭除還灑掃。","栖遲還竹巷，物役浸江島。","倏忽变星霜，悲傷满衷抱。"]', '诗', 'shi', '', NULL, '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 憶東郭居 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e951ac7e-488c-4282-a368-a58852fc9f2f', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 憶題惠山寺書堂', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 憶題惠山寺书堂', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["故山一別光陰改，秋露清風歲月多。","松下壯心年少去，池邊衰影老人過。","白雲生滅依巖岫，青桂榮枯託薜蘿。","惟有此身長是客，又驅旌斾寄煙波。"]', '["故山一別光陰改，秋露清风歲月多。","松下壯心年少去，池邊衰影老人過。","白云生滅依巖岫，青桂榮枯託薜蘿。","惟有此身长是客，又驱旌斾寄煙波。"]', '诗', 'shi', '', NULL, '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 憶題惠山寺書堂 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38869ec6-7ab2-4c91-b1b1-6772267fdf63', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 憶西湖雙鸂鶒', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 憶西湖雙鸂鶒', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["雙鸂鶒，錦毛斕斑長比翼，戲繞蓮藂迴錦臆。","照灼花叢兩相得，漁歌驚起飛南北。","繚繞追隨不迷惑，雲間上下同棲息。","不作驚禽遠相憶，東家少婦機中語。","剪斷迴文泣機杼，徒嗟孔雀銜毛羽。","一去東南別離苦，五里裴回竟何補。"]', '["雙鸂鶒，錦毛斕斑长比翼，戲繞蓮藂迴錦臆。","照灼花叢兩相得，漁歌驚起飞南北。","繚繞追隨不迷惑，云间上下同棲息。","不作驚禽远相憶，东家少婦機中語。","剪斷迴文泣機杼，徒嗟孔雀銜毛羽。","一去东南別離苦，五里裴回竟何補。"]', '诗', 'shi', '', NULL, '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 憶西湖雙鸂鶒 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1274d774-d716-4705-8497-c3cdd510a7c0', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 早梅橋', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 早梅橋', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["早梅花，滿枝發。","東風報春春未徹，紫萼迎風玉珠裂。","楊柳未黃鶯結舌，委素飄香照新月。","橋邊一樹傷離別，遊蕩行人莫攀折。","不競江南豔陽節，任落東風伴春雪。"]', '["早梅花，满枝發。","东风報春春未徹，紫萼迎风玉珠裂。","楊柳未黄鶯結舌，委素飄香照新月。","橋邊一樹傷離別，游蕩行人莫攀折。","不競江南豔陽節，任落东风伴春雪。"]', '诗', 'shi', '', NULL, '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 早梅橋 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66d08e7c-5949-4f75-a9bf-6fa8f16392c9', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 翡翠塢', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 翡翠塢', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["翡翠飛飛繞蓮塢，一啄嘉魚一鳴舞。","蓮莖觸散蓮葉欹，露滴珠光似還浦。","虞人掠水輕浮弋，翡翠驚飛飛不息。","直上層空翠影高，還向雲間雙比翼。","彈射莫及弋不得，日暮虞人空歎息。"]', '["翡翠飞飞繞蓮塢，一啄嘉鱼一鳴舞。","蓮莖觸散蓮葉欹，露滴珠光似還浦。","虞人掠水轻浮弋，翡翠驚飞飞不息。","直上層空翠影高，還向云间雙比翼。","彈射莫及弋不得，日暮虞人空歎息。"]', '诗', 'shi', '', NULL, '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 翡翠塢 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a36a0840-505a-449f-b3eb-e0060e8ae76d', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後', '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["羽毛似雪無瑕點，顧影秋池舞白雲。","閑整素儀三島近，迴飄清唳九霄聞。","好風順舉應摩日，逸翮將成莫戀羣。","凌勵坐看空碧外，更憐鳧鷺老江濆。"]', '["羽毛似雪無瑕点，顧影秋池舞白云。","闲整素儀三島近，迴飄清唳九霄闻。","好风順舉應摩日，逸翮將成莫戀羣。","凌勵坐看空碧外，更怜鳧鷺老江濆。"]', '诗', 'shi', '', NULL, '過梅里七首  家於無錫四十載今敝廬數堵猶存今列題於後 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fac21232-f8fd-4b2f-8e72-c794307ba356', '過吳門二十四韻', '過吳门二十四韻', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["煙水吳都郭，閶門架碧流。","綠楊深淺巷，青翰往來舟。","朱戶千家室，丹楹百處樓。","水光搖極浦，草色辨長洲。","憶作麻衣翠，曾爲旅棹遊。","放歌隨楚老，清宴奉諸侯。","花寺聽鶯入，春湖看雁留。","里吟傳綺唱，鄉語認歈謳。","橋轉攢虹飲，波通鬬鷁浮。","竹扉梅圃靜，水巷橘園幽。","縫堵荒麋苑，穿巖破虎丘。","舊風猶越鼓，餘俗尚吳鉤。","故館曾閑訪，遺基亦徧搜。","吹臺山木盡，香徑佛宮秋。","帳殿菰蒲掩，雲房露霧收。","苧蘿妖覆滅，荆棘鬼包羞。","風月俄黃綬，經過半白頭。","重來冠蓋客，非復別離愁。","候火分通陌，前旌駐外郵。","水風搖綵斾，堤柳引鳴騶。","問吏兒孫隔，呼名禮敬修。","顧瞻殊宿昔，語默過悲憂。","義感心空在，容衰日易偷。","還持滄海詔，從此布皇猷。"]', '["煙水吳都郭，閶门架碧流。","綠楊深淺巷，青翰往来舟。","朱戶千家室，丹楹百处楼。","水光搖極浦，草色辨长洲。","憶作麻衣翠，曾爲旅棹游。","放歌隨楚老，清宴奉諸侯。","花寺听鶯入，春湖看雁留。","里吟傳綺唱，乡語認歈謳。","橋轉攢虹饮，波通鬬鷁浮。","竹扉梅圃静，水巷橘园幽。","縫堵荒麋苑，穿巖破虎丘。","旧风猶越鼓，餘俗尚吳鉤。","故館曾闲訪，遺基亦徧搜。","吹台山木尽，香徑佛宮秋。","帳殿菰蒲掩，云房露霧收。","苧蘿妖覆滅，荆棘鬼包羞。","风月俄黄綬，經過半白头。","重来冠蓋客，非复別離愁。","候火分通陌，前旌駐外郵。","水风搖綵斾，堤柳引鳴騶。","问吏兒孫隔，呼名禮敬修。","顧瞻殊宿昔，語默過悲憂。","義感心空在，容衰日易偷。","還持滄海詔，從此布皇猷。"]', '诗', 'shi', '', NULL, '過吳門二十四韻 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58542b87-49af-459c-b37d-aec1d72a7855', '杭州天竺靈隱二寺頃歲亦布衣一遊及赴鎮會稽不敢以登臨自適竟不復到寺寺多猨猱謂之孫團彌長其類因追思爲詩二首 一', '杭州天竺靈隐二寺頃歲亦布衣一游及赴鎮會稽不敢以登臨自適竟不复到寺寺多猨猱謂之孫團彌长其類因追思爲诗二首 一', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["翠巖幽谷高低寺，十里松風碧嶂連。","開盡春花芳草澗，徧通秋水月明泉。","石文照日分霞壁，竹影侵雲拂暮煙。","時有猨猱擾鍾磬，老僧無復得安禪。"]', '["翠巖幽谷高低寺，十里松风碧嶂連。","开尽春花芳草澗，徧通秋水月明泉。","石文照日分霞壁，竹影侵云拂暮煙。","时有猨猱擾鍾磬，老僧無复得安禪。"]', '诗', 'shi', '', NULL, '杭州天竺靈隱二寺頃歲亦布衣一遊及赴鎮會稽不敢以登臨自適竟不復到寺寺多猨猱謂之孫團彌長其類因追思爲詩二首 一 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('603d8ea0-383d-43c5-98ea-1b83542a3d14', '杭州天竺靈隱二寺頃歲亦布衣一遊及赴鎮會稽不敢以登臨自適竟不復到寺寺多猨猱謂之孫團彌長其類因追思爲詩二首 二', '杭州天竺靈隐二寺頃歲亦布衣一游及赴鎮會稽不敢以登臨自適竟不复到寺寺多猨猱謂之孫團彌长其類因追思爲诗二首 二', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["人煙不隔江城近，水石雖清海氣深。","波動只觀羅剎相，靜居難識梵王心。","魚扃晝鎖龍宮寶，雁塔高摩欲界金。","近日尤聞重雕飾，世人遙禮二檀林。"]', '["人煙不隔江城近，水石雖清海氣深。","波动只观羅剎相，静居难識梵王心。","鱼扃晝鎖龙宮寶，雁塔高摩欲界金。","近日尤闻重雕飾，世人遙禮二檀林。"]', '诗', 'shi', '', NULL, '杭州天竺靈隱二寺頃歲亦布衣一遊及赴鎮會稽不敢以登臨自適竟不復到寺寺多猨猱謂之孫團彌長其類因追思爲詩二首 二 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9356725-b5ad-4a5b-9e36-8e31edb39bf6', '渡西陵十六韻', '渡西陵十六韻', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["雨送奔濤遠，風收駭浪平。","截流張斾影，分岸走鼙聲。","獸逐銜波湧，龜艨噴棹輕。","海門凝霧暗，江渚濕雲橫。","雁翼看舟子，魚鱗辨水營。","騎交遮戍合，戈簇擁沙明。","謬履千夫長，將詢百吏情。","下車占黍稷，冬雨害粢盛。","望禱依前聖，垂休翼厚生。","半江猶慘澹，全野已澄清。","愛景三辰朗，祥農萬庾盈。","浦程通曲嶼，海色媚重城。","弓日鞬櫜動，旗風虎豹爭。","及郊揮白羽，入里卷紅旌。","愷悌思陳力，端莊冀表誠。","臨人與安俗，非止奉師貞。"]', '["雨送奔濤远，风收駭浪平。","截流張斾影，分岸走鼙声。","獸逐銜波湧，龟艨噴棹轻。","海门凝霧暗，江渚濕云橫。","雁翼看舟子，鱼鱗辨水營。","騎交遮戍合，戈簇擁沙明。","謬履千夫长，將詢百吏情。","下车占黍稷，冬雨害粢盛。","望禱依前聖，垂休翼厚生。","半江猶慘澹，全野已澄清。","愛景三辰朗，祥農万庾盈。","浦程通曲嶼，海色媚重城。","弓日鞬櫜动，旗风虎豹爭。","及郊揮白羽，入里卷紅旌。","愷悌思陳力，端莊冀表誠。","臨人與安俗，非止奉師貞。"]', '诗', 'shi', '', NULL, '渡西陵十六韻 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e8bfad5-2e10-41c7-aeb4-d54624303c4a', '新樓詩二十首 新樓', '新楼诗二十首 新楼', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["戎容罷引旌旗卷，朱戶褰開雉堞高。","山聳翠微連郡閣，地臨滄海接靈鼇。","坐疑許宅驅雞犬，笑類樊妻化羽毛。","惆悵桂枝零落促，莫思方朔種仙桃。"]', '["戎容罷引旌旗卷，朱戶褰开雉堞高。","山聳翠微連郡閣，地臨滄海接靈鼇。","坐疑許宅驱雞犬，笑類樊妻化羽毛。","惆悵桂枝零落促，莫思方朔種仙桃。"]', '诗', 'shi', '', NULL, '新樓詩二十首 新樓 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8648c94f-3480-4c25-b696-87426376b250', '新樓詩二十首 海榴亭', '新楼诗二十首 海榴亭', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["海榴亭早開繁蘂，光照晴霞破碧煙。","高近紫霄疑菡萏，迥依江月半嬋娟。","懷芳不作翻風豔，別萼猶含泣露妍。","搖落舊叢雲水隔，不堪行坐數流年。"]', '["海榴亭早开繁蘂，光照晴霞破碧煙。","高近紫霄疑菡萏，迥依江月半嬋娟。","懷芳不作翻风豔，別萼猶含泣露妍。","搖落旧叢云水隔，不堪行坐數流年。"]', '诗', 'shi', '', NULL, '新樓詩二十首 海榴亭 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66ca7165-e0a8-4532-93f9-b2835385daae', '新樓詩二十首 望海亭', '新楼诗二十首 望海亭', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["烏盈兔缺天涯迥，鶴背松梢拂檻低。","湖鏡坐隅看匣滿，海濤生處辨雲齊。","夕嵐明滅江帆小，煙樹蒼茫客思迷。","蕭索感心俱是夢，九天應共草萋萋。"]', '["烏盈兔缺天涯迥，鹤背松梢拂檻低。","湖镜坐隅看匣满，海濤生处辨云齊。","夕嵐明滅江帆小，煙樹蒼茫客思迷。","蕭索感心俱是梦，九天應共草萋萋。"]', '诗', 'shi', '', NULL, '新樓詩二十首 望海亭 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19640e97-9144-4640-9a41-d5512aabb43e', '新樓詩二十首', '新楼诗二十首', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["杜鵑如火千房拆，丹檻低看晚景中。","繁豔向人啼宿露，落英飄砌怨春風。","早梅昔待佳人折，好月誰將老子同。","惟有此花隨越鳥，一聲啼處滿山紅。"]', '["杜鵑如火千房拆，丹檻低看晚景中。","繁豔向人啼宿露，落英飄砌怨春风。","早梅昔待佳人折，好月誰將老子同。","惟有此花隨越鸟，一声啼处满山紅。"]', '诗', 'shi', '', NULL, '新樓詩二十首 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('985b2d1f-3dee-4287-ad74-61ecaf3623f9', '新樓詩二十首', '新楼诗二十首', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["爲憐湖水通宵望，不學樊楊却月樓。","惟待素規澄滿鏡，莫看纖魄挂如鉤。","卷簾方影侵紅燭，繞竹斜暉透碧流。","蕭瑟曉風聞木落，此時何異洞庭秋。"]', '["爲怜湖水通宵望，不学樊楊却月楼。","惟待素規澄满镜，莫看纖魄挂如鉤。","卷簾方影侵紅燭，繞竹斜暉透碧流。","蕭瑟晓风闻木落，此时何異洞庭秋。"]', '诗', 'shi', '', NULL, '新樓詩二十首 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c0f02f-21d3-4bce-acb9-eff80ce4f0c0', '新樓詩二十首', '新楼诗二十首', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["綠波春水湖光滿，丹檻連楹碧嶂遙。","蘭鷁對飛漁棹急，彩虹翻影海旗搖。","鬬疑斑虎歸三島，散作遊龍上九霄。","鼉鼓若雷爭勝負，柳堤花岸萬人招。"]', '["綠波春水湖光满，丹檻連楹碧嶂遙。","蘭鷁对飞漁棹急，彩虹翻影海旗搖。","鬬疑斑虎归三島，散作游龙上九霄。","鼉鼓若雷爭勝負，柳堤花岸万人招。"]', '诗', 'shi', '', NULL, '新樓詩二十首 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08a50e12-2888-4249-9484-88f440012324', '新樓詩二十首', '新楼诗二十首', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["銀地溪邊遇衲師，笑將花宇指潛知。","定觀玄度生前事，不道靈山別後期。","真相有無因色界，化城興滅在蓮基。","好令滄海龍宮子，長護金人舊浴池。"]', '["銀地溪邊遇衲師，笑將花宇指潛知。","定观玄度生前事，不道靈山別後期。","真相有無因色界，化城兴滅在蓮基。","好令滄海龙宮子，长護金人旧浴池。"]', '诗', 'shi', '', NULL, '新樓詩二十首 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42518e41-9216-40b0-ab0e-4eb5f95dbaf5', '新樓詩二十首 禹廟', '新楼诗二十首 禹廟', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["削平水土窮滄海，畚鍤東南盡會稽。","山擁翠屏朝玉帛，穴通金闕架雲霓。","秘文鏤石藏青壁，寶檢封雲化紫泥。","清廟萬年長血食，始知明德與天齊。"]', '["削平水土窮滄海，畚鍤东南尽會稽。","山擁翠屏朝玉帛，穴通金闕架云霓。","秘文鏤石藏青壁，寶檢封云化紫泥。","清廟万年长血食，始知明德與天齊。"]', '诗', 'shi', '', NULL, '新樓詩二十首 禹廟 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7a7f1b1-759c-4c17-a1e8-9a3f52a2c9c3', '新樓詩二十首', '新楼诗二十首', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["寺深松桂無塵事，地接荒郊帶夕陽。","啼鳥歇時山寂寂，野花殘處月蒼蒼。","絳紗凝焰開金像，清梵銷聲閉竹房。","丘壠漸平連茂草，九原何處不心傷。"]', '["寺深松桂無塵事，地接荒郊带夕陽。","啼鸟歇时山寂寂，野花殘处月蒼蒼。","絳紗凝焰开金像，清梵銷声閉竹房。","丘壠漸平連茂草，九原何处不心傷。"]', '诗', 'shi', '', NULL, '新樓詩二十首 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b805c64b-bdc3-4b62-9ec7-5a2ae86e30e5', '新樓詩二十首', '新楼诗二十首', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["一峰凝黛當明鏡，十仞喬松倚翠屏。","秋月滿時侵兔魄，素波搖處動龜形。","舊深崖谷藏仙島，新結樓臺起佛扃。","不學大蛟憑水怪，等閑雪雨害生靈。"]', '["一峰凝黛當明镜，十仞喬松倚翠屏。","秋月满时侵兔魄，素波搖处动龟形。","旧深崖谷藏仙島，新結楼台起佛扃。","不学大蛟憑水怪，等闲雪雨害生靈。"]', '诗', 'shi', '', NULL, '新樓詩二十首 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22ea197b-05d4-426a-bc07-6d912ad5b7eb', '新樓詩二十首 重臺蓮', '新楼诗二十首 重台蓮', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["綠荷舒卷涼風曉，紅萼開縈紫菂重。","游女漢臯爭笑臉，二妃湘浦竝愁容。","自含秋露貞姿結，不競春妖冶態穠。","終恐玉京仙子識，却將歸種碧池峰。"]', '["綠荷舒卷涼风晓，紅萼开縈紫菂重。","游女漢臯爭笑臉，二妃湘浦竝愁容。","自含秋露貞姿結，不競春妖冶態穠。","終恐玉京仙子識，却將归種碧池峰。"]', '诗', 'shi', '', NULL, '新樓詩二十首 重臺蓮 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0107cd6a-da26-4720-ade8-847bf82f0f9e', '新樓詩二十首 橘園', '新楼诗二十首 橘园', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["江城霧歛輕霜早，園橘千株欲變金。","朱實摘時天路近，素英飄處海雲深。","懼同枳棘愁遷徙，每抱馨香委照臨。","憐爾結根能自保，不隨寒暑換貞心。"]', '["江城霧歛轻霜早，园橘千株欲变金。","朱實摘时天路近，素英飄处海云深。","懼同枳棘愁遷徙，每抱馨香委照臨。","怜爾結根能自保，不隨寒暑換貞心。"]', '诗', 'shi', '', NULL, '新樓詩二十首 橘園 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96a26e34-d40a-4a5c-8125-ee996b829bf8', '新樓詩二十首', '新楼诗二十首', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["最深城郭在人煙，疑借壺中到梵天。","巖樹桂花開月殿，石樓風鐸繞金仙。","地無塵染多靈草，室鑒真空有定泉。","應是法宮傳覺路，使無煩惱見青蓮。"]', '["最深城郭在人煙，疑借壺中到梵天。","巖樹桂花开月殿，石楼风鐸繞金仙。","地無塵染多靈草，室鑒真空有定泉。","應是法宮傳覺路，使無煩惱见青蓮。"]', '诗', 'shi', '', NULL, '新樓詩二十首 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73a9ca7a-8cd7-4b4f-a185-23fbc95861cc', '新樓詩二十首 北樓櫻桃花', '新楼诗二十首 北楼櫻桃花', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["開花占得春光早，雪綴雲裝萬萼輕。","凝豔拆時初照日，落英頻處乍聞鶯。","舞空柔弱看無力，帶月蔥蘢似有情。","多事東風入閨闥，盡飄芳思委江城。"]', '["开花占得春光早，雪綴云裝万萼轻。","凝豔拆时初照日，落英頻处乍闻鶯。","舞空柔弱看無力，带月蔥蘢似有情。","多事东风入閨闥，尽飄芳思委江城。"]', '诗', 'shi', '', NULL, '新樓詩二十首 北樓櫻桃花 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ede1c15-bea9-4cd9-9090-174491168726', '新樓詩二十首 城上薔薇', '新楼诗二十首 城上薔薇', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["薔薇繁豔滿城陰，爛熳開紅次第深。","新蘂度香翻宿蝶，密房飄影戲晨禽。","竇閨織婦慙詩句，南國佳人怨錦衾。","風月寂寥思往事，暮春空賦白頭吟。"]', '["薔薇繁豔满城陰，爛熳开紅次第深。","新蘂度香翻宿蝶，密房飄影戲晨禽。","竇閨织婦慙诗句，南国佳人怨錦衾。","风月寂寥思往事，暮春空賦白头吟。"]', '诗', 'shi', '', NULL, '新樓詩二十首 城上薔薇 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6effb5c-393e-4402-ae6d-036f290bcafd', '新樓詩二十首 南庭竹', '新楼诗二十首 南庭竹', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["東南舊美凌霜操，五月凝陰入坐寒。","煙惹翠梢含玉露，粉開春籜聳琅玕。","莫令戲馬童兒見，試引爲龍道士看。","知爾結根香實在，鳳皇終擬下雲端。"]', '["东南旧美凌霜操，五月凝陰入坐寒。","煙惹翠梢含玉露，粉开春籜聳琅玕。","莫令戲马童兒见，試引爲龙道士看。","知爾結根香實在，鳳皇終擬下云端。"]', '诗', 'shi', '', NULL, '新樓詩二十首 南庭竹 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17ca506f-2af7-4238-a1cf-cf53c4615633', '新樓詩二十首', '新楼诗二十首', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["石橋峰上栖玄鶴，碧闕巖邊蔭羽人。","冰葉萬條垂碧實，玉珠千日保青春。","月中泣露應同浥，澗底侵雲尚有塵。","徒使茯苓成琥珀，不爲松老化龍鱗。"]', '["石橋峰上栖玄鹤，碧闕巖邊蔭羽人。","冰葉万條垂碧實，玉珠千日保青春。","月中泣露應同浥，澗底侵云尚有塵。","徒使茯苓成琥珀，不爲松老化龙鱗。"]', '诗', 'shi', '', NULL, '新樓詩二十首 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09da42aa-01f7-4b8e-aa4f-7c243e4f1308', '新樓詩二十首 海棠', '新楼诗二十首 海棠', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["海邊佳樹生奇彩，知是仙山取得栽。","瓊蘂籍中聞閬苑，紫芝圖上見蓬萊。","淺深芳萼通宵換，委積紅英報曉開。","寄語春園百花道，莫爭顏色泛金杯。"]', '["海邊佳樹生奇彩，知是仙山取得栽。","瓊蘂籍中闻閬苑，紫芝圖上见蓬萊。","淺深芳萼通宵換，委積紅英報晓开。","寄語春园百花道，莫爭顏色泛金杯。"]', '诗', 'shi', '', NULL, '新樓詩二十首 海棠 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3875128a-b5d2-4d34-810b-d54f54f8fb56', '新樓詩二十首 水寺', '新楼诗二十首 水寺', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["煙波野寺經過處，水國蒼茫夢想中。","雲散浦間江月迥，日曛洲渚海潮通。","坐看魚鳥沈浮遠，靜見樓臺上下同。","聞道化城方便喻，只應從此到龍宮。"]', '["煙波野寺經過处，水国蒼茫梦想中。","云散浦间江月迥，日曛洲渚海潮通。","坐看鱼鸟沈浮远，静见楼台上下同。","闻道化城方便喻，只應從此到龙宮。"]', '诗', 'shi', '', NULL, '新樓詩二十首 水寺 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d56bb87e-68b3-4d69-b06c-c315bd94f4ad', '新樓詩二十首 靈汜橋', '新楼诗二十首 靈汜橋', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["靈汜橋邊多感傷，分明湖派繞迴塘。","岸花前後聞幽鳥，湖月高低怨綠楊。","能促歲陰惟白髮，巧乘風馬是春光。","何須化鶴歸華表，却數凋零念越鄉。"]', '["靈汜橋邊多感傷，分明湖派繞迴塘。","岸花前後闻幽鸟，湖月高低怨綠楊。","能促歲陰惟白髮，巧乘风马是春光。","何須化鹤归华表，却數凋零念越乡。"]', '诗', 'shi', '', NULL, '新樓詩二十首 靈汜橋 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a933cc1-29fc-4b59-a8fb-9abdfb8ffa63', '若耶溪', '若耶溪', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["嵐光花影繞山陰，山轉花稀到碧潯。","傾國美人妖豔遠，鑿山良冶鑄鑪深。","凌波莫惜臨妝面，瑩鍔當期出匣心。","應是蛟龍長不去，若耶秋水尚沈沈。"]', '["嵐光花影繞山陰，山轉花稀到碧潯。","傾国美人妖豔远，鑿山良冶鑄鑪深。","凌波莫惜臨妝面，瑩鍔當期出匣心。","應是蛟龙长不去，若耶秋水尚沈沈。"]', '诗', 'shi', '', NULL, '若耶溪 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d2efb8-09fe-46c3-a1c6-3af66782500a', '登禹廟迴降雪五言二十韻', '登禹廟迴降雪五言二十韻', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["金奏雲壇畢，同雲拂雪來。","玉田千畝合，瓊室萬家開。","湖暗冰封鏡，山明樹變梅。","裂繒分井陌，連璧混樓臺。","麻引詩人興，鹽牽謝女才。","細疑歌響盡，旋作舞腰迴。","著水鵝毛失，鋪松鶴羽摧。","半崖雲掩映，當砌月裴回。","遇物纖能狀，隨方巧若裁。","玉花全綴萼，珠蚌盡呈胎。","志士書頻照，鮫人杼正催。","妬妝凌粉匣，欺酒上瓊杯。","海使迷奔轍，江濤認暗雷。","疾飄風作馭，輕集霰爲媒。","劒客休矜利，農師正念摧。","瑞彰知有感，靈貺表無災。","堯歷占新慶，虞階想舊陪。","粉凝鸞閣下，銀結鳳池隈。","雞樹花驚笑，龍池絮欲猜。","勞歌會稽守，遙祝永康哉。"]', '["金奏云壇畢，同云拂雪来。","玉田千畝合，瓊室万家开。","湖暗冰封镜，山明樹变梅。","裂繒分井陌，連璧混楼台。","麻引诗人兴，鹽牽謝女才。","細疑歌响尽，旋作舞腰迴。","著水鵝毛失，鋪松鹤羽摧。","半崖云掩映，當砌月裴回。","遇物纖能狀，隨方巧若裁。","玉花全綴萼，珠蚌尽呈胎。","志士书頻照，鮫人杼正催。","妬妝凌粉匣，欺酒上瓊杯。","海使迷奔轍，江濤認暗雷。","疾飄风作馭，轻集霰爲媒。","劒客休矜利，農師正念摧。","瑞彰知有感，靈貺表無災。","堯歷占新慶，虞階想旧陪。","粉凝鸾閣下，銀結鳳池隈。","雞樹花驚笑，龙池絮欲猜。","勞歌會稽守，遙祝永康哉。"]', '诗', 'shi', '', NULL, '登禹廟迴降雪五言二十韻 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bff9437-ec13-4070-b3d9-a25ffc0713cb', '題法華寺五言二十韻', '題法华寺五言二十韻', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["花界無生地，慈宮有相天。","化娥騰寶像，留影閟金仙。","殿湧全身塔，池開半月泉。","十峰排碧落，雙澗合清漣。","藥草經行徧，香燈次第燃。","戒珠高臘護，心印祖僧傳。","瓶識先羅漢，衣存舊福田。","幻身觀火宅，昏眼照青蓮。","住覺超真境，依遊渡法船。","化城珠百億，靈跡冠三千。","蕭壁將沈影，梁薪尚綴煙。","色塵知有數，劫燼豈無年。","龍噴疑通海，鯨吞想漏川。","磬疎聞啓梵，鐘息見安禪。","指喻三車覺，開迷五陰纏。","教通方便入，心達是非詮。","見葉千花藏，檀林萬寶篇。","坐嚴獅子迅，幢飾網珠懸。","極樂知無礙，分明應有緣。","還將意功德，留偈法王前。"]', '["花界無生地，慈宮有相天。","化娥腾寶像，留影閟金仙。","殿湧全身塔，池开半月泉。","十峰排碧落，雙澗合清漣。","藥草經行徧，香灯次第燃。","戒珠高臘護，心印祖僧傳。","瓶識先羅漢，衣存旧福田。","幻身观火宅，昏眼照青蓮。","住覺超真境，依游渡法船。","化城珠百億，靈跡冠三千。","蕭壁將沈影，梁薪尚綴煙。","色塵知有數，劫燼豈無年。","龙噴疑通海，鯨吞想漏川。","磬疎闻啓梵，鐘息见安禪。","指喻三车覺，开迷五陰纏。","教通方便入，心達是非詮。","见葉千花藏，檀林万寶篇。","坐嚴獅子迅，幢飾網珠懸。","極乐知無礙，分明應有緣。","還將意功德，留偈法王前。"]', '诗', 'shi', '', NULL, '題法華寺五言二十韻 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228ff657-9b19-429a-882f-0981abf7e2a2', '宿越州天王寺', '宿越州天王寺', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["海隅布政慙期月，江上霑巾媿萬人。","休按簿書懲黠吏，未齊風俗昧良臣。","壺冰自潔中無玷，鏡水非求下見鱗。","清夜佛宮觀色相，却歸前老更前身。"]', '["海隅布政慙期月，江上霑巾媿万人。","休按簿书懲黠吏，未齊风俗昧良臣。","壺冰自潔中無玷，镜水非求下见鱗。","清夜佛宮观色相，却归前老更前身。"]', '诗', 'shi', '', NULL, '宿越州天王寺 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5052c292-7fcd-4d89-90f8-f585cba128be', '却渡西陵別越中父老', '却渡西陵別越中父老', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["海潮晚上江風急，津吏篙師語默齊。","傾手奉觴看故老，擁流爭拜見孩提。","慙非杜母臨襄峴，自鄙朱翁別會稽。","漸舉雲帆煙水闊，杳然鳧雁各東西。"]', '["海潮晚上江风急，津吏篙師語默齊。","傾手奉觴看故老，擁流爭拜见孩提。","慙非杜母臨襄峴，自鄙朱翁別會稽。","漸舉云帆煙水闊，杳然鳧雁各东西。"]', '诗', 'shi', '', NULL, '却渡西陵別越中父老 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d5b8782-3afa-4a8b-8f97-acea92118d4e', '却到浙西', '却到浙西', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["臨平水竭蒹葭死，里社蕭條旅館秋。","嘗歎晉郊無乞糴，豈忘吳俗共分憂。","野悲揚目稱嗟食，林極翳桑顧所求。","苛政尚存猶惕息，老人偷拜擁前舟。"]', '["臨平水竭蒹葭死，里社蕭條旅館秋。","嘗歎晉郊無乞糴，豈忘吳俗共分憂。","野悲揚目稱嗟食，林極翳桑顧所求。","苛政尚存猶惕息，老人偷拜擁前舟。"]', '诗', 'shi', '', NULL, '却到浙西 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9cb86e5-750a-41e7-a62e-86d40fb8b2f1', '蘇州不住遙望武丘報恩兩寺', '蘇州不住遙望武丘報恩兩寺', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["秋山古寺東西遠，竹院松門悵望同。","幽鳥靜時侵徑月，野煙消處滿林風。","塔分朱雁餘霞外，剎對金螭落照中。","官備散寮身却累，往來慙謝二蓮宮。"]', '["秋山古寺东西远，竹院松门悵望同。","幽鸟静时侵徑月，野煙消处满林风。","塔分朱雁餘霞外，剎对金螭落照中。","官備散寮身却累，往来慙謝二蓮宮。"]', '诗', 'shi', '', NULL, '蘇州不住遙望武丘報恩兩寺 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b21568f0-66be-42c4-a0eb-208d9b1d4c0a', '迴望館娃故宮', '迴望館娃故宮', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["江雲斷續草綿連，雲隔秋波樹覆煙。","飄雪荻花鋪漲渚，變霜楓葉卷平田。","雀愁化水喧斜日，鴻怨驚風叫暮天。","因問館娃何所恨，破吳紅臉尚開蓮。"]', '["江云斷續草綿連，云隔秋波樹覆煙。","飄雪荻花鋪漲渚，变霜楓葉卷平田。","雀愁化水喧斜日，鴻怨驚风叫暮天。","因问館娃何所恨，破吳紅臉尚开蓮。"]', '诗', 'shi', '', NULL, '迴望館娃故宮 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30b4bd17-f4f2-48c0-a9ab-0e3cc0666a82', '姑蘇臺雜句', '姑蘇台杂句', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["越王巧破夫差國，來獻黃金重雕刻。","西施醉舞花豔傾，妬月嬌娥恣妖惑。","姑蘇百尺曉鋪開，樓楣盡化黃金臺。","歌清管咽歡未極，越師戈甲浮江來。","伍胥抉目看吳滅，范蠡全身霸西越。","寂莫千年盡古墟，蕭條兩地皆明月。","靈巖香徑掩禪扉，秋草荒涼徧落暉。","江浦迴看鷗鳥沒，碧峰斜見鷺鷥飛。","如今白髮星星滿，却作閑官不閑散。","野寺經過懼悔尤，公程迫蹙悲秋館。","吳鄉越國舊淹留，草樹煙霞昔徧遊。","雲木夢迴多感歡，不惟惆悵至長洲。"]', '["越王巧破夫差国，来獻黄金重雕刻。","西施醉舞花豔傾，妬月嬌娥恣妖惑。","姑蘇百尺晓鋪开，楼楣尽化黄金台。","歌清管咽歡未極，越師戈甲浮江来。","伍胥抉目看吳滅，范蠡全身霸西越。","寂莫千年尽古墟，蕭條兩地皆明月。","靈巖香徑掩禪扉，秋草荒涼徧落暉。","江浦迴看鷗鸟沒，碧峰斜见鷺鷥飞。","如今白髮星星满，却作闲官不闲散。","野寺經過懼悔尤，公程迫蹙悲秋館。","吳乡越国旧淹留，草樹煙霞昔徧游。","云木梦迴多感歡，不惟惆悵至长洲。"]', '诗', 'shi', '', NULL, '姑蘇臺雜句 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33915e18-8c70-4872-9db4-ae6712edff7a', '開元寺', '开元寺', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["十層花宇真毫相，數仞峰巒閟月扉。","攢立寶山中色界，散周香海小輪圍。","坐隅咫尺窺巖壑，窗外高低辨翠微。","難保爾形終不轉，莫令偷拂六銖衣。"]', '["十層花宇真毫相，數仞峰巒閟月扉。","攢立寶山中色界，散周香海小輪圍。","坐隅咫尺窺巖壑，窗外高低辨翠微。","难保爾形終不轉，莫令偷拂六銖衣。"]', '诗', 'shi', '', NULL, '開元寺 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78e1c384-29e2-46e9-aff3-0d400ba702b8', '臯橋', '臯橋', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["伯鸞憔悴甘飄寓，非向囂塵隱姓名。","鴻鵠羽毛終有志，素絲琴瑟自諧聲。","故橋秋月無家照，古井寒泉見底清。","猶有餘風未磨滅，至今鄉里重和鳴。"]', '["伯鸾憔悴甘飄寓，非向囂塵隐姓名。","鴻鵠羽毛終有志，素絲琴瑟自諧声。","故橋秋月無家照，古井寒泉见底清。","猶有餘风未磨滅，至今乡里重和鳴。"]', '诗', 'shi', '', NULL, '臯橋 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de285a0f-2635-4c67-b68c-d0289a39d2d5', '真娘墓', '真娘墓', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["一株繁豔春城盡，雙樹慈門忍草生。","愁態自隨風燭滅，愛心難逐雨花輕。","黛消波月空蟾影，歌息梁塵有梵聲。","還似錢塘蘇小小，祗應迴首是卿卿。"]', '["一株繁豔春城尽，雙樹慈门忍草生。","愁態自隨风燭滅，愛心难逐雨花轻。","黛消波月空蟾影，歌息梁塵有梵声。","還似錢塘蘇小小，祗應迴首是卿卿。"]', '诗', 'shi', '', NULL, '真娘墓 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c18ad53-743c-46c3-afd6-761dde1931cd', '却望無錫芙蓉湖 一', '却望無錫芙蓉湖 一', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["水寬山遠煙嵐迥，柳岸縈迴在碧流。","清晝不風鳧雁少，却疑初夢鏡湖秋。"]', '["水寬山远煙嵐迥，柳岸縈迴在碧流。","清晝不风鳧雁少，却疑初梦镜湖秋。"]', '诗', 'shi', '', NULL, '却望無錫芙蓉湖 一 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a08d0bfa-5446-4c35-9f86-6366ae42df4f', '却望無錫芙蓉湖 二', '却望無錫芙蓉湖 二', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["丹橘村邊獨火微，碧流明處雁初飛。","蕭條落葉垂楊岸，隔水寥寥聞擣衣。"]', '["丹橘村邊独火微，碧流明处雁初飞。","蕭條落葉垂楊岸，隔水寥寥闻擣衣。"]', '诗', 'shi', '', NULL, '却望無錫芙蓉湖 二 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26c9b6ee-4ca2-4ecb-b153-4ac1415090a1', '却望無錫芙蓉湖 三', '却望無錫芙蓉湖 三', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["逐波雲影參差遠，背日嵐光隱見深。","猶似望中連海樹，月生湖上是山陰。"]', '["逐波云影參差远，背日嵐光隐见深。","猶似望中連海樹，月生湖上是山陰。"]', '诗', 'shi', '', NULL, '却望無錫芙蓉湖 三 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b38832ba-1187-4a67-8cf1-dcf8bc6337e2', '却望無錫芙蓉湖 四', '却望無錫芙蓉湖 四', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["舊山認得煙嵐近，湖水平鋪碧岫間。","喜見雲泉還悵望，自慙山叟不歸山。"]', '["旧山認得煙嵐近，湖水平鋪碧岫间。","喜见云泉還悵望，自慙山叟不归山。"]', '诗', 'shi', '', NULL, '却望無錫芙蓉湖 四 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b924d86f-d84d-4c54-bec9-25877fc9eafa', '却望無錫芙蓉湖 五', '却望無錫芙蓉湖 五', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["翠崖幽谷分明處，倦鳥歸雲在眼前。","惆悵白頭爲四老，遠隨塵土去伊川。"]', '["翠崖幽谷分明处，倦鸟归云在眼前。","惆悵白头爲四老，远隨塵土去伊川。"]', '诗', 'shi', '', NULL, '却望無錫芙蓉湖 五 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a34c470-da71-4a2a-97a9-b998c42bce3d', '重到惠山', '重到惠山', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["碧峰依舊松筠老，重得經過已白頭。","俱是海天黃葉信，兩逢霜節菊花秋。","望中白鶴憐歸翼，行處青苔恨昔遊。","還向窗間名姓下，數行添記別離愁。"]', '["碧峰依旧松筠老，重得經過已白头。","俱是海天黄葉信，兩逢霜節菊花秋。","望中白鹤怜归翼，行处青苔恨昔游。","還向窗间名姓下，數行添記別離愁。"]', '诗', 'shi', '', NULL, '重到惠山 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe5d682f-3b84-420e-8efc-822711c9188d', '鑒玄影堂', '鑒玄影堂', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["香燈寂莫網塵中，煩惱身須色界空。","龍鉢已傾無法雨，虎牀猶在有悲風。","定心池上浮泡沒，招手巖邊夢幻通。","深夜月明松子落，儼然聽法侍生公。"]', '["香灯寂莫網塵中，煩惱身須色界空。","龙鉢已傾無法雨，虎牀猶在有悲风。","定心池上浮泡沒，招手巖邊梦幻通。","深夜月明松子落，儼然听法侍生公。"]', '诗', 'shi', '', NULL, '鑒玄影堂 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e3d60b9-9a69-4da7-91c3-0e9664914292', '別石泉', '別石泉', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["素沙見底空無色，青石潛流暗有聲。","微渡竹風涵淅瀝，細浮松月透輕明。","桂凝秋露添靈液，茗折香芽泛玉英。","應是梵宮連洞府，浴池今化醒泉清。"]', '["素沙见底空無色，青石潛流暗有声。","微渡竹风涵淅瀝，細浮松月透轻明。","桂凝秋露添靈液，茗折香芽泛玉英。","應是梵宮連洞府，浴池今化醒泉清。"]', '诗', 'shi', '', NULL, '別石泉 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3d09c65-b21d-4b38-bb61-7a5a13a75bab', '別雙溫樹', '別雙溫樹', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["翠條盈尺憐孤秀，植向西窗待月軒。","輕剪綠絲秋葉暗，密扶纖幹夏陰繁。","故山手種空懷想，溫室心知不敢言。","看爾拂雲今得地，莫隨陵谷改深根。"]', '["翠條盈尺怜孤秀，植向西窗待月軒。","轻剪綠絲秋葉暗，密扶纖幹夏陰繁。","故山手種空懷想，溫室心知不敢言。","看爾拂云今得地，莫隨陵谷改深根。"]', '诗', 'shi', '', NULL, '別雙溫樹 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a5f693e-7c8d-4c20-a1c3-bfec8a474e6f', '重別西湖', '重別西湖', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["浦邊梅葉看凋落，波上雙禽去寂寥。","吹管曲傳花易失，織文機學羽難飄。","雪欺春早摧芳蕚，隼勵秋深拂翠翹。","繁豔彩毛無處所，盡成愁歎別谿橋。"]', '["浦邊梅葉看凋落，波上雙禽去寂寥。","吹管曲傳花易失，织文機学羽难飄。","雪欺春早摧芳蕚，隼勵秋深拂翠翹。","繁豔彩毛無处所，尽成愁歎別谿橋。"]', '诗', 'shi', '', NULL, '重別西湖 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d0ce467-1ee7-4612-979a-8c10c174357d', '毘陵東山', '毘陵东山', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["昔人別館淹留處，卜築東山學謝家。","業桂半空摧枳棘，曲池平盡隔煙霞。","重開漁浦連天月，更種春園滿地花。","依舊秋風還寂莫，數行衰柳宿啼鴉。"]', '["昔人別館淹留处，卜築东山学謝家。","業桂半空摧枳棘，曲池平尽隔煙霞。","重开漁浦連天月，更種春园满地花。","依旧秋风還寂莫，數行衰柳宿啼鴉。"]', '诗', 'shi', '', NULL, '毘陵東山 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4434de0f-4328-4810-b3d7-5a812772183b', '建元寺', '建元寺', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["江城物候傷心地，遠寺經過禁火辰。","芳草壠邊迴首客，野花叢裏斷腸人。","紫荆繁豔空門晝，紅藥深開古殿春。","歎息光陰催白髮，莫悲風月獨霑巾。"]', '["江城物候傷心地，远寺經過禁火辰。","芳草壠邊迴首客，野花叢裏斷腸人。","紫荆繁豔空门晝，紅藥深开古殿春。","歎息光陰催白髮，莫悲风月独霑巾。"]', '诗', 'shi', '', NULL, '建元寺 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4cb6229-d6b1-483f-a860-15b5d4fc7208', '却到金陵登北固亭', '却到金陵登北固亭', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["龍形江影隔雲深，虎勢山光入浪沈。","潮蹙海風驅萬里，日浮天塹洞千尋。","衆峰作限橫空碧，一柱中維徹底金。","還叱檝師看五兩，莫令辜負濟川心。"]', '["龙形江影隔云深，虎勢山光入浪沈。","潮蹙海风驱万里，日浮天塹洞千尋。","衆峰作限橫空碧，一柱中維徹底金。","還叱檝師看五兩，莫令辜負濟川心。"]', '诗', 'shi', '', NULL, '却到金陵登北固亭 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2041eb8c-12af-4d50-a54a-43cc1414f9eb', '望鶴林寺', '望鹤林寺', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["鶴栖峰下青蓮宇，花發江城世界春。","紅照日高殷奪火，紫凝霞曙瑩銷塵。","每思載酒悲前事，欲問題詩想舊身。","自歎秋風勞物役，白頭拘束一閑人。"]', '["鹤栖峰下青蓮宇，花發江城世界春。","紅照日高殷奪火，紫凝霞曙瑩銷塵。","每思載酒悲前事，欲问題诗想旧身。","自歎秋风勞物役，白头拘束一闲人。"]', '诗', 'shi', '', NULL, '望鶴林寺 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc48d76d-a666-4b6b-9d4e-b54ce368198f', '宿瓜州', '宿瓜州', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["煙昏水郭津亭晚，迴望金陵若動搖。","衝浦迴風翻宿浪，照沙低月歛殘潮。","柳經寒露看蕭索，人改衰容自寂寥。","官冷舊諳唯旅館，歲陰輕薄是涼飆。"]', '["煙昏水郭津亭晚，迴望金陵若动搖。","衝浦迴风翻宿浪，照沙低月歛殘潮。","柳經寒露看蕭索，人改衰容自寂寥。","官冷旧諳唯旅館，歲陰轻薄是涼飆。"]', '诗', 'shi', '', NULL, '宿瓜州 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a03213a-3dfc-41fb-a4d7-7aad9c72a9e5', '入揚州郭', '入揚州郭', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["菊芳沙渚殘花少，柳過秋風墜葉疎。","堤繞門津喧井市，路交村陌混樵漁。","畏衝生客呼童僕，欲指潮痕問里閭。","非爲掩身羞白髮，自緣多病喜肩輿。"]', '["菊芳沙渚殘花少，柳過秋风墜葉疎。","堤繞门津喧井市，路交村陌混樵漁。","畏衝生客呼童僕，欲指潮痕问里閭。","非爲掩身羞白髮，自緣多病喜肩輿。"]', '诗', 'shi', '', NULL, '入揚州郭 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e23faa15-b7c4-4801-9010-de99c8fe405e', '宿揚州水館', '宿揚州水館', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["舟依淺岸參差合，橋映晴虹上下連。","輕檝過時搖水月，遠燈繁處隔秋煙。","却思海嶠還悽歎，近涉江濤更凜然。","閑凭欄干指星漢，尚疑軒蓋在樓船。"]', '["舟依淺岸參差合，橋映晴虹上下連。","轻檝過时搖水月，远灯繁处隔秋煙。","却思海嶠還悽歎，近涉江濤更凜然。","闲凭欄干指星漢，尚疑軒蓋在楼船。"]', '诗', 'shi', '', NULL, '宿揚州水館 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8cc2268-11e7-4f3d-83d5-098d9b4fd17e', '州中小飲便別牛相', '州中小饮便別牛相', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["笙歌罷曲辭賓侶，庭竹移陰就小齋。","愁不解顏徒滿酌，病非傷肺爲憂懷。","耻矜學步貽身患，豈慕醒狂躡禍階。","從此別離長酩酊，洛陽狂狷任椎埋。"]', '["笙歌罷曲辞賓侶，庭竹移陰就小斋。","愁不解顏徒满酌，病非傷肺爲憂懷。","耻矜学步貽身患，豈慕醒狂躡禍階。","從此別離长酩酊，洛陽狂狷任椎埋。"]', '诗', 'shi', '', NULL, '州中小飲便別牛相 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c504af7-9377-4540-a883-a6b2a39b22b2', '却過淮陰吊韓信廟', '却過淮陰吊韓信廟', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["功高自棄漢元臣，遺廟陰森楚水濱。","英主任賢增虎翼，假王徼福犯龍鱗。","賤能忍恥卑狂少，貴乏懷忠近佞人。","徒用千金酬一飯，不知明哲重防身。"]', '["功高自棄漢元臣，遺廟陰森楚水濱。","英主任賢增虎翼，假王徼福犯龙鱗。","賤能忍恥卑狂少，貴乏懷忠近佞人。","徒用千金酬一飯，不知明哲重防身。"]', '诗', 'shi', '', NULL, '却過淮陰吊韓信廟 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b92fefdd-ddbc-478b-8d8d-8724abe2176d', '却入泗口', '却入泗口', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["洪河一派清淮接，堤草蘆花萬里秋。","煙樹寂寥分楚澤，海雲明滅滿揚州。","望深江漢連天遠，思起鄉閭滿眼愁。","惆悵路岐真此處，夕陽西沒水東流。"]', '["洪河一派清淮接，堤草蘆花万里秋。","煙樹寂寥分楚澤，海云明滅满揚州。","望深江漢連天远，思起乡閭满眼愁。","惆悵路岐真此处，夕陽西沒水东流。"]', '诗', 'shi', '', NULL, '却入泗口 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bea3434-7a5a-4321-bc84-d20b29627ff6', '重入洛陽東門', '重入洛陽东门', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["商顏重命伊川叟，時事知非入洛人。","連野碧流通御苑，滿階秋草過天津。","每慚清秩容衰齒，猶有華簪寄病身。","驅馬獨歸尋里巷，日斜行處舊紅塵。"]', '["商顏重命伊川叟，时事知非入洛人。","連野碧流通御苑，满階秋草過天津。","每慚清秩容衰齒，猶有华簪寄病身。","驱马独归尋里巷，日斜行处旧紅塵。"]', '诗', 'shi', '', NULL, '重入洛陽東門 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5fc2dea-7599-42e4-a849-15a6aac340b6', '拜三川守', '拜三川守', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["恭承寵詔臨伊洛，靜守朝章化比閭。","風變市兒驚偃草，雨晴郊藪謬隨車。","改張琴瑟移膠柱，止息笙篁辨魯魚。","唯有從容期一德，使齊文教奉皇居。"]', '["恭承寵詔臨伊洛，静守朝章化比閭。","风变市兒驚偃草，雨晴郊藪謬隨车。","改張琴瑟移膠柱，止息笙篁辨魯鱼。","唯有從容期一德，使齊文教奉皇居。"]', '诗', 'shi', '', NULL, '拜三川守 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d30fdec9-9662-4837-8d6f-c781bf7355ae', '慶雲見', '慶云见', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["禮成中嶽陳金冊，祥報卿雲冠玉峰。","輕未透林疑待鳳，細非行雨詎從龍。","卷風變彩霏微薄，照日籠光映隱重。","還入九霄成沆瀣，夕嵐生處鶴歸松。"]', '["禮成中嶽陳金冊，祥報卿云冠玉峰。","轻未透林疑待鳳，細非行雨詎從龙。","卷风变彩霏微薄，照日籠光映隐重。","還入九霄成沆瀣，夕嵐生处鹤归松。"]', '诗', 'shi', '', NULL, '慶雲見 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6c2566b-4fa4-4f97-846f-32b01e2b47ad', '靈蛇見少林寺', '靈蛇见少林寺', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["瑣文結綬靈蛇降，蠖屈螭盤顧視閑。","鱗蹙翠光抽璀璨，腹連金彩動彎環。","已應蛻骨風雷後，豈効銜珠草莽間。","知爾全身護崑閬，不矜揮尾在常山。"]', '["瑣文結綬靈蛇降，蠖屈螭盤顧視闲。","鱗蹙翠光抽璀璨，腹連金彩动彎环。","已應蛻骨风雷後，豈効銜珠草莽间。","知爾全身護崑閬，不矜揮尾在常山。"]', '诗', 'shi', '', NULL, '靈蛇見少林寺 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19415dc-5337-4280-897b-67965cc47d1b', '拜宣武軍節度使', '拜宣武軍節度使', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["油幢竝入虎旗開，錦橐從天鳳詔來。","星應魏師新鼓角，地嫌梁苑舊池臺。","日暉紅斾分如電，人擁青門動若雷。","伊洛鏡清迴首處，是非紛雜任塵埃。"]', '["油幢竝入虎旗开，錦橐從天鳳詔来。","星應魏師新鼓角，地嫌梁苑旧池台。","日暉紅斾分如電，人擁青门动若雷。","伊洛镜清迴首处，是非紛杂任塵埃。"]', '诗', 'shi', '', NULL, '拜宣武軍節度使 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('438cac15-96b9-4ced-9867-4045458cc672', '到宣武三十韻', '到宣武三十韻', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["七月趨梁苑，三年謝尹京。","舊風除物蠹，新律奉師貞。","龍節雙油重，蛇矛百練明。","躍魚連後斾，騰虎耀前旌。","路轉金神竝，川開鐵馬橫。","擁旄差白羽，分轡引紅纓。","在浚風煙接，維嵩鞏洛清。","貫魚奔騎疾，連雁卷行輕。","煙壘風調角，秋原雨洗兵。","宿雲看布甲，疎柳見分營。","鼓徹通宵警，和門候曉晴。","虎符三校列，魚胄萬夫迎。","弄馬猨猱健，奔車角觝呈。","駕肩傍隘道，張幕內連楹。","森戟承三令，攢戈退一聲。","及郊知雨過，觀俗辨風行。","望宋憐思女，遊梁念客卿。","義夫留感激，公子播英名。","澤廣豚魚洽，恩宣豈弟生。","善師忘任智，中略在推誠。","式宴歌鍾合，陳筵綺繡并。","戲鼙千卒躍，均酒百壺傾。","樂與師徒共，歡從井邑盈。","教通因漸染，人悅尚和平。","授鉞慙分閫，登壇荷列城。","虛裘朝獨坐，雄劒夜孤鳴。","白髮侵霜變，丹心捧日驚。","衛青終保志，潘岳未忘情。","期月終迷化，三年詎有成。","惟看波海動，天外斬長鯨。"]', '["七月趨梁苑，三年謝尹京。","旧风除物蠹，新律奉師貞。","龙節雙油重，蛇矛百練明。","躍鱼連後斾，腾虎耀前旌。","路轉金神竝，川开鐵马橫。","擁旄差白羽，分轡引紅纓。","在浚风煙接，維嵩鞏洛清。","貫鱼奔騎疾，連雁卷行轻。","煙壘风調角，秋原雨洗兵。","宿云看布甲，疎柳见分營。","鼓徹通宵警，和门候晓晴。","虎符三校列，鱼胄万夫迎。","弄马猨猱健，奔车角觝呈。","駕肩傍隘道，張幕內連楹。","森戟承三令，攢戈退一声。","及郊知雨過，观俗辨风行。","望宋怜思女，游梁念客卿。","義夫留感激，公子播英名。","澤廣豚鱼洽，恩宣豈弟生。","善師忘任智，中略在推誠。","式宴歌鍾合，陳筵綺繡并。","戲鼙千卒躍，均酒百壺傾。","乐與師徒共，歡從井邑盈。","教通因漸染，人悅尚和平。","授鉞慙分閫，登壇荷列城。","虛裘朝独坐，雄劒夜孤鳴。","白髮侵霜变，丹心捧日驚。","衛青終保志，潘岳未忘情。","期月終迷化，三年詎有成。","惟看波海动，天外斬长鯨。"]', '诗', 'shi', '', NULL, '到宣武三十韻 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e5096a8-29bd-44a3-876c-07b00e132153', '江南暮春寄家', '江南暮春寄家', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["雒陽城見梅迎雪，魚口橋逢雪送梅。","劒水寺前芳草合，鏡湖亭上野花開。","江鴻斷續翻雲去，海燕差池拂水回。","想得心知近寒食，潛聽喜鵲望歸來。"]', '["雒陽城见梅迎雪，鱼口橋逢雪送梅。","劒水寺前芳草合，镜湖亭上野花开。","江鴻斷續翻云去，海燕差池拂水回。","想得心知近寒食，潛听喜鵲望归来。"]', '诗', 'shi', '', NULL, '江南暮春寄家 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22099372-939e-4154-a175-15d5365ac21c', '奉酬樂天立秋夕有懷見寄', '奉酬乐天立秋夕有懷见寄', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["深夜星漢靜，秋風初報涼。","階篁淅瀝響，露葉參差光。","冰兔半升魄，銅壺微滴長。","薄帷乍飄卷，襟帶輕搖颺。","此際昏夢清，斜月滿軒房。","屣履步前楹，劒戟森在行。","重城宵正分，號鼓互相望。","獨坐有所思，夫君鸞鳳章。","天津落星河，一葦安可航。","龍泉白玉首，魚服黃金裝。","報國未知効，惟鵜徒在梁。","裴回顧戎旃，顥氣生東方。","衰葉滿欄草，斑毛盈鏡霜。","羸牛未脫轅，老馬強騰驤。","吟君白雪唱，慙媿巴人腸。"]', '["深夜星漢静，秋风初報涼。","階篁淅瀝响，露葉參差光。","冰兔半升魄，銅壺微滴长。","薄帷乍飄卷，襟带轻搖颺。","此際昏梦清，斜月满軒房。","屣履步前楹，劒戟森在行。","重城宵正分，號鼓互相望。","独坐有所思，夫君鸾鳳章。","天津落星河，一葦安可航。","龙泉白玉首，鱼服黄金裝。","報国未知効，惟鵜徒在梁。","裴回顧戎旃，顥氣生东方。","衰葉满欄草，斑毛盈镜霜。","羸牛未脫轅，老马強腾驤。","吟君白雪唱，慙媿巴人腸。"]', '诗', 'shi', '', NULL, '奉酬樂天立秋夕有懷見寄 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83fe84e1-49aa-4462-836d-d2ac557040a6', '山出雲', '山出云', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["杳靄祥雲起，飄颺翠嶺新。","縈峰開石秀，吐葉間松春。","林靜翻空少，山明度嶺頻。","迴崖時掩鶴，幽澗或隨人。","姑射朝凝雪，陽臺晚伴神。","悠悠九霄上，應坐玉京賓。"]', '["杳靄祥云起，飄颺翠嶺新。","縈峰开石秀，吐葉间松春。","林静翻空少，山明度嶺頻。","迴崖时掩鹤，幽澗或隨人。","姑射朝凝雪，陽台晚伴神。","悠悠九霄上，應坐玉京賓。"]', '诗', 'shi', '', NULL, '山出雲 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62e08f4c-db9f-4095-b37b-97aa869d46ba', '上黨奏慶雲見', '上黨奏慶云见', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["飛龍久馭宇，真氣尚興雲。","五色傳嘉瑞，千齡表聖君。","從風忽蕭索，依漢更氛氳。","影徹天初霽，光鮮日未曛。","表祥近自遠，垂化聚還分。","寧作無依者，空傳陶令文。"]', '["飞龙久馭宇，真氣尚兴云。","五色傳嘉瑞，千齡表聖君。","從风忽蕭索，依漢更氛氳。","影徹天初霽，光鲜日未曛。","表祥近自远，垂化聚還分。","寧作無依者，空傳陶令文。"]', '诗', 'shi', '', NULL, '上黨奏慶雲見 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('287473db-3aca-49b4-a915-409b50eb5f5c', '華山慶雲見', '华山慶云见', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["聖主祠名岳，高峰發慶雲。","金柯初繚繞，玉葉漸氛氳。","氣色含珠日，晴光吐翠雰。","依稀來鶴態，髣髴列仙羣。","萬樹流光影，千潭寫錦文。","蒼生欣有望，祥瑞在吾君。"]', '["聖主祠名岳，高峰發慶云。","金柯初繚繞，玉葉漸氛氳。","氣色含珠日，晴光吐翠雰。","依稀来鹤態，髣髴列仙羣。","万樹流光影，千潭寫錦文。","蒼生欣有望，祥瑞在吾君。"]', '诗', 'shi', '', NULL, '華山慶雲見 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6463c613-eef0-4943-a22c-b14715369a3b', '欲到西陵寄王行周', '欲到西陵寄王行周', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["西陵沙岸回流急，船底黏沙去岸遙。","驛吏遞呼催下纜，棹郎閑立道齊橈。","猶瞻伍相青山廟，未見雙童白鶴橋。","欲責舟人無次第，自知貪酒過春潮。"]', '["西陵沙岸回流急，船底黏沙去岸遙。","驛吏遞呼催下纜，棹郎闲立道齊橈。","猶瞻伍相青山廟，未见雙童白鹤橋。","欲責舟人無次第，自知貪酒過春潮。"]', '诗', 'shi', '', NULL, '欲到西陵寄王行周 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa117c57-cc2f-4647-a501-59a4d5b7065a', '華頂', '华頂', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["欲向仙峰煉九丹，獨瞻華頂禮仙壇。","石標琪樹凌空碧，水挂銀河映月寒。","天外鶴聲隨絳節，洞中雲氣隱琅玕。","浮生未有從師地，空誦仙經想羽翰。"]', '["欲向仙峰煉九丹，独瞻华頂禮仙壇。","石標琪樹凌空碧，水挂銀河映月寒。","天外鹤声隨絳節，洞中云氣隐琅玕。","浮生未有從師地，空誦仙經想羽翰。"]', '诗', 'shi', '', NULL, '華頂 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a2193c-1bd7-4426-b17f-d02a8a4aec1b', '鶯鶯歌', '鶯鶯歌', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["伯勞飛遲燕飛疾，垂楊綻金花笑日。","綠窗嬌女字鶯鶯，金雀婭鬟年十七。","黃姑上天阿母在，寂莫霜姿素蓮質。","門掩重關蕭寺中，芳草花時不曾出。"]', '["伯勞飞遲燕飞疾，垂楊綻金花笑日。","綠窗嬌女字鶯鶯，金雀婭鬟年十七。","黄姑上天阿母在，寂莫霜姿素蓮質。","门掩重关蕭寺中，芳草花时不曾出。"]', '诗', 'shi', '', NULL, '鶯鶯歌 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e39c3b0-03af-47d7-a98f-32f811025380', '贈毛仙翁', '贈毛仙翁', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["憶昔我祖神仙主，玄元皇帝周柱史。","曾師軒黃友堯湯，混迹和光佐周武。","周之天子無仙氣，成武康昭都瞥爾。","穆王麤識神仙事，八極輪蹄方逞志。","鶴髮韜真世不知，日月星辰幾回死。","金鼎作丹丹化碧，三萬六千神入宅。","仙兄受術幾千年，已是當時駕鴻客。","海光悠容天路長，春風玉女開宮院。","紫筆親教書姓名，玉皇詔刻青金簡。","桂窗一別三千春，秦妃鏡裏娥眉新。","忽控香虯天上去，海隅劫石霄花塵。","一從仙駕辭中土，頑日昏風老無主。","九州爭奪無時休，八駿垂頭避豺虎。","我亦玄元千世孫，眼穿望斷蒼煙根。","花麟白鳳竟冥寞，飛春走月勞神昏。","百年命促奔馬疾，愁腸盤結心摧崪。","今朝稽首拜仙兄，願贈丹砂化秋骨。"]', '["憶昔我祖神仙主，玄元皇帝周柱史。","曾師軒黄友堯湯，混迹和光佐周武。","周之天子無仙氣，成武康昭都瞥爾。","穆王麤識神仙事，八極輪蹄方逞志。","鹤髮韜真世不知，日月星辰幾回死。","金鼎作丹丹化碧，三万六千神入宅。","仙兄受術幾千年，已是當时駕鴻客。","海光悠容天路长，春风玉女开宮院。","紫笔親教书姓名，玉皇詔刻青金簡。","桂窗一別三千春，秦妃镜裏娥眉新。","忽控香虯天上去，海隅劫石霄花塵。","一從仙駕辞中土，頑日昏风老無主。","九州爭奪無时休，八駿垂头避豺虎。","我亦玄元千世孫，眼穿望斷蒼煙根。","花麟白鳳竟冥寞，飞春走月勞神昏。","百年命促奔马疾，愁腸盤結心摧崪。","今朝稽首拜仙兄，願贈丹砂化秋骨。"]', '诗', 'shi', '', NULL, '贈毛仙翁 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fbfc98e-586b-4de7-a278-c7032b8d4a74', '和晉公三首 一', '和晉公三首 一', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["鳳儀常欲附，蚊力自知微。","願假罇罍末，膺門自此依。"]', '["鳳儀常欲附，蚊力自知微。","願假罇罍末，膺门自此依。"]', '诗', 'shi', '', NULL, '和晉公三首 一 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c1bd6aa-d116-4cb6-8f6b-614f655ab4ca', '和晉公三首 二', '和晉公三首 二', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["貂蟬公獨步，鴛鷺我同羣。","插羽先飛酒，交鋒便著文。"]', '["貂蟬公独步，鴛鷺我同羣。","插羽先飞酒，交鋒便著文。"]', '诗', 'shi', '', NULL, '和晉公三首 二 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11859a0a-c499-4d49-ba00-718369a74cdc', '和晉公三首 三', '和晉公三首 三', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["窮陰初莽蒼，離思漸氛氳。","殘雪午橋岸，斜陽伊水濱。"]', '["窮陰初莽蒼，離思漸氛氳。","殘雪午橋岸，斜陽伊水濱。"]', '诗', 'shi', '', NULL, '和晉公三首 三 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04970036-9dd8-4ad6-9193-4ac9731ad381', '古風二首 一', '古风二首 一', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["春種一粒粟，秋成萬顆子。","四海無閑田，農夫猶餓死。"]', '["春種一粒粟，秋成万顆子。","四海無闲田，農夫猶餓死。"]', '诗', 'shi', '', NULL, '古風二首 一 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab5ec1e2-084a-486d-bd84-39b320bf4d88', '古風二首 二', '古风二首 二', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["鋤禾日當午，汗滴禾下土。","誰知盤中餐，粒粒皆辛苦。"]', '["鋤禾日當午，汗滴禾下土。","誰知盤中餐，粒粒皆辛苦。"]', '诗', 'shi', '', NULL, '古風二首 二 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6936ce03-b918-4092-aa4b-89f09beaff41', '柳二首 一', '柳二首 一', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["陶令門前罥接籬，亞夫營裏拂朱旗。","人事推移無舊物，年年春至綠垂絲。"]', '["陶令门前罥接籬，亞夫營裏拂朱旗。","人事推移無旧物，年年春至綠垂絲。"]', '诗', 'shi', '', NULL, '柳二首 一 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99056766-ad1b-45f2-9f00-454f16c68bdd', '柳二首 二', '柳二首 二', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["千條垂柳拂金絲，日暖牽風葉學眉。","愁見花飛狂不定，還同輕薄五陵兒。"]', '["千條垂柳拂金絲，日暖牽风葉学眉。","愁见花飞狂不定，還同轻薄五陵兒。"]', '诗', 'shi', '', NULL, '柳二首 二 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09115c75-6775-41e4-aab8-c7466c32a782', '題白樂天文集', '題白乐天文集', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["寄玉蓮花藏，緘珠貝葉扃。","院閑容客讀，講倦許僧聽。","部列雕金榜，題存刻石銘。","永添鴻寶集，莫雜小乘經。"]', '["寄玉蓮花藏，緘珠貝葉扃。","院闲容客读，講倦許僧听。","部列雕金榜，題存刻石銘。","永添鴻寶集，莫杂小乘經。"]', '诗', 'shi', '', NULL, '題白樂天文集 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e01cf688-7b65-4c35-9fd0-4c57dd137873', '答章孝標', '答章孝標', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["假金方用真金鍍，若是真金不鍍金。","十載長安得一第，何須空腹用高心。"]', '["假金方用真金鍍，若是真金不鍍金。","十載长安得一第，何須空腹用高心。"]', '诗', 'shi', '', NULL, '答章孝標 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbcb2a21-ed3f-47ab-9efa-d02004995e1e', '朱槿花', '朱槿花', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["瘴煙長暖無霜雪，槿豔繁花滿樹紅。","每歎芳菲四時厭，不知開落有春風。"]', '["瘴煙长暖無霜雪，槿豔繁花满樹紅。","每歎芳菲四时厭，不知开落有春风。"]', '诗', 'shi', '', NULL, '朱槿花 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cd11d7f-d466-4ae5-8bc6-b23c8f676f1e', '至潭州聞猿', '至潭州闻猿', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["昔陪天上三清客，今作端州萬里人。","湘浦更聞猿夜嘯，斷腸無淚可霑巾。"]', '["昔陪天上三清客，今作端州万里人。","湘浦更闻猿夜嘯，斷腸無泪可霑巾。"]', '诗', 'shi', '', NULL, '至潭州聞猿 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f46559d-6eba-44b3-b5d7-34615f5dbc69', '江亭', '江亭', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["瘴江昏霧連天合，欲作家書更斷腸。","今日病身悲狀候，豈能埋骨向炎荒。"]', '["瘴江昏霧連天合，欲作家书更斷腸。","今日病身悲狀候，豈能埋骨向炎荒。"]', '诗', 'shi', '', NULL, '江亭 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b307387-3bbf-40f9-bcd9-f1da697cd021', '紅蕉花', '紅蕉花', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["紅蕉花樣炎方識，瘴水溪邊色最深。","葉滿叢深殷似火，不唯燒眼更燒心。"]', '["紅蕉花樣炎方識，瘴水溪邊色最深。","葉满叢深殷似火，不唯燒眼更燒心。"]', '诗', 'shi', '', NULL, '紅蕉花 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40a39e66-b220-49d7-9311-3f4f25b882cd', '憶漢月', '憶漢月', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["花開花落無時節，春去春來有底憑。","燕子不藏雷不蟄，燭煙昏霧暗騰騰。"]', '["花开花落無时節，春去春来有底憑。","燕子不藏雷不蟄，燭煙昏霧暗腾腾。"]', '诗', 'shi', '', NULL, '憶漢月 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28f3b894-be4e-49b4-9e95-fb1550e10750', '端州江亭得家書二首 一', '端州江亭得家书二首 一', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["雨中鵲語喧江樹，風處蛛絲颺水潯。","開拆遠書何事喜，數行家信抵千金。"]', '["雨中鵲語喧江樹，风处蛛絲颺水潯。","开拆远书何事喜，數行家信抵千金。"]', '诗', 'shi', '', NULL, '端州江亭得家書二首 一 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad36b445-fdba-4b15-b591-d254c1242ff0', '端州江亭得家書二首 二', '端州江亭得家书二首 二', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["長安別日春風早，嶺外今來白露秋。","莫道淮南悲木葉，不聞搖落更堪愁。"]', '["长安別日春风早，嶺外今来白露秋。","莫道淮南悲木葉，不闻搖落更堪愁。"]', '诗', 'shi', '', NULL, '端州江亭得家書二首 二 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b8c629a-0626-4350-be18-3e678e49980a', '聞猨', '闻猨', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["見說三聲巴峽深，此時行者盡沾襟。","端州江口連雲處，始信哀猨傷客心。"]', '["见说三声巴峽深，此时行者尽沾襟。","端州江口連云处，始信哀猨傷客心。"]', '诗', 'shi', '', NULL, '聞猨 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('737947c3-2db1-4e37-a0e4-a47dce0f7230', '贈韋金吾', '贈韋金吾', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["自報金吾主禁兵，腰間寶劒重橫行。","接輿也是狂歌客，更就將軍乞一聲。"]', '["自報金吾主禁兵，腰间寶劒重橫行。","接輿也是狂歌客，更就將軍乞一声。"]', '诗', 'shi', '', NULL, '贈韋金吾 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb05253-765e-4e34-84e2-23b1d9e39d42', '長門怨', '长门怨', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["宮殿沈沈曉欲分，昭陽更漏不堪聞。","珊瑚枕上千行淚，不是思君是恨君。"]', '["宮殿沈沈晓欲分，昭陽更漏不堪闻。","珊瑚枕上千行泪，不是思君是恨君。"]', '诗', 'shi', '', NULL, '長門怨 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11e225c9-4a31-4afd-91b3-fb754ccac5be', '龜山寺魚池 一', '龟山寺鱼池 一', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["汲水添池活白蓮，十千鬐鬣盡生天。","凡庸不識慈悲意，自葬江魚入九泉。"]', '["汲水添池活白蓮，十千鬐鬣尽生天。","凡庸不識慈悲意，自葬江鱼入九泉。"]', '诗', 'shi', '', NULL, '龜山寺魚池 一 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a29de75-f584-4375-8b2d-683d73f4105b', '龜山寺魚池 二', '龟山寺鱼池 二', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["剃髮多緣是代耕，好聞人死惡人生。","祇園說法無高下，爾輩何勞尚世情。"]', '["剃髮多緣是代耕，好闻人死惡人生。","祇园说法無高下，爾輩何勞尚世情。"]', '诗', 'shi', '', NULL, '龜山寺魚池 二 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ca211d7-18e4-41d4-a754-c72c28e846d6', '賦月', '賦月', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["月，光輝，皎潔。","耀乾坤，靜空闊。","圓滿中秋，玩爭詩哲。","玉兔鏑難穿，桂枝人共折。","萬象照乃無私，瓊臺豈遮君謁。","抱琴對彈別鶴聲，不得知音聲不切。"]', '["月，光輝，皎潔。","耀乾坤，静空闊。","圓满中秋，玩爭诗哲。","玉兔鏑难穿，桂枝人共折。","万象照乃無私，瓊台豈遮君謁。","抱琴对彈別鹤声，不得知音声不切。"]', '诗', 'shi', '', NULL, '賦月 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a7e5945-d571-4c50-b620-634872d6d893', '句', '句', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["君詠風月夕，余當童稚年。","閑窗讀書罷，偷詠左司篇。"]', '["君詠风月夕，余當童稚年。","闲窗读书罷，偷詠左司篇。"]', '诗', 'shi', '', NULL, '句 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6b1b736-ae47-42ca-8711-99aee01de648', '和太原張相公山亭懷古', '和太原張相公山亭懷古', '52e02a17-e8f4-4e9a-b961-d84a6f30b14b', '唐', '["疊石狀崖巘，翠含城上樓。","前移廬霍峰，遠帶沅湘流。","瀟灑主人靜，夤緣芳徑幽。","清輝在昏旦，豈異東山游。"]', '["叠石狀崖巘，翠含城上楼。","前移廬霍峰，远带沅湘流。","瀟灑主人静，夤緣芳徑幽。","清輝在昏旦，豈異东山游。"]', '诗', 'shi', '', NULL, '和太原張相公山亭懷古 崔公信 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d74a82fe-4c5b-4925-9759-7f619bdb985a', '過小妓英英墓', '過小妓英英墓', '36c9049a-d43c-4ab9-bd41-785a4f05c0de', '唐', '["蕭晨騎馬出皇都，聞說埋冤在路隅。","別我已爲泉下土，思君猶似掌中珠。","四弦品柱聲初絕，三尺孤墳草已枯。","蘭質蕙心何所在，焉知過者是狂夫。"]', '["蕭晨騎马出皇都，闻说埋冤在路隅。","別我已爲泉下土，思君猶似掌中珠。","四弦品柱声初絕，三尺孤墳草已枯。","蘭質蕙心何所在，焉知過者是狂夫。"]', '诗', 'shi', '', NULL, '過小妓英英墓 楊虞卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebfb90a0-ccf4-4f10-bfe4-b8b1d253edf6', '句', '句', '36c9049a-d43c-4ab9-bd41-785a4f05c0de', '唐', '["河勢崑崙遠，山形菡萏秋。"]', '["河勢崑崙远，山形菡萏秋。"]', '诗', 'shi', '', NULL, '句 楊虞卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('743b1a3c-e602-4604-a181-317bd81e60d0', '和段相公登武擔寺西臺', '和段相公登武擔寺西台', '1ecea968-b89d-47a4-b7f9-8a0b4bf5e3af', '唐', '["清淨此道宮，層臺復倚空。","偶時三伏外，列席九霄中。","平視雲端路，高臨樹杪風。","自憐榮末座，前日別池籠。"]', '["清淨此道宮，層台复倚空。","偶时三伏外，列席九霄中。","平視云端路，高臨樹杪风。","自怜榮末座，前日別池籠。"]', '诗', 'shi', '', NULL, '和段相公登武擔寺西臺 楊汝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06ba6fc0-85d9-4e2f-9701-a69616b9c0cb', '和段相公夏登張儀樓', '和段相公夏登張儀楼', '1ecea968-b89d-47a4-b7f9-8a0b4bf5e3af', '唐', '["從公城上來，秋近絕纖埃。","樓古秦規在，江分蜀望開。","遠山標宿雪，末席本寒灰。","陪賞今爲忝，臨歡敢訴杯。"]', '["從公城上来，秋近絕纖埃。","楼古秦規在，江分蜀望开。","远山標宿雪，末席本寒灰。","陪賞今爲忝，臨歡敢訴杯。"]', '诗', 'shi', '', NULL, '和段相公夏登張儀樓 楊汝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23a7512a-6feb-4ce5-9246-8a7000dc881f', '和宗人尚書嗣復祠祭武侯畢題臨淮公舊碑', '和宗人尚书嗣复祠祭武侯畢題臨淮公旧碑', '1ecea968-b89d-47a4-b7f9-8a0b4bf5e3af', '唐', '["古栢森然地，修嚴蜀相祠。","一過榮異代，三顧盛當時。","功德流何遠，馨香薦未衰。","敬名探國志，飾像慰甿思。","昔謁從征蓋，今聞擁信旗。","固宜光寵下，有淚刻前碑。"]', '["古栢森然地，修嚴蜀相祠。","一過榮異代，三顧盛當时。","功德流何远，馨香薦未衰。","敬名探国志，飾像慰甿思。","昔謁從征蓋，今闻擁信旗。","固宜光寵下，有泪刻前碑。"]', '诗', 'shi', '', NULL, '和宗人尚書嗣復祠祭武侯畢題臨淮公舊碑 楊汝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f1e2a4c-b9fa-4837-b407-7b370ed7f086', '宴楊僕射新昌里第', '宴楊僕射新昌里第', '1ecea968-b89d-47a4-b7f9-8a0b4bf5e3af', '唐', '["隔坐應須賜御屏，盡將仙翰入高冥。","文章舊價留鸞掖，桃李新陰在鯉庭。","再歲生徒陳賀宴，一時良史盡傳馨。","當時疏廣雖云盛，詎有茲筵醉綠醽。"]', '["隔坐應須賜御屏，尽將仙翰入高冥。","文章旧價留鸾掖，桃李新陰在鯉庭。","再歲生徒陳賀宴，一时良史尽傳馨。","當时疏廣雖云盛，詎有茲筵醉綠醽。"]', '诗', 'shi', '', NULL, '宴楊僕射新昌里第 楊汝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ac1b81a-77e1-4a83-a417-795af4422cad', '建節後偶作', '建節後偶作', '1ecea968-b89d-47a4-b7f9-8a0b4bf5e3af', '唐', '["拋却弓刀上砌臺，上方臺榭與雲開。","山僧見我衣裳窄，知道新從戰地來。"]', '["拋却弓刀上砌台，上方台榭與云开。","山僧见我衣裳窄，知道新從戰地来。"]', '诗', 'shi', '', NULL, '建節後偶作 楊汝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('156ed6c6-08da-4e5d-ab37-b067b47642b1', '題畫山水', '題畫山水', '1ecea968-b89d-47a4-b7f9-8a0b4bf5e3af', '唐', '["太華峰前是故鄉，路人遙指讀書堂。","如今老大騎官馬，羞向關西道姓楊。"]', '["太华峰前是故乡，路人遙指读书堂。","如今老大騎官马，羞向关西道姓楊。"]', '诗', 'shi', '', NULL, '題畫山水 楊汝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f6f0f66-5d2e-474b-a972-ea662a6a9585', '賀筵占贈營妓', '賀筵占贈營妓', '1ecea968-b89d-47a4-b7f9-8a0b4bf5e3af', '唐', '["郎君得意及青春，蜀國將軍又不貧。","一曲高歌紅一疋，兩頭娘子謝夫人。"]', '["郎君得意及青春，蜀国將軍又不貧。","一曲高歌紅一疋，兩头娘子謝夫人。"]', '诗', 'shi', '', NULL, '賀筵占贈營妓 楊汝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9cd35e-e0d8-4311-b011-a66ed6377fe3', '句', '句', '1ecea968-b89d-47a4-b7f9-8a0b4bf5e3af', '唐', '["昔日蘭亭無豔質，此時金谷有高人。"]', '["昔日蘭亭無豔質，此时金谷有高人。"]', '诗', 'shi', '', NULL, '句 楊汝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7646514b-0003-4ef8-9fa1-d1a65d27c700', '賦得芙蓉出水', '賦得芙蓉出水', 'deb6e6e5-579e-4dc9-a535-1447e871b846', '唐', '["菡萏迎秋吐，夭搖映水濱。","劍芒開寶匣，峰影寫蒲津。","下覆差參荇，高辭苒弱蘋。","自當巢翠甲，非止戲頳鱗。","莫以時先後，而言色故新。","芳香正堪翫，誰報涉江人。"]', '["菡萏迎秋吐，夭搖映水濱。","劍芒开寶匣，峰影寫蒲津。","下覆差參荇，高辞苒弱蘋。","自當巢翠甲，非止戲頳鱗。","莫以时先後，而言色故新。","芳香正堪翫，誰報涉江人。"]', '诗', 'shi', '', NULL, '賦得芙蓉出水 陳至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a9eda2a-6490-4b38-90a1-9508fc8563db', '薦冰', '薦冰', 'deb6e6e5-579e-4dc9-a535-1447e871b846', '唐', '["凌寒開涸沍，寢廟致精誠。","色靜澄三酒，光寒肅兩楹。","形鹽非近進，玉豆爲潛英。","禮自春分展，堅從北陸成。","藉茅心共結，出鑑水漸明。","幸得來觀薦，靈臺一小生。"]', '["凌寒开涸沍，寢廟致精誠。","色静澄三酒，光寒肅兩楹。","形鹽非近進，玉豆爲潛英。","禮自春分展，堅從北陸成。","藉茅心共結，出鑑水漸明。","幸得来观薦，靈台一小生。"]', '诗', 'shi', '', NULL, '薦冰 陳至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3597fe6-86d6-494f-b3ba-159e512b8aa3', '句', '句', 'deb6e6e5-579e-4dc9-a535-1447e871b846', '唐', '["藻井尚寒龍跡在，紅樓初施日光通。"]', '["藻井尚寒龙跡在，紅楼初施日光通。"]', '诗', 'shi', '', NULL, '句 陳至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95190d25-f10e-420f-9a2a-21bf59569af7', '薦冰', '薦冰', 'd4968e64-109e-470b-aea3-ea706a574e89', '唐', '["仲月開凌室，齋心感聖情。","寒姿分玉坐，皓彩發丹楹。","積素因風壯，虛空向日明。","遙涵牕戶冷，近映冕旒清。","在掌光逾澈，當軒質自輕。","良辰方可致，由此表精誠。"]', '["仲月开凌室，斋心感聖情。","寒姿分玉坐，皓彩發丹楹。","積素因风壯，虛空向日明。","遙涵牕戶冷，近映冕旒清。","在掌光逾澈，當軒質自轻。","良辰方可致，由此表精誠。"]', '诗', 'shi', '', NULL, '薦冰 趙蕃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('820e1560-e3c9-4601-a27e-eaa404a6f878', '老人星', '老人星', 'd4968e64-109e-470b-aea3-ea706a574e89', '唐', '["大史占南極，秋分見壽星。","增輝延寶曆，發曜起祥經。","灼爍依狼地，昭彰近帝庭。","高懸方杳杳，孤白乍熒熒。","應見光新吐，休徵德自形。","既能符聖柞，從此表遐齡。"]', '["大史占南極，秋分见壽星。","增輝延寶曆，發曜起祥經。","灼爍依狼地，昭彰近帝庭。","高懸方杳杳，孤白乍熒熒。","應见光新吐，休徵德自形。","既能符聖柞，從此表遐齡。"]', '诗', 'shi', '', NULL, '老人星 趙蕃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('facf2f2e-e60d-4c8c-ad4a-e2164333ffb1', '古意', '古意', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["女蘿寄青松，綠蔓花綿綿。","三五定君婚，結髮早移天。","肅肅羔鴈禮，泠泠琴瑟篇。","恭承采蘩祀，敢効同車賢。","皎日不留景，良辰如逝川。","愁心忽移愛，花貌無歸妍。","翠袖皓珠粉，碧階封綠錢。","新人易如玉，廢瑟難爲弦。","寄謝蕣華木，榮君香閣前。","豈無搖落苦，貴與根蒂連。","希君舊光景，照妾薄暮年。"]', '["女蘿寄青松，綠蔓花綿綿。","三五定君婚，結髮早移天。","肅肅羔鴈禮，泠泠琴瑟篇。","恭承采蘩祀，敢効同车賢。","皎日不留景，良辰如逝川。","愁心忽移愛，花貌無归妍。","翠袖皓珠粉，碧階封綠錢。","新人易如玉，廢瑟难爲弦。","寄謝蕣华木，榮君香閣前。","豈無搖落苦，貴與根蒂連。","希君旧光景，照妾薄暮年。"]', '诗', 'shi', '', NULL, '古意 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e919f17-21ed-4f00-b331-78d9e2f39f36', '蕭史圖歌', '蕭史圖歌', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["霜綃數幅八月天，綵龍引鳳堂堂然。","小載蕭僊穆公女，隨仙上歸玉京去。","仙路迢遙煙幾重，女衣清淨雲三素。","胡髯毿珊雲髻光，翠蕤皎潔瓊華涼。","露痕煙跡漬紅貌，疑別秦宮初斷腸。","此天每在西北上，紫霄洞客曉煙望。"]', '["霜綃數幅八月天，綵龙引鳳堂堂然。","小載蕭僊穆公女，隨仙上归玉京去。","仙路迢遙煙幾重，女衣清淨云三素。","胡髯毿珊云髻光，翠蕤皎潔瓊华涼。","露痕煙跡漬紅貌，疑別秦宮初斷腸。","此天每在西北上，紫霄洞客晓煙望。"]', '诗', 'shi', '', NULL, '蕭史圖歌 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8311a574-3e0a-4beb-a09d-7e96cef3b10c', '會仙歌', '會仙歌', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["輕輕濛濛，龍言鳳語何從容。","耳有響兮目無踪，杳杳默默。","花張錦織，王[母]初自崑崙來。","茅盈王方平在側，青毛仙鳥銜錦符。","謹上阿環起居王母書，始知僊事亦多故。","一隔絳河千歲餘，詳玉字。","多喜氣，瑤臺明月來墮地。","冠劒低昂蹈舞頻，禮容盡若君臣事。","願言小仙藝，姓名許飛瓊。","洞陰玉磬敲天聲，樂王[母]，一送玉杯長命酒。","碧花醉，靈揚揚，笑賜二子長生方。","二子未及伸拜謝，蒼蒼上兮皇皇下。"]', '["轻轻濛濛，龙言鳳語何從容。","耳有响兮目無踪，杳杳默默。","花張錦织，王[母]初自崑崙来。","茅盈王方平在側，青毛仙鸟銜錦符。","謹上阿环起居王母书，始知僊事亦多故。","一隔絳河千歲餘，詳玉字。","多喜氣，瑤台明月来墮地。","冠劒低昂蹈舞頻，禮容尽若君臣事。","願言小仙藝，姓名許飞瓊。","洞陰玉磬敲天声，乐王[母]，一送玉杯长命酒。","碧花醉，靈揚揚，笑賜二子长生方。","二子未及伸拜謝，蒼蒼上兮皇皇下。"]', '诗', 'shi', '', NULL, '會仙歌 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5469871-f190-4906-9f50-27448cc64872', '李夫人歌', '李夫人歌', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["璿閨羽帳華燭陳，方士夜降夫人神。","葳蕤半露芙蓉色，窈窕將期環珮身。","麗如三五月，可望難親近。","嚬黛含犀竟不言，春思秋怨誰能問。","欲求巧笑如生時，歌塵在空瑟銜絲。","神來未及夢相見，帝比初亡心更悲。","愛之欲其生又死，東流萬代無迴水。","宮漏丁丁夜向晨，煙消霧散愁方士。"]', '["璿閨羽帳华燭陳，方士夜降夫人神。","葳蕤半露芙蓉色，窈窕將期环珮身。","丽如三五月，可望难親近。","嚬黛含犀竟不言，春思秋怨誰能问。","欲求巧笑如生时，歌塵在空瑟銜絲。","神来未及梦相见，帝比初亡心更悲。","愛之欲其生又死，东流万代無迴水。","宮漏丁丁夜向晨，煙消霧散愁方士。"]', '诗', 'shi', '', NULL, '李夫人歌 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6591c871-c724-42c1-8038-205060c93540', '水殿采菱歌', '水殿采菱歌', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["宮鴉叫赤光，潮聲入宮宮影涼。","火華啼露卷橫塘，金堤四合宛柔揚。","美人荷裙芙蓉妝，柔荑縈霧櫂龍航。","采蓮一聲歌態長，青絲結眼捕鴛鴦。"]', '["宮鴉叫赤光，潮声入宮宮影涼。","火华啼露卷橫塘，金堤四合宛柔揚。","美人荷裙芙蓉妝，柔荑縈霧櫂龙航。","采蓮一声歌態长，青絲結眼捕鴛鴦。"]', '诗', 'shi', '', NULL, '水殿采菱歌 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29e61c7a-6386-478d-a35f-81ea451bce21', '周先生畫洞庭歌', '周先生畫洞庭歌', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["江南客，水爲鄉，舟爲宅，能以筆鋒知地脈。","閑分楚水入丹青，不下此堂臨洞庭。","水文不浪煙不動，木末稜稜山碧重。","帝子應哀窈窕雲，客人似得嬋娟夢。","六月火光衣上生，齋心寂聽潺湲聲。","林冰搖鏡水拂簟，盡日獨臥秋風清。"]', '["江南客，水爲乡，舟爲宅，能以笔鋒知地脈。","闲分楚水入丹青，不下此堂臨洞庭。","水文不浪煙不动，木末稜稜山碧重。","帝子應哀窈窕云，客人似得嬋娟梦。","六月火光衣上生，斋心寂听潺湲声。","林冰搖镜水拂簟，尽日独臥秋风清。"]', '诗', 'shi', '', NULL, '周先生畫洞庭歌 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f92abb6-a723-45a1-baf0-dc5c4078a0ef', '霓裳羽衣歌', '霓裳羽衣歌', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["玉煙生窗午輕凝，晨華左耀鮮相凌。","人言天孫機上親手迹，有時怨別無所惜。","遂令武帝厭雲韶，金針天絲綴飄飄。","五聲寫出心中見，拊石喧金栢梁殿。","此衣春日賜何人，秦女腰肢輕若燕。","香風間旋衆彩隨，聯聯珍珠貫長絲。","眼前意是三清客，星宿離離遶身白。","鸞鳳有聲不見身，出宮入徵隨伶人。","神仙如月只可望，瑤華池頭幾惆悵。","喬山一閉曲未終，鼎湖秋驚白頭浪。"]', '["玉煙生窗午轻凝，晨华左耀鲜相凌。","人言天孫機上親手迹，有时怨別無所惜。","遂令武帝厭云韶，金針天絲綴飄飄。","五声寫出心中见，拊石喧金栢梁殿。","此衣春日賜何人，秦女腰肢轻若燕。","香风间旋衆彩隨，聯聯珍珠貫长絲。","眼前意是三清客，星宿離離遶身白。","鸾鳳有声不见身，出宮入徵隨伶人。","神仙如月只可望，瑤华池头幾惆悵。","喬山一閉曲未終，鼎湖秋驚白头浪。"]', '诗', 'shi', '', NULL, '霓裳羽衣歌 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('660dc0ac-3a1f-4527-b472-1671fe3bcb3f', '寓興', '寓兴', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["念來若望神，追往如話夢。","夢神不無跡，誰使煩心用。","魯聖虛泣鱗，楚狂浪歌鳳。","那言阮家子，更作窮途慟。"]', '["念来若望神，追往如話梦。","梦神不無跡，誰使煩心用。","魯聖虛泣鱗，楚狂浪歌鳳。","那言阮家子，更作窮途慟。"]', '诗', 'shi', '', NULL, '寓興 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e10f90db-3c4b-427a-9748-733582b40c60', '遊山', '游山', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["白道行深雲，雲高路彌細。","時時天上客，遺路人間世。","煙花最深處，井臼得空刺。","天寒鶴巢林，石長泉脈閉。","神化萬靈集，心期一朝契。","不見金板書，誰知阮家裔。","終期太古人，問取松柏歲。"]', '["白道行深云，云高路彌細。","时时天上客，遺路人间世。","煙花最深处，井臼得空刺。","天寒鹤巢林，石长泉脈閉。","神化万靈集，心期一朝契。","不见金板书，誰知阮家裔。","終期太古人，问取松柏歲。"]', '诗', 'shi', '', NULL, '遊山 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be59a7d5-933d-4dae-9bca-c1880437d8a7', '隋宮', '隋宮', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["御街多行客，行客悲春風。","楚老幾代人，種田煬帝宮。","零落池臺勢，高低禾黍中。"]', '["御街多行客，行客悲春风。","楚老幾代人，種田煬帝宮。","零落池台勢，高低禾黍中。"]', '诗', 'shi', '', NULL, '隋宮 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84badf2a-804e-4def-9704-f8886aa4bfce', '懷仙二首 一', '懷仙二首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["崑崙九層臺，臺上宮城峻。","西母持地圖，東來獻虞舜。","虞宮禮成後，迴駕仙風順。","十二樓上人，笙歌沸天引。","裴迴扶桑路，白日生離恨。","青鳥更不來，麻姑斷書信。","乃知東海水，清淺誰能問。"]', '["崑崙九層台，台上宮城峻。","西母持地圖，东来獻虞舜。","虞宮禮成後，迴駕仙风順。","十二楼上人，笙歌沸天引。","裴迴扶桑路，白日生離恨。","青鸟更不来，麻姑斷书信。","乃知东海水，清淺誰能问。"]', '诗', 'shi', '', NULL, '懷仙二首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6deba95b-4f6f-4380-8bea-ae266102f917', '懷仙二首 二', '懷仙二首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["閬峰綺閣幾千丈，瑤水西流十二城。","曾見周靈王太子，碧桃花下自吹笙。"]', '["閬峰綺閣幾千丈，瑤水西流十二城。","曾见周靈王太子，碧桃花下自吹笙。"]', '诗', 'shi', '', NULL, '懷仙二首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b6346c1-d8ad-4c81-86b3-5b148d34e4dc', '懷遠人', '懷远人', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["遠道在天際，客行如浮雲。","浮雲不知歸，似我長望君。","秋至漢水高，南音何時聞？","瑤草難遠寄，西風氣氤氳。","常恐山岳遊，不反鸞鳳羣。","無厭坐遲人，風雨驚斯文。"]', '["远道在天際，客行如浮云。","浮云不知归，似我长望君。","秋至漢水高，南音何时闻？","瑤草难远寄，西风氣氤氳。","常恐山岳游，不反鸾鳳羣。","無厭坐遲人，风雨驚斯文。"]', '诗', 'shi', '', NULL, '懷遠人 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdc7299a-dc10-4829-8514-7f6674b06ee7', '懷尹真人', '懷尹真人', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["萬里疊嶂翠，一心浮雲閑。","羽人杏花發，倚樹紅瓊顏。","流水杳冥外，女蘿陰蔭間。","却思人間世，多恐不可還。","青鳥飛難遠，春雲晴不閑。","但恐五雲車，山上復有山。"]', '["万里叠嶂翠，一心浮云闲。","羽人杏花發，倚樹紅瓊顏。","流水杳冥外，女蘿陰蔭间。","却思人间世，多恐不可還。","青鸟飞难远，春云晴不闲。","但恐五云车，山上复有山。"]', '诗', 'shi', '', NULL, '懷尹真人 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4df53de8-a639-454b-a2fd-e39e95a37593', '秋晚銅山道中宿隱者', '秋晚銅山道中宿隐者', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["我鄉山川遙，秋晚空景促。","天明共雲散，日落依鳥宿。","主人逃名子，鶴髮臥空谷。","野言得真風，山貌宜古服。","喜於無聲地，暫傲羲皇俗。","秋窗照疎螢，寒犬吠落木。","朝隱留此處，一點天邊宿。","今憶見此時，添悲覽止足。","遲遲清夜晝，幽路出深竹。","笑謝萬戶侯，余將耻干祿。"]', '["我乡山川遙，秋晚空景促。","天明共云散，日落依鸟宿。","主人逃名子，鹤髮臥空谷。","野言得真风，山貌宜古服。","喜於無声地，暫傲羲皇俗。","秋窗照疎螢，寒犬吠落木。","朝隐留此处，一点天邊宿。","今憶见此时，添悲覽止足。","遲遲清夜晝，幽路出深竹。","笑謝万戶侯，余將耻干祿。"]', '诗', 'shi', '', NULL, '秋晚銅山道中宿隱者 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2a0d38-fc11-413d-bb46-823affc9b03f', '感懷', '感懷', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["宿心不覺遠，事去勞追憶。","曠古川上懷，東流幾時息。","門前青山路，眼見歸不得。","曉夢雲月光，過秋蘭蕙色。"]', '["宿心不覺远，事去勞追憶。","曠古川上懷，东流幾时息。","门前青山路，眼见归不得。","晓梦云月光，過秋蘭蕙色。"]', '诗', 'shi', '', NULL, '感懷 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d302e3-24e3-441d-90b3-723633298677', '經秦皇墓', '經秦皇墓', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["左崗青虬盤，右坂白虎踞。","誰識此中陵，祖龍藏身處。","別爲一天地，下入三泉路。","珠華翔青鳥，玉影耀白兔。","山河一易姓，萬事隨人去。","白晝盜開陵，玄冬火焚樹。","哀哉送死厚，乃爲棄身具。","死者不復知，回看漢文墓。"]', '["左崗青虬盤，右坂白虎踞。","誰識此中陵，祖龙藏身处。","別爲一天地，下入三泉路。","珠华翔青鸟，玉影耀白兔。","山河一易姓，万事隨人去。","白晝盜开陵，玄冬火焚樹。","哀哉送死厚，乃爲棄身具。","死者不复知，回看漢文墓。"]', '诗', 'shi', '', NULL, '經秦皇墓 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('114a62cf-942e-4515-aa95-8988f3a30e72', '將歸舊山留別孟郊', '將归旧山留別孟郊', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["擇木無利刃，羨魚無巧綸。","如何不量力，自取中路貧。","前者不厭耕，一日不離親。","今來千里外，我心不在身。","悠悠慈母心，惟願才如人。","蠶桑能幾許，衣服常著新。","一飯吐尺絲，誰見此殷勤。","別君歸耕去，持火燒車輪。"]', '["擇木無利刃，羨鱼無巧綸。","如何不量力，自取中路貧。","前者不厭耕，一日不離親。","今来千里外，我心不在身。","悠悠慈母心，惟願才如人。","蠶桑能幾許，衣服常著新。","一飯吐尺絲，誰见此殷勤。","別君归耕去，持火燒车輪。"]', '诗', 'shi', '', NULL, '將歸舊山留別孟郊 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fe1fcd8-245c-4eaa-b9b2-6534588e6788', '留辭杜員外式方', '留辞杜員外式方', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["東風吹旅懷，鄉夢無夜無。","慚見君子堂，貧思上歸途。","海岳泛念深，涓塵復何須。","婆娑不在本，屈曲無弦弧。","惻惻奉離尊，承歡獨向隅。","時當鳳來日，孰用雞鳴夫。","迴首九仙門，皇家在玉壺。","慙非海人別，淚下不成珠。"]', '["东风吹旅懷，乡梦無夜無。","慚见君子堂，貧思上归途。","海岳泛念深，涓塵复何須。","婆娑不在本，屈曲無弦弧。","惻惻奉離尊，承歡独向隅。","时當鳳来日，孰用雞鳴夫。","迴首九仙门，皇家在玉壺。","慙非海人別，泪下不成珠。"]', '诗', 'shi', '', NULL, '留辭杜員外式方 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0026fed-1541-449e-a24c-088a841ea78d', '長城', '长城', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["蒙公虜生人，北築秦氏冤。","禍興蕭牆內，萬里防禍根。","城成六國亡，宮闕啟千門。","生人半爲土，何用空中原。","奈何家天下，骨肉尚無恩。","投沙擁海水，安得久不翻。","乘高慘人魂，寒日易黃昏。","枯骨貫朽鐵，砂中如有言。","萬古驪山下，徒悲野火燔。"]', '["蒙公虜生人，北築秦氏冤。","禍兴蕭牆內，万里防禍根。","城成六国亡，宮闕啟千门。","生人半爲土，何用空中原。","奈何家天下，骨肉尚無恩。","投沙擁海水，安得久不翻。","乘高慘人魂，寒日易黄昏。","枯骨貫朽鐵，砂中如有言。","万古驪山下，徒悲野火燔。"]', '诗', 'shi', '', NULL, '長城 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b48abf4f-005f-4e54-9016-1aec061f38f1', '蔡平喜遇河陽馬判官寬話別', '蔡平喜遇河陽马判官寬話別', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["從事東軍正四年，相逢且喜偃兵前。","看尋狡兔翻三窟，見射妖星落九天。","江上柳營迴鼓角，河陽花府望神仙。","秋風蕭颯醉中別，白馬嘶霜鴈叫煙。"]', '["從事东軍正四年，相逢且喜偃兵前。","看尋狡兔翻三窟，见射妖星落九天。","江上柳營迴鼓角，河陽花府望神仙。","秋风蕭颯醉中別，白马嘶霜鴈叫煙。"]', '诗', 'shi', '', NULL, '蔡平喜遇河陽馬判官寬話別 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f6ddbe7-fd35-4389-9cba-de7e2a142333', '寄福州從事殷堯藩', '寄福州從事殷堯藩', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["越嶺寒輕物象殊，海城臺閣似蓬壺。","幾迴入市鮫綃女，終歲啼花山鷓鴣。","雷令劒龍知去未，虎夷雲鶴亦來無。","就中靜事冥宵話，何惜雙輪訪病夫。"]', '["越嶺寒轻物象殊，海城台閣似蓬壺。","幾迴入市鮫綃女，終歲啼花山鷓鴣。","雷令劒龙知去未，虎夷云鹤亦来無。","就中静事冥宵話，何惜雙輪訪病夫。"]', '诗', 'shi', '', NULL, '寄福州從事殷堯藩 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1df60304-17f6-4338-8fe2-6c6c1a8f38dc', '壯士行', '壯士行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["西方太白高，壯士羞病死。","心知報恩處，對酒歌易水。","沙鴻嘷天末，橫劒別妻子。","蘇武執節歸，班超束書起。","山河不足重，重在遇知己。"]', '["西方太白高，壯士羞病死。","心知報恩处，对酒歌易水。","沙鴻嘷天末，橫劒別妻子。","蘇武執節归，班超束书起。","山河不足重，重在遇知己。"]', '诗', 'shi', '', NULL, '壯士行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a36fbb37-c2b8-4ebb-a2a0-101022b81766', '章華宮行', '章华宮行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["煙渚南鴻呼曉羣，章華宮娥怨行雲。","十二巫峯仰天祿，金車何處邀雲宿。","小腰婑墮三千人，宮衣水碧顏青春。","豈無一人似神女，忍使黛蛾常不伸。","黛蛾不伸猶自可，春朝諸處門常鏁。"]', '["煙渚南鴻呼晓羣，章华宮娥怨行云。","十二巫峯仰天祿，金车何处邀云宿。","小腰婑墮三千人，宮衣水碧顏青春。","豈無一人似神女，忍使黛蛾常不伸。","黛蛾不伸猶自可，春朝諸处门常鏁。"]', '诗', 'shi', '', NULL, '章華宮行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c04dcaa1-533a-4ff3-859f-e51e3e52de38', '倚瑟行', '倚瑟行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["金輿傳驚灞滻水，龍旗參天行殿巍。","左文皇帝右慎姬，北面侍臣張釋之。","因高知處邯鄲道，壽陵已見生秋草。","萬世何人不此歸，一言出口堪生老。","高歌倚瑟流清悲，徐樂哀生知爲誰。","臣驚歡歎不可放，願賜一言釋名妄。","明珠爲日紅亭亭，水銀爲河玉爲星。","泉宮一閉秦國喪，牧童弄火驪山上。","與世無情在速貧，棄尸于野由斯葬。","生死茫茫不可知，視不一姓君莫悲。","始皇有訓二世哲，君獨何人至於斯。","灞陵一代無發毀，儉風本是張廷尉。"]', '["金輿傳驚灞滻水，龙旗參天行殿巍。","左文皇帝右慎姬，北面侍臣張釋之。","因高知处邯鄲道，壽陵已见生秋草。","万世何人不此归，一言出口堪生老。","高歌倚瑟流清悲，徐乐哀生知爲誰。","臣驚歡歎不可放，願賜一言釋名妄。","明珠爲日紅亭亭，水銀爲河玉爲星。","泉宮一閉秦国喪，牧童弄火驪山上。","與世無情在速貧，棄尸于野由斯葬。","生死茫茫不可知，視不一姓君莫悲。","始皇有訓二世哲，君独何人至於斯。","灞陵一代無發毀，儉风本是張廷尉。"]', '诗', 'shi', '', NULL, '倚瑟行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('517b0595-b7cd-41dc-9ee7-b8b4a9a2f076', '辭輦行', '辞輦行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["漢家代久淳風薄，帝重微行極荒樂。","青娥三千奉一人，班女不以色事君。","朝停玉輦詔同載，三十六宮皆眄睞。","不驚六馬緩天儀，從容鳴環前致辭。","君恩如海深難竭，妾命如絲輕易絕。","願陪阿[母]同小星，敢使太陽齊萬物。","周末幽王不可宗，妾聞上聖遺休風。","五更三老待白日，八十一女居深宮。","願將輦內有餘席，迴賜忠臣妾恩澤。"]', '["漢家代久淳风薄，帝重微行極荒乐。","青娥三千奉一人，班女不以色事君。","朝停玉輦詔同載，三十六宮皆眄睞。","不驚六马緩天儀，從容鳴环前致辞。","君恩如海深难竭，妾命如絲轻易絕。","願陪阿[母]同小星，敢使太陽齊万物。","周末幽王不可宗，妾闻上聖遺休风。","五更三老待白日，八十一女居深宮。","願將輦內有餘席，迴賜忠臣妾恩澤。"]', '诗', 'shi', '', NULL, '辭輦行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dfd87b6-3a34-4abd-bfea-b32c46479f15', '巢烏行', '巢烏行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["烏生幾子林蕭條，雄烏求食雌守巢。","夜愁風雨巢傾覆，常見一烏巢下宿。","日長雛飢雄未迴，雌鳥下巢去哀哀。","野田春盡少遺穀，尋食不得飢飛來。","黃雀亦引數青雀，雀飛未遠烏驚落。","既分青雀噉爾雛，爾雛雖長心何如。","將飛不飛猶未忍，古瑟寫哀哀不盡。"]', '["烏生幾子林蕭條，雄烏求食雌守巢。","夜愁风雨巢傾覆，常见一烏巢下宿。","日长雛飢雄未迴，雌鸟下巢去哀哀。","野田春尽少遺穀，尋食不得飢飞来。","黄雀亦引數青雀，雀飞未远烏驚落。","既分青雀噉爾雛，爾雛雖长心何如。","將飞不飞猶未忍，古瑟寫哀哀不尽。"]', '诗', 'shi', '', NULL, '巢烏行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b51abdeb-6419-4388-8f9f-ea10bea79d4e', '姑蘇宮行', '姑蘇宮行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["姑蘇宮，九層金臺半虛空。","雕楹璇題鬬皎潔，中有妖姬似明月。","西見洞庭秋鏡開，水華百里盤宮來。","越王采女能水戲，仙舟如龍旌曳翠。","羽蓋晴翻橘柚香，玉笙夜送芙蓉醉。","歸帆平靜君無勞，還從下下上高高。"]', '["姑蘇宮，九層金台半虛空。","雕楹璇題鬬皎潔，中有妖姬似明月。","西见洞庭秋镜开，水华百里盤宮来。","越王采女能水戲，仙舟如龙旌曳翠。","羽蓋晴翻橘柚香，玉笙夜送芙蓉醉。","归帆平静君無勞，還從下下上高高。"]', '诗', 'shi', '', NULL, '姑蘇宮行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4224d002-b9c7-458b-9ee1-3c751c9062a0', '悲哉行', '悲哉行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["促促晨復昏，死生同一源。","貴年不懼老，賤老傷久存。","朗朗哭前歌，絳旌引幽魂。","來爲千金子，去臥百草根。","黃土塞生路，悲風送回轅。","金鞍舊良馬，四顧不入門。","生結千歲念，榮華及百孫。","黃金買性命，白刃酬一言。","寧知北山下，松柏侵田園。"]', '["促促晨复昏，死生同一源。","貴年不懼老，賤老傷久存。","朗朗哭前歌，絳旌引幽魂。","来爲千金子，去臥百草根。","黄土塞生路，悲风送回轅。","金鞍旧良马，四顧不入门。","生結千歲念，榮华及百孫。","黄金買性命，白刃酬一言。","寧知北山下，松柏侵田园。"]', '诗', 'shi', '', NULL, '悲哉行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cd4d6dd-cfc6-44aa-8af3-30400208b3db', '元日早朝行', '元日早朝行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["乾元發生春爲宗，盛德在天斗建東。","東方歲星大明宮，南山喜氣搖晴空。","望雲五等舞萬玉，獻壽一聲出千峯。","文章垂彩禮樂正，太白下直旌旗紅。","旌旗不斷春風前，直如朱繩非爾妍。"]', '["乾元發生春爲宗，盛德在天斗建东。","东方歲星大明宮，南山喜氣搖晴空。","望云五等舞万玉，獻壽一声出千峯。","文章垂彩禮乐正，太白下直旌旗紅。","旌旗不斷春风前，直如朱繩非爾妍。"]', '诗', 'shi', '', NULL, '元日早朝行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('277be1b3-68eb-4327-a97d-eab65070bdbb', '秋懷五首 一', '秋懷五首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["促促生有涯，營營意無限。","無限意未申，有涯生已晚。","恩榮不可恃，天道歸寸管。","老如影隨人，時若車下坂。","行者歸期盡，居人心更遠。","涼風日蕭條，親戚長在眼。","多憂知無奈，聖賢莫能免。","客鳥投本枝，生生復深淺。"]', '["促促生有涯，營營意無限。","無限意未申，有涯生已晚。","恩榮不可恃，天道归寸管。","老如影隨人，时若车下坂。","行者归期尽，居人心更远。","涼风日蕭條，親戚长在眼。","多憂知無奈，聖賢莫能免。","客鸟投本枝，生生复深淺。"]', '诗', 'shi', '', NULL, '秋懷五首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c6e24d7-0b15-46f6-b790-f9295f1fd0a4', '秋懷五首 二', '秋懷五首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["秋曉客迢迢，月清風楚楚。","草蟲夜侵我，唧唧牀下語。","流年白日馳，微願不我與。","心如繅絲綸，展轉多頭緒。","憑觴散煩襟，援瑟清夜拊。","迴感帝子心，空堂有煙雨。","絲減悲不減，器新聲更古。","一弦有餘哀，何況二十五。"]', '["秋晓客迢迢，月清风楚楚。","草蟲夜侵我，唧唧牀下語。","流年白日驰，微願不我與。","心如繅絲綸，展轉多头緒。","憑觴散煩襟，援瑟清夜拊。","迴感帝子心，空堂有煙雨。","絲減悲不減，器新声更古。","一弦有餘哀，何況二十五。"]', '诗', 'shi', '', NULL, '秋懷五首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a94c12-7462-4174-891e-4e1f01a80821', '秋懷五首 三', '秋懷五首 三', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["九月夜如年，幽房勞別夢。","不知別日遠，夜夜猶相送。","玉牀暗蟲響，錦席寒淚凍。","明鏡失舊人，空林誤歸鳳。","新年堪愛惜，錦字亦珍重。","一念皎皎時，幽襟非所用。"]', '["九月夜如年，幽房勞別梦。","不知別日远，夜夜猶相送。","玉牀暗蟲响，錦席寒泪凍。","明镜失旧人，空林誤归鳳。","新年堪愛惜，錦字亦珍重。","一念皎皎时，幽襟非所用。"]', '诗', 'shi', '', NULL, '秋懷五首 三 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d8667b-7871-4db3-a8d4-206f4b96ccba', '秋懷五首 四', '秋懷五首 四', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["金氣白日來，疎黃滿河關。","平居乏愉悅，況復身險艱。","一憶故鄉居，一望客人還。","兩心四海中，誰不傷朱顏。","雙燕不巢樹，浮萍不出山。","性命君由天，安得易其間。","休悲砌蟲苦，此日無人閑。"]', '["金氣白日来，疎黄满河关。","平居乏愉悅，況复身險艱。","一憶故乡居，一望客人還。","兩心四海中，誰不傷朱顏。","雙燕不巢樹，浮萍不出山。","性命君由天，安得易其间。","休悲砌蟲苦，此日無人闲。"]', '诗', 'shi', '', NULL, '秋懷五首 四 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f984ba-f8fb-4eb4-ae65-ad5b10233ec3', '秋懷五首 五', '秋懷五首 五', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["龍荒變露色，燕鴈南爲客。","遊子聲影中，涕零念離析。","四時如車馬，轉此今與昔。","往歎在空中，存事委幽迹。","翩翩日歛照，朗朗月繫夕。","物生春不留，年壯老還迫。","天機杳何爲，長壽與松柏。"]', '["龙荒变露色，燕鴈南爲客。","游子声影中，涕零念離析。","四时如车马，轉此今與昔。","往歎在空中，存事委幽迹。","翩翩日歛照，朗朗月繫夕。","物生春不留，年壯老還迫。","天機杳何爲，长壽與松柏。"]', '诗', 'shi', '', NULL, '秋懷五首 五 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43220e26-c586-418c-a20b-102a4536a4a0', '秋夜對月懷李正封', '秋夜对月懷李正封', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["援琴悵獨立，高月對秋堂。","美人遠於月，徒望空景光。","坐憶執手時，七弦起淒涼。","平生知音少，君子安可忘。","客意如夢寐，路岐遍四方。","日遠迷所之，滿天心暗傷。","主奉二鯉魚，中含五文章。","惜無千金荅，愁思盈中腸。","此夕臨風歎，零露霑衣裳。"]', '["援琴悵独立，高月对秋堂。","美人远於月，徒望空景光。","坐憶執手时，七弦起淒涼。","平生知音少，君子安可忘。","客意如梦寐，路岐遍四方。","日远迷所之，满天心暗傷。","主奉二鯉鱼，中含五文章。","惜無千金荅，愁思盈中腸。","此夕臨风歎，零露霑衣裳。"]', '诗', 'shi', '', NULL, '秋夜對月懷李正封 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ef68ff3-e364-4e3c-b94c-ce03bf079f09', '廬山石鏡', '廬山石镜', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["東巖採薇人，巖際朝見月。","怪墮幽蘿間，非時更澄徹。","綠蘿就玉兔，再與高鳥歇。","清光照掌中，始悟石上發。","誰傳陰陽火，鑄此天地物。","深影藏半山，虛輪帶凝雪。","早迴謝公賞，今遇樵夫說。","白日乘綵霞，翩翩對容髮。","我圖辨鬼魅，信美留煙闕。","形神乍相逢，竟夕難取別。","如其終身照，可化黃金骨。"]', '["东巖採薇人，巖際朝见月。","怪墮幽蘿间，非时更澄徹。","綠蘿就玉兔，再與高鸟歇。","清光照掌中，始悟石上發。","誰傳陰陽火，鑄此天地物。","深影藏半山，虛輪带凝雪。","早迴謝公賞，今遇樵夫说。","白日乘綵霞，翩翩对容髮。","我圖辨鬼魅，信美留煙闕。","形神乍相逢，竟夕难取別。","如其終身照，可化黄金骨。"]', '诗', 'shi', '', NULL, '廬山石鏡 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f78fd453-41dc-47cb-adaa-c2c86dde0f7b', '與峨眉山道士期盡日不至', '與峨眉山道士期尽日不至', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["傾景安再中，人生有何常。","胡爲少君別，風馭峨眉陽。","結我千日期，青山故人堂。","期盡師不至，望雲空燒香。","顧慙有限身，易老白日光。","懷君屢驚歎，支體安能強。","往聞清修籙，未究服食方。","瑤田有靈芝，眼見不得嘗。","玉壺貯天地，歲月亦已長。","若用壺中景，東溟又堪傷。","寄言赤玉簫，夜夜吹清商。"]', '["傾景安再中，人生有何常。","胡爲少君別，风馭峨眉陽。","結我千日期，青山故人堂。","期尽師不至，望云空燒香。","顧慙有限身，易老白日光。","懷君屢驚歎，支體安能強。","往闻清修籙，未究服食方。","瑤田有靈芝，眼见不得嘗。","玉壺貯天地，歲月亦已长。","若用壺中景，东溟又堪傷。","寄言赤玉簫，夜夜吹清商。"]', '诗', 'shi', '', NULL, '與峨眉山道士期盡日不至 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c0bba7c-2875-48c2-becb-740c1dfb1be6', '述德上太原嚴尚書綬', '述德上太原嚴尚书綬', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["帝命河嶽神，降靈翼軒轅。","天王委管籥，開閉秦門北。","頂戴日月光，口宣雨露言。","甲馬不及汗，天驕自亡魂。","清塚入內地，黃河窮本源。","風雲寢氣象，鳥獸翔旗旛。","軍人歌無胡，長劒倚崑崙。","終古鞭血地，到今耕稼繁。","樵客天一畔，何由拜旌軒。","願請執御臣，爲公動朱轓。","豈令羣荒外，尚有辜帝恩。","願陳田舍歌，暫息四坐喧。","條桑去附枝，薙草絕本根。","可惜漢公主，哀哀嫁烏孫。"]', '["帝命河嶽神，降靈翼軒轅。","天王委管籥，开閉秦门北。","頂戴日月光，口宣雨露言。","甲马不及汗，天驕自亡魂。","清塚入內地，黄河窮本源。","风云寢氣象，鸟獸翔旗旛。","軍人歌無胡，长劒倚崑崙。","終古鞭血地，到今耕稼繁。","樵客天一畔，何由拜旌軒。","願請執御臣，爲公动朱轓。","豈令羣荒外，尚有辜帝恩。","願陳田舍歌，暫息四坐喧。","條桑去附枝，薙草絕本根。","可惜漢公主，哀哀嫁烏孫。"]', '诗', 'shi', '', NULL, '述德上太原嚴尚書綬 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecf449e2-0bb7-44b4-ad5e-42b6dd058af8', '山中懷劉修', '山中懷劉修', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["松老秋意孤，夜涼吟風水。","山人在遠道，相憶中夜起。","春光如不至，幽蘭含香死。","響象離鶴情，念來一相似。","月斜掩扉臥，又在夢魂裏。"]', '["松老秋意孤，夜涼吟风水。","山人在远道，相憶中夜起。","春光如不至，幽蘭含香死。","响象離鹤情，念来一相似。","月斜掩扉臥，又在梦魂裏。"]', '诗', 'shi', '', NULL, '山中懷劉修 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b09c9524-dc3b-46b1-9bf9-7b6b39e0cd7a', '塞下', '塞下', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["北風號薊門，殺氣日夜興。","咸陽三千里，驛馬如飢鷹。","行子久去鄉，逢山不敢登。","寒日慘大野，虜雲若飛鵬。","西北防秋軍，麾幢宿層層。","匈奴天未喪，戰鼓長登登。","漢卒馬上老，繁纓空絲繩。","誠知天所驕，欲罷又不能。"]', '["北风號薊门，殺氣日夜兴。","咸陽三千里，驛马如飢鷹。","行子久去乡，逢山不敢登。","寒日慘大野，虜云若飞鵬。","西北防秋軍，麾幢宿層層。","匈奴天未喪，戰鼓长登登。","漢卒马上老，繁纓空絲繩。","誠知天所驕，欲罷又不能。"]', '诗', 'shi', '', NULL, '塞下 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6f99baf-94e0-4cd9-9eaf-acc51eba1e94', '送僧南遊', '送僧南游', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["且攀隋宮柳，莫憶江南春。","師有懷鄉志，未爲無事人。"]', '["且攀隋宮柳，莫憶江南春。","師有懷乡志，未爲無事人。"]', '诗', 'shi', '', NULL, '送僧南遊 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a27ee11-0b4f-457e-8e48-0b76e3d97483', '行路難', '行路难', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["玉堂向夕如無人，絲竹儼然宮商死。","細人何言入君耳，塵生金罇酒如水。","君今不念歲蹉跎，鴈天明明涼露多。","華燈清凝久照夜，綵僮窈窕虛垂蘿。","入宮見妒君不察，暮入此地生風波。","此時不樂早休息，女顏易老君如何。"]', '["玉堂向夕如無人，絲竹儼然宮商死。","細人何言入君耳，塵生金罇酒如水。","君今不念歲蹉跎，鴈天明明涼露多。","华灯清凝久照夜，綵僮窈窕虛垂蘿。","入宮见妒君不察，暮入此地生风波。","此时不乐早休息，女顏易老君如何。"]', '诗', 'shi', '', NULL, '行路難 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a71418ae-c493-429c-a3b1-a56a5a21887d', '子規', '子規', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["中林子規啼，云是古蜀帝。","蜀帝胡爲鳥，驚急如罪戾。","一啼豔陽節，春色亦可替。","再啼孟夏林，密葉堪委翳。","三啼涼秋曉，百卉無生意。","四啼玄冥冬，雲物慘不霽。","芸黃壯士髮，沾灑妖姬袂。","悲深寒烏雛，哀掩病鶴翅。","胡爲託幽命，庇質無完毳。","戚戚含至冤，卑卑忌羣勢。","吾聞鳳皇長，羽族皆受制。","盍分翡翠毛，使學鸚鵡慧。","敵怨不在弦，一哀尚能繼。","那令不知休，泣血經世世。","古風失中和，衰代因鄭衛。","三歎尚淫哀，向渴嘻流涕。","如因異聲感，樂與中腸契。","至教一昏蕪，生人遂危脆。","古意歎通近，如上青天際。","荼蓼久已甘，空勞菫葵惠。","誰聞子規苦，思與正聲計。"]', '["中林子規啼，云是古蜀帝。","蜀帝胡爲鸟，驚急如罪戾。","一啼豔陽節，春色亦可替。","再啼孟夏林，密葉堪委翳。","三啼涼秋晓，百卉無生意。","四啼玄冥冬，云物慘不霽。","芸黄壯士髮，沾灑妖姬袂。","悲深寒烏雛，哀掩病鹤翅。","胡爲託幽命，庇質無完毳。","戚戚含至冤，卑卑忌羣勢。","吾闻鳳皇长，羽族皆受制。","盍分翡翠毛，使学鸚鵡慧。","敵怨不在弦，一哀尚能繼。","那令不知休，泣血經世世。","古风失中和，衰代因鄭衛。","三歎尚淫哀，向渴嘻流涕。","如因異声感，乐與中腸契。","至教一昏蕪，生人遂危脆。","古意歎通近，如上青天際。","荼蓼久已甘，空勞菫葵惠。","誰闻子規苦，思與正声計。"]', '诗', 'shi', '', NULL, '子規 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba88d0d2-683d-4e0d-904d-98dc638afa1e', '秋夜聞鄭山人彈楚妃怨', '秋夜闻鄭山人彈楚妃怨', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["明月搖落夜，深堂清淨弦。","中間楚妃奏，十指哀嬋娟。","寥寥夜含風，蕩蕩意如泉。","寂寞物無象，依稀語空煙。","旅人多西望，客鴈難南前。","由來感神事，豈爲無情傳。","容華能幾時，不再來者年。","此夕河漢上，雙星含淒然。"]', '["明月搖落夜，深堂清淨弦。","中间楚妃奏，十指哀嬋娟。","寥寥夜含风，蕩蕩意如泉。","寂寞物無象，依稀語空煙。","旅人多西望，客鴈难南前。","由来感神事，豈爲無情傳。","容华能幾时，不再来者年。","此夕河漢上，雙星含淒然。"]', '诗', 'shi', '', NULL, '秋夜聞鄭山人彈楚妃怨 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0c3923f-7b3f-432b-bcda-9577735b0a4f', '憶舊遊', '憶旧游', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["憶求無何鄉，了在赤谷村。","仙人居其中，將往問所存。","日入濛汜宿，石煙抱山門。","明月久不下，半峯照啼猨。","堂上白鶴翁，神清心無煩。","齋心侍席前，跪請長生恩。","云昔崆峒老，何詞受軒轅。","從星使變化，任日張乾坤。","若到舊鄉里，宛如曾討論。","風移嵓花氣，珠貫金經言。","涼夜惜易盡，青煙謝晨喧。","自唯腥膻體，難久留其藩。","幾世身在夢，百年雲無根。","悠悠竟何事，愚智相憂冤。","歎息幾晚寤，蒙師招其魂。","至今瑤華心，每想清水源。"]', '["憶求無何乡，了在赤谷村。","仙人居其中，將往问所存。","日入濛汜宿，石煙抱山门。","明月久不下，半峯照啼猨。","堂上白鹤翁，神清心無煩。","斋心侍席前，跪請长生恩。","云昔崆峒老，何词受軒轅。","從星使变化，任日張乾坤。","若到旧乡里，宛如曾討論。","风移嵓花氣，珠貫金經言。","涼夜惜易尽，青煙謝晨喧。","自唯腥膻體，难久留其藩。","幾世身在梦，百年云無根。","悠悠竟何事，愚智相憂冤。","歎息幾晚寤，蒙師招其魂。","至今瑤华心，每想清水源。"]', '诗', 'shi', '', NULL, '憶舊遊 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eb524f1-b078-4e81-a69c-d5683625ad4a', '白露', '白露', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["清蟬暫休響，豐露還移色。","金飆爽晨華，玉壺增夜刻。","已低疎螢燄，稍減哀蟬力。","迎社促燕心，助風勞鴈翼。","一悲紈扇情，再想清淺憶。","高高拜月歸，軋軋挑燈織。","盈盈玉盤淚，何處無消息。"]', '["清蟬暫休响，豐露還移色。","金飆爽晨华，玉壺增夜刻。","已低疎螢燄，稍減哀蟬力。","迎社促燕心，助风勞鴈翼。","一悲紈扇情，再想清淺憶。","高高拜月归，軋軋挑灯织。","盈盈玉盤泪，何处無消息。"]', '诗', 'shi', '', NULL, '白露 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5a9e67a-1ff0-483c-bed5-852f681f22d6', '經隱叟', '經隐叟', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["行蹋門外泉，坐披牀上雲。","誰將許由事，萬古留與君。","虛洞閉金鏁，蠹簡藏鳥文。","蘿景深的的，蕙風閑薰薰。","余有世上心，此來未及羣。","殷勤諱姓名，莫遣樵客聞。"]', '["行蹋门外泉，坐披牀上云。","誰將許由事，万古留與君。","虛洞閉金鏁，蠹簡藏鸟文。","蘿景深的的，蕙风闲薰薰。","余有世上心，此来未及羣。","殷勤諱姓名，莫遣樵客闻。"]', '诗', 'shi', '', NULL, '經隱叟 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b20bad-8b04-456f-aa5f-d2ada26890ea', '秋暮山中懷李端公益', '秋暮山中懷李端公益', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["舊事與日遠，秋花仍舊香。","前年繡衣客，此節過此堂。","侍臣不自高，笑脫繡衣裳。","眠雲有餘態，入鳥不亂行。","我恐雲嵐色，損君鞍馬光。","君言此何言，且共覆前觴。","古人重一笑，買日輕金裝。","日盡秉燭遊，千年不能忘。","君言此何言，明日皆異鄉。","明日非今日，山下道路長。","一從山下來，天地再炎涼。","此中會難得，夢君馬玄黃。"]', '["旧事與日远，秋花仍旧香。","前年繡衣客，此節過此堂。","侍臣不自高，笑脫繡衣裳。","眠云有餘態，入鸟不亂行。","我恐云嵐色，損君鞍马光。","君言此何言，且共覆前觴。","古人重一笑，買日轻金裝。","日尽秉燭游，千年不能忘。","君言此何言，明日皆異乡。","明日非今日，山下道路长。","一從山下来，天地再炎涼。","此中會难得，梦君马玄黄。"]', '诗', 'shi', '', NULL, '秋暮山中懷李端公益 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb262b65-a14b-4bf4-a32d-7a641244f21b', '苦哉遠征人', '苦哉远征人', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["征人歌古曲，攜手上河梁。","李陵死別處，窅杳玄冥鄉。","憶昔從此路，連年征鬼方。","久行迷漢曆，三死氊衣裳。","百戰身且在，微功信難忘。","遠承雲臺議，非勢孰敢當。","落日弔李廣，白首過河陽。","閑弓失月影，勞劒無龍光。","去日始束髮，今來髮成霜。","虛名乃閑事，生見父母鄉。","掩抑大風歌，裴回少年場。","誠哉古人言，鳥盡良弓藏。"]', '["征人歌古曲，携手上河梁。","李陵死別处，窅杳玄冥乡。","憶昔從此路，連年征鬼方。","久行迷漢曆，三死氊衣裳。","百戰身且在，微功信难忘。","远承云台議，非勢孰敢當。","落日弔李廣，白首過河陽。","闲弓失月影，勞劒無龙光。","去日始束髮，今来髮成霜。","虛名乃闲事，生见父母乡。","掩抑大风歌，裴回少年場。","誠哉古人言，鸟尽良弓藏。"]', '诗', 'shi', '', NULL, '苦哉遠征人 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f612bd25-ffaa-4dd5-ae1d-52bba80c95f8', '悼豆盧策先輩', '悼豆盧策先輩', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["喪車出東門，生時馬無力。","何處入黃泉，嵩高山西北。","室人萬里外，久望君官職。","今與牽衣兒，翻號死消息。","平生江海上，我不空相識。","遠客迷畏途，孤鴻傷一翼。","行將雞黍祭，已是烏鳶食。","勸酒執御郎，行人有哀色。","先悲三尺土，經歲哭不得。","眼前雙雙流，故袂安可拭。","一拜隔千里，生人意何極。","唯有陽春曲，永播清玉德。"]', '["喪车出东门，生时马無力。","何处入黄泉，嵩高山西北。","室人万里外，久望君官職。","今與牽衣兒，翻號死消息。","平生江海上，我不空相識。","远客迷畏途，孤鴻傷一翼。","行將雞黍祭，已是烏鳶食。","勸酒執御郎，行人有哀色。","先悲三尺土，經歲哭不得。","眼前雙雙流，故袂安可拭。","一拜隔千里，生人意何極。","唯有陽春曲，永播清玉德。"]', '诗', 'shi', '', NULL, '悼豆盧策先輩 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc4a03c5-85e3-4e84-aea2-f4690e699c4e', '首夏', '首夏', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["昨日青春去，晚峯尚含妍。","雖留有餘態，脈脈防憂煎。","幽人惜時節，對此感流年。"]', '["昨日青春去，晚峯尚含妍。","雖留有餘態，脈脈防憂煎。","幽人惜时節，对此感流年。"]', '诗', 'shi', '', NULL, '首夏 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82236b8-86a3-4453-8fd4-9a62c209229d', '寄天台準公', '寄天台準公', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["赤城橋東見月夜，佛壠寺邊行月僧。","閑蹋莓苔繞琪樹，海光清淨對心燈。"]', '["赤城橋东见月夜，佛壠寺邊行月僧。","闲蹋莓苔繞琪樹，海光清淨对心灯。"]', '诗', 'shi', '', NULL, '寄天台準公 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17cf2fa-a775-4bd7-ad67-cfb1d6ed6628', '送僧東遊', '送僧东游', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["風流東晉後，外學入僧家。","獨唱郢中雪，還遊天際霞。","雲村共香飯，水月喻秋花。","景物添新致，前程詎可涯。"]', '["风流东晉後，外学入僧家。","独唱郢中雪，還游天際霞。","云村共香飯，水月喻秋花。","景物添新致，前程詎可涯。"]', '诗', 'shi', '', NULL, '送僧東遊 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('132b5e93-03cc-44af-a8e9-415f6b37109a', '送僧之宣城', '送僧之宣城', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["昔從謝太守，賓客宛陵城。","有日持齋戒，高僧識姓名。","秋風送客去，安得盡忘情。"]', '["昔從謝太守，賓客宛陵城。","有日持斋戒，高僧識姓名。","秋风送客去，安得尽忘情。"]', '诗', 'shi', '', NULL, '送僧之宣城 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d0e4cd4-51ef-4292-ad62-647d8205615f', '宣城北樓昔從順陽公會於此', '宣城北楼昔從順陽公會於此', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["詩樓郡城北，窗牖敬亭山。","幾步塵埃隔，終朝世界閑。","憑師看粉壁，名姓在其間。"]', '["诗楼郡城北，窗牖敬亭山。","幾步塵埃隔，終朝世界闲。","憑師看粉壁，名姓在其间。"]', '诗', 'shi', '', NULL, '宣城北樓昔從順陽公會於此 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0ed9984-2332-4b5e-a4f7-b221d9d42274', '東高峯', '东高峯', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["東亭最高峙，春樹繞山腰。","畫裏青鸞客，雲中碧玉簫。","秋風若西望，爲我一長謠。"]', '["东亭最高峙，春樹繞山腰。","畫裏青鸾客，云中碧玉簫。","秋风若西望，爲我一长謠。"]', '诗', 'shi', '', NULL, '東高峯 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caa01581-d8d6-495d-8ade-96176564cb10', '禪定寺經院', '禪定寺經院', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["蓮華不朽寺，雕刻滿山根。","石汗知天雨，金泥落聖言。","思量施金客，千古獨消魂。"]', '["蓮华不朽寺，雕刻满山根。","石汗知天雨，金泥落聖言。","思量施金客，千古独消魂。"]', '诗', 'shi', '', NULL, '禪定寺經院 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07ff702e-afa1-4580-a6cd-edd5c07cad60', '范真傳侍御累有寄因奉酬十首 一', '范真傳侍御累有寄因奉酬十首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["昨日新花紅滿眼，今朝美酒綠留人。","更宜明月含芳露，憑仗蕭郎夜賞春。"]', '["昨日新花紅满眼，今朝美酒綠留人。","更宜明月含芳露，憑仗蕭郎夜賞春。"]', '诗', 'shi', '', NULL, '范真傳侍御累有寄因奉酬十首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c238a50-2d95-477c-b0b5-b8087c88eb49', '范真傳侍御累有寄因奉酬十首 二', '范真傳侍御累有寄因奉酬十首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["白雪翦花朱蠟蒂，折花傳笑惜春人。","請君白日留明日，一醉春風莫厭頻。"]', '["白雪翦花朱蠟蒂，折花傳笑惜春人。","請君白日留明日，一醉春风莫厭頻。"]', '诗', 'shi', '', NULL, '范真傳侍御累有寄因奉酬十首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c089bda-7465-4766-92ec-cd8cf8e8187b', '范真傳侍御累有寄因奉酬十首 三', '范真傳侍御累有寄因奉酬十首 三', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["雲髻鳳文細，對君歌少年。","萬金酬一顧，可惜十千錢。"]', '["云髻鳳文細，对君歌少年。","万金酬一顧，可惜十千錢。"]', '诗', 'shi', '', NULL, '范真傳侍御累有寄因奉酬十首 三 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f366d3cf-0a4c-45aa-85fe-1a706c78b1d3', '范真傳侍御累有寄因奉酬十首 四', '范真傳侍御累有寄因奉酬十首 四', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["玉管傾杯樂，春園鬬草情。","野花無限意，處處逐人行。"]', '["玉管傾杯乐，春园鬬草情。","野花無限意，处处逐人行。"]', '诗', 'shi', '', NULL, '范真傳侍御累有寄因奉酬十首 四 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e0373b-c0ca-429b-a44b-595d9dcd8002', '范真傳侍御累有寄因奉酬十首 五', '范真傳侍御累有寄因奉酬十首 五', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["聞道中山酒，一杯千日醒。","黃鶯似傳語，勸酒太叮嚀。"]', '["闻道中山酒，一杯千日醒。","黄鶯似傳語，勸酒太叮嚀。"]', '诗', 'shi', '', NULL, '范真傳侍御累有寄因奉酬十首 五 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c0c4358-ade3-427e-80b9-e5e3dc0494a6', '范真傳侍御累有寄因奉酬十首 六', '范真傳侍御累有寄因奉酬十首 六', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["紅袂歌聲起，因君始得聞。","黃昏小垂手，與我駐浮雲。"]', '["紅袂歌声起，因君始得闻。","黄昏小垂手，與我駐浮云。"]', '诗', 'shi', '', NULL, '范真傳侍御累有寄因奉酬十首 六 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa2291df-41af-40a5-918b-9066d4f99899', '范真傳侍御累有寄因奉酬十首 七', '范真傳侍御累有寄因奉酬十首 七', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["相勸醉年華，莫醒春日斜。","春風宛陵道，萬里晉陽花。"]', '["相勸醉年华，莫醒春日斜。","春风宛陵道，万里晉陽花。"]', '诗', 'shi', '', NULL, '范真傳侍御累有寄因奉酬十首 七 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddebd259-6943-4890-ba16-80f2031fc9b9', '范真傳侍御累有寄因奉酬十首 八', '范真傳侍御累有寄因奉酬十首 八', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["碧綠草縈堤，紅藍花滿溪。","願君常踐蹋，莫使暗萋萋。"]', '["碧綠草縈堤，紅藍花满溪。","願君常踐蹋，莫使暗萋萋。"]', '诗', 'shi', '', NULL, '范真傳侍御累有寄因奉酬十首 八 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a249ad-546d-4e0f-92aa-ad45b5843466', '范真傳侍御累有寄因奉酬十首 九', '范真傳侍御累有寄因奉酬十首 九', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["萋萋巫峽雲，楚客莫留恩。","歲久晉陽道，誰能向太原。"]', '["萋萋巫峽云，楚客莫留恩。","歲久晉陽道，誰能向太原。"]', '诗', 'shi', '', NULL, '范真傳侍御累有寄因奉酬十首 九 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e580af4-c011-4f1a-9682-e745551a0f0c', '范真傳侍御累有寄因奉酬十首 十', '范真傳侍御累有寄因奉酬十首 十', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["歲酒勸屠蘇，楚聲山鷓鴣。","春風入君意，千日不須臾。"]', '["歲酒勸屠蘇，楚声山鷓鴣。","春风入君意，千日不須臾。"]', '诗', 'shi', '', NULL, '范真傳侍御累有寄因奉酬十首 十 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5febff1-aa0d-482a-91ce-09733762f19d', '越女詞', '越女词', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["越女芙蓉妝，浣紗清淺水。","忽驚春心曉，不敢思君子。","君子縱我思，寧來浣溪裏。"]', '["越女芙蓉妝，浣紗清淺水。","忽驚春心晓，不敢思君子。","君子縱我思，寧来浣溪裏。"]', '诗', 'shi', '', NULL, '越女詞 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f5d3ce-1cd6-4322-a0fe-cbea8245f8d2', '弄玉詞二首 一', '弄玉词二首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["素女結念飛天行，白玉參差鳳皇聲，天仙借女雙翅猛。","五燈繞身生，入煙去無影。"]', '["素女結念飞天行，白玉參差鳳皇声，天仙借女雙翅猛。","五灯繞身生，入煙去無影。"]', '诗', 'shi', '', NULL, '弄玉詞二首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43025c0b-38e4-475c-957b-d10cc8062722', '弄玉詞二首 二', '弄玉词二首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["三清弄玉秦公女，嫁得天上人。","瓊簫碧月喚朱雀，攜手上謁玉晨君。","夫妻同壽，萬萬青春。"]', '["三清弄玉秦公女，嫁得天上人。","瓊簫碧月喚朱雀，携手上謁玉晨君。","夫妻同壽，万万青春。"]', '诗', 'shi', '', NULL, '弄玉詞二首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cca3e969-8205-47ac-baf8-9bf7c29bf0f6', '山行經樵翁', '山行經樵翁', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["我心勞我身，遠道誰與論。","心如木中火，憂至常自燔。","披訪結恩地，世人輕報恩。","女無良媒識，知入何人門。","寒日行深山，路由谷中村。","田翁樵採熟，男女謳吟喧。","借問身命謀，上言媿乾坤。","時清公賦薄，力勤地利繁。","下念草木年，坐家見重孫。","舉案饋賓客，糟漿盈陶尊。","醉閑鹿裘煗，白髮舞軒軒。","仰羨太古人，余將破行轅。","遑遑問身事，師友難爲言。","離歌又行去，落日低寒泉。"]', '["我心勞我身，远道誰與論。","心如木中火，憂至常自燔。","披訪結恩地，世人轻報恩。","女無良媒識，知入何人门。","寒日行深山，路由谷中村。","田翁樵採熟，男女謳吟喧。","借问身命謀，上言媿乾坤。","时清公賦薄，力勤地利繁。","下念草木年，坐家见重孫。","舉案饋賓客，糟漿盈陶尊。","醉闲鹿裘煗，白髮舞軒軒。","仰羨太古人，余將破行轅。","遑遑问身事，師友难爲言。","離歌又行去，落日低寒泉。"]', '诗', 'shi', '', NULL, '山行經樵翁 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79835f5d-98af-4613-a14b-f76ade22009e', '途中旅思二首 一', '途中旅思二首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["喔喔雞鳴曉，蕭蕭馬辭櫪。","草草名利區，居人少於客。","生期三萬日，童耄半虛擲。","修短命半中，憂歡復相敵。","朝提黃金爵，暮造青松宅。","來往日相悲，北邙田土窄。","峨峨西天岳，錦繡明翠壁。","中有不死鄉，千年無人跡。","心期周太子，下馬拜虛碧。","鶴駕如可從，他年執煙策。"]', '["喔喔雞鳴晓，蕭蕭马辞櫪。","草草名利區，居人少於客。","生期三万日，童耄半虛擲。","修短命半中，憂歡复相敵。","朝提黄金爵，暮造青松宅。","来往日相悲，北邙田土窄。","峨峨西天岳，錦繡明翠壁。","中有不死乡，千年無人跡。","心期周太子，下马拜虛碧。","鹤駕如可從，他年執煙策。"]', '诗', 'shi', '', NULL, '途中旅思二首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a295f66-8827-4ca9-963f-c61448db6244', '途中旅思二首 二', '途中旅思二首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["星出方問宿，睡眼始朦朧。","天光見地色，上路車幢幢。","時物既老大，衆山何枯空。","青冥見古栢，寥朗聞疎鴻。","獨步天地間，無因爲君忠。","白毛尋人憂，生此頭髮中。","躍馬非壯歲，報恩無高功。","斯言化爲火，日夜焚深衷。"]', '["星出方问宿，睡眼始朦朧。","天光见地色，上路车幢幢。","时物既老大，衆山何枯空。","青冥见古栢，寥朗闻疎鴻。","独步天地间，無因爲君忠。","白毛尋人憂，生此头髮中。","躍马非壯歲，報恩無高功。","斯言化爲火，日夜焚深衷。"]', '诗', 'shi', '', NULL, '途中旅思二首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9015befa-d621-4ca8-a533-9412338bb0f3', '舊鏡', '旧镜', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["嬋娟本家鏡，與妾歸君子。","每憶並照時，相逢明月裏。","春風忽分影，白日難依倚。","珠粉不結花，玉璫寧輝耳。","心期不可見，不保長如此。","華髮一欺人，青銅化爲鬼。","良人有歸日，肯學妖桃李。","瑤匣若浮雲，冥冥藏玉水。","侍兒不遣照，恐學孤鸞死。"]', '["嬋娟本家镜，與妾归君子。","每憶並照时，相逢明月裏。","春风忽分影，白日难依倚。","珠粉不結花，玉璫寧輝耳。","心期不可见，不保长如此。","华髮一欺人，青銅化爲鬼。","良人有归日，肯学妖桃李。","瑤匣若浮云，冥冥藏玉水。","侍兒不遣照，恐学孤鸾死。"]', '诗', 'shi', '', NULL, '舊鏡 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d7e4c3f-2852-4e6a-b36b-18e75b7c1b59', '宿悟空寺贈僧', '宿悟空寺贈僧', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["勞者謠燭蛾，致身何營營。","雪山本師在，心地如鏡清。","往與本師別，人間買浮名。","朝光畏不久，內火燒人情。","迷路喜爲遠，宿留化人城。","前心宛如此，了了隨靜生。","維持薝蔔花，却與前心行。"]', '["勞者謠燭蛾，致身何營營。","雪山本師在，心地如镜清。","往與本師別，人间買浮名。","朝光畏不久，內火燒人情。","迷路喜爲远，宿留化人城。","前心宛如此，了了隨静生。","維持薝蔔花，却與前心行。"]', '诗', 'shi', '', NULL, '宿悟空寺贈僧 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bf1c336-f8c6-401f-9172-a4cfd2503001', '感興', '感兴', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["幽人無近迹，別易會則稀。","黃鶴亦姓丁，寥寥何處飛？","時見海上山，繞雲心依依。","諒無馭風術，中路愁虛歸。","童髮慕道心，壯年墮塵機。","白日不饒我，如今事皆非。","羣羊化石盡，雙鳧與我違。","□岳黃金富，軒轅曉霞衣。","誰令日在眼，容色煙雲微。"]', '["幽人無近迹，別易會則稀。","黄鹤亦姓丁，寥寥何处飞？","时见海上山，繞云心依依。","諒無馭风術，中路愁虛归。","童髮慕道心，壯年墮塵機。","白日不饒我，如今事皆非。","羣羊化石尽，雙鳧與我違。","□岳黄金富，軒轅晓霞衣。","誰令日在眼，容色煙云微。"]', '诗', 'shi', '', NULL, '感興 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c82ce31-f228-41a1-a960-da4e36b95602', '秋思', '秋思', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["楚客秋更悲，皇皇無聲地。","時無無事人，我命與身異。","良時如飛鳥，回掌成故事。","蹉跎秋定還，凝冽堅冰至。","人生不期老，華髮誰能避。","感此惜壯年，壯年少爲貴。","我生雖努力，榮途難自致。","徒爲擊角歌，且慙雕劒字。","吾師罕言命，感激潛傷思。"]', '["楚客秋更悲，皇皇無声地。","时無無事人，我命與身異。","良时如飞鸟，回掌成故事。","蹉跎秋定還，凝冽堅冰至。","人生不期老，华髮誰能避。","感此惜壯年，壯年少爲貴。","我生雖努力，榮途难自致。","徒爲擊角歌，且慙雕劒字。","吾師罕言命，感激潛傷思。"]', '诗', 'shi', '', NULL, '秋思 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('499c76a4-433c-4dc8-a691-31cfdc21d08c', '客途逢鄉人旋別', '客途逢乡人旋別', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["驚鴻一斷行，天遠會無因。","無因忽相會，感歎若有神。","我鄉路三千，百里一主人。","一宿獨何戀，何況舊鄉鄰。","牢落歲華晏，相憐客中貧。","迎霜君衣煖，與我同一身。","誰在天日下，此生能不勤。","青萍寄流水，安得長相親。","明發更遠道，山河重苦辛。"]', '["驚鴻一斷行，天远會無因。","無因忽相會，感歎若有神。","我乡路三千，百里一主人。","一宿独何戀，何況旧乡鄰。","牢落歲华晏，相怜客中貧。","迎霜君衣煖，與我同一身。","誰在天日下，此生能不勤。","青萍寄流水，安得长相親。","明發更远道，山河重苦辛。"]', '诗', 'shi', '', NULL, '客途逢鄉人旋別 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73021908-2c50-4e4d-bb43-a3081d3ffd90', '隋帝陵下', '隋帝陵下', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["白露沾衣隋主宮，雲亭月館楚淮東。","盤龍樓艦浮冤水，雕錦帆幢使亂風。","長夜應憐桀何罪，告成合笑禹無功。","傷心近似驪山路，陵樹無根秋草中。"]', '["白露沾衣隋主宮，云亭月館楚淮东。","盤龙楼艦浮冤水，雕錦帆幢使亂风。","长夜應怜桀何罪，告成合笑禹無功。","傷心近似驪山路，陵樹無根秋草中。"]', '诗', 'shi', '', NULL, '隋帝陵下 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a1692c9-24e3-447f-a7e8-0e4d50eeedab', '洛陽春望', '洛陽春望', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["五鳳樓南望洛陽，龍門迴合抱蒼蒼。","受朝前殿雲霞煗，封岳行宮草木香。","四海爲家知德盛，二京有宅卜年長。","東人猶憶時巡禮，願覲元和日月光。"]', '["五鳳楼南望洛陽，龙门迴合抱蒼蒼。","受朝前殿云霞煗，封岳行宮草木香。","四海爲家知德盛，二京有宅卜年长。","东人猶憶时巡禮，願覲元和日月光。"]', '诗', 'shi', '', NULL, '洛陽春望 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bb3ff12-7af7-4f58-b077-0e19a8a9b5ea', '始見二毛', '始见二毛', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["玄髮迎憂光色闌，衰華因鏡強相看。","百川赴海返潮易，一葉報秋歸樹難。","初弄藕絲牽欲斷，又驚機素翦仍殘。","顏生豈是光陰晚，余亦何人不自寬。"]', '["玄髮迎憂光色闌，衰华因镜強相看。","百川赴海返潮易，一葉報秋归樹难。","初弄藕絲牽欲斷，又驚機素翦仍殘。","顏生豈是光陰晚，余亦何人不自寬。"]', '诗', 'shi', '', NULL, '始見二毛 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6110615d-4175-46e6-86f4-45e676904579', '巫山懷古', '巫山懷古', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["十二峯巒鬬翠微，石煙花霧犯容輝。","青春楚女妒雲老，白日神人入夢稀。","銀箭暗凋歌夜燭，珠泉頻點舞時衣。","誰傷宋玉千年後，留得青山辨是非。"]', '["十二峯巒鬬翠微，石煙花霧犯容輝。","青春楚女妒云老，白日神人入梦稀。","銀箭暗凋歌夜燭，珠泉頻点舞时衣。","誰傷宋玉千年後，留得青山辨是非。"]', '诗', 'shi', '', NULL, '巫山懷古 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a34239-17b5-4533-a0b5-56220a62bb06', '郊天迴', '郊天迴', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["日動蕭煙上泰壇，帝從黃道整和鑾。","風前貔武迴雕仗，雲裏神龍起畫竿。","金鳥赦書鳴九夜，玉山壽酒舞千官。","始知報本終朝禮，舊典時巡只自難。"]', '["日动蕭煙上泰壇，帝從黄道整和鑾。","风前貔武迴雕仗，云裏神龙起畫竿。","金鸟赦书鳴九夜，玉山壽酒舞千官。","始知報本終朝禮，旧典时巡只自难。"]', '诗', 'shi', '', NULL, '郊天迴 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('739cdb6a-c48b-457b-b4aa-ea2ad0f0040d', '溫泉宮', '溫泉宮', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["憶昔開元天地平，武皇十月幸華清。","山蒸陰火雲三素，日落溫泉雞一鳴。","綵羽鳥仙歌不死，翠霓童妾舞長生。","仍聞老叟垂黃髮，猶說龍髯縹緲情。"]', '["憶昔开元天地平，武皇十月幸华清。","山蒸陰火云三素，日落溫泉雞一鳴。","綵羽鸟仙歌不死，翠霓童妾舞长生。","仍闻老叟垂黄髮，猶说龙髯縹緲情。"]', '诗', 'shi', '', NULL, '溫泉宮 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97630b82-0b6e-4da0-aac1-0d77efa68e50', '寄歸', '寄归', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["塞草黃來見鴈稀，隴雲白後少人歸。","新絲強入未衰鬢，別淚應沾獨宿衣。","幾夕精誠拜初月，每秋河漢對空機。","更看出獵相思苦，不射秋田朝雉飛。"]', '["塞草黄来见鴈稀，隴云白後少人归。","新絲強入未衰鬢，別泪應沾独宿衣。","幾夕精誠拜初月，每秋河漢对空機。","更看出獵相思苦，不射秋田朝雉飞。"]', '诗', 'shi', '', NULL, '寄歸 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('018782aa-7f8e-4371-95c6-5f0be2c3e38d', '贈遠', '贈远', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["辛苦關西車騎官，幾年旌節客河蘭。","金泥舞虎精神暗，銀縷交龍氣色寒。","欲和古詩成竇錦，倍悲秋扇損齊紈。","莫勞鴈足傳書信，願向凌煙閣上看。"]', '["辛苦关西车騎官，幾年旌節客河蘭。","金泥舞虎精神暗，銀縷交龙氣色寒。","欲和古诗成竇錦，倍悲秋扇損齊紈。","莫勞鴈足傳书信，願向凌煙閣上看。"]', '诗', 'shi', '', NULL, '贈遠 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d87585-5c8a-4ade-a64b-9406d7599c2c', '九日與友人登高', '九日與友人登高', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["雲木疎黃秋滿川，茱萸風裏一尊前。","幾迴爲客逢佳節，曾見何人再少年。","霜報征衣冷針指，雁驚幽夢淚嬋娟。","古來醉樂皆難得，留取窮通付上天。"]', '["云木疎黄秋满川，茱萸风裏一尊前。","幾迴爲客逢佳節，曾见何人再少年。","霜報征衣冷針指，雁驚幽梦泪嬋娟。","古来醉乐皆难得，留取窮通付上天。"]', '诗', 'shi', '', NULL, '九日與友人登高 鮑溶 shi');
